thread_local! {
    static SIDECAR_LOCK_WAIT_MICROS: Cell<u128> = const { Cell::new(0) };
}

fn seconds_from_micros(micros: u128) -> f64 {
    micros as f64 / 1_000_000.0
}

fn compressed_mib_per_second(compressed_bytes: u64, elapsed_seconds: f64) -> f64 {
    if elapsed_seconds <= 0.0 {
        return 0.0;
    }
    compressed_bytes as f64 / (1024.0 * 1024.0) / elapsed_seconds
}

fn lock_manifest_sidecars(
    sidecars: &Arc<Mutex<ManifestSidecarCollector>>,
) -> MutexGuard<'_, ManifestSidecarCollector> {
    let started_at = Instant::now();
    let guard = sidecars.lock().unwrap();
    let waited = started_at.elapsed().as_micros();
    SIDECAR_LOCK_WAIT_MICROS.with(|total| total.set(total.get().saturating_add(waited)));
    guard
}

fn take_sidecar_lock_wait_micros() -> u128 {
    SIDECAR_LOCK_WAIT_MICROS.with(|total| total.replace(0))
}

fn to_io_error(error: impl Display) -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, error.to_string())
}

fn compact_pipeline_error(
    worker_error: Option<io::Error>,
    producer_error: Option<io::Error>,
) -> Option<io::Error> {
    match (worker_error, producer_error) {
        (Some(error), Some(producer_error))
            if matches!(
                producer_error.kind(),
                io::ErrorKind::Interrupted | io::ErrorKind::BrokenPipe
            ) =>
        {
            Some(error)
        }
        (_, Some(error)) | (Some(error), None) => Some(error),
        (None, None) => None,
    }
}

fn capture_producer_error(cancelled: &AtomicBool, result: io::Result<()>) -> Option<io::Error> {
    match result {
        Ok(()) => None,
        Err(error) => {
            cancelled.store(true, Ordering::Release);
            Some(error)
        }
    }
}

fn primary_producer_failure_diagnostic(error: &io::Error) -> Option<String> {
    if matches!(
        error.kind(),
        io::ErrorKind::Interrupted | io::ErrorKind::BrokenPipe
    ) {
        return None;
    }
    Some(format!(
        "PTG2_SCANNER_PRIMARY_FAILED\ttype=producer_error\terror={error}"
    ))
}

fn scan(path: &Path, requested: &[String]) -> io::Result<()> {
    let mut targets: HashMap<Vec<u8>, String> = HashMap::new();
    for name in requested {
        targets.insert(name.as_bytes().to_vec(), name.clone());
    }

    let total_bytes = path.metadata().map(|metadata| metadata.len()).unwrap_or(0);
    let compressed_bytes_read = Arc::new(AtomicU64::new(0));
    let mut reader = open_json_reader(path, Arc::clone(&compressed_bytes_read))?;
    let stdout = io::stdout();
    let mut writer = BufWriter::new(stdout.lock());
    let mut buffer = vec![0u8; READ_BUF_SIZE];
    let progress_bytes_interval = progress_interval(
        "HLTHPRT_PTG2_SCANNER_PROGRESS_BYTES",
        DEFAULT_PROGRESS_BYTES,
    );
    let progress_objects_interval = progress_interval(
        "HLTHPRT_PTG2_SCANNER_PROGRESS_OBJECTS",
        DEFAULT_PROGRESS_OBJECTS,
    );
    let mut next_progress_bytes = progress_bytes_interval;
    let mut next_progress_objects = progress_objects_interval;
    let mut object_counts: HashMap<String, u64> = HashMap::new();
    let started_at = Instant::now();
    let mut depth: usize = 0;
    let mut active_name: Option<String> = None;
    let mut active_array_depth: usize = 0;
    let mut capture: Vec<u8> = Vec::new();
    let mut capture_depth: usize = 0;
    let mut in_string = false;
    let mut escape = false;
    let mut string_buffer: Option<Vec<u8>> = None;
    let mut candidate_key: Option<Vec<u8>> = None;
    let mut pending_key: Option<Vec<u8>> = None;

    loop {
        let read = reader.read(&mut buffer)?;
        if read == 0 {
            break;
        }
        for &byte in &buffer[..read] {
            if capture_depth > 0 {
                capture.push(byte);
            }

            if in_string {
                if let Some(ref mut string_buf) = string_buffer {
                    string_buf.push(byte);
                }
                if escape {
                    escape = false;
                } else if byte == b'\\' {
                    escape = true;
                } else if byte == b'"' {
                    in_string = false;
                    if let Some(mut string_buf) = string_buffer.take() {
                        if string_buf.last() == Some(&b'"') {
                            string_buf.pop();
                        }
                        candidate_key = Some(string_buf);
                    }
                }
                continue;
            }

            if byte == b'"' {
                in_string = true;
                escape = false;
                if depth == 1 && active_name.is_none() && capture_depth == 0 {
                    string_buffer = Some(Vec::new());
                } else {
                    string_buffer = None;
                }
                continue;
            }

            if let Some(candidate) = candidate_key.take() {
                if byte.is_ascii_whitespace() {
                    candidate_key = Some(candidate);
                    continue;
                }
                if byte == b':' {
                    pending_key = Some(candidate);
                    continue;
                }
            }

            if let Some(pending) = pending_key.take() {
                if byte.is_ascii_whitespace() {
                    pending_key = Some(pending);
                    continue;
                }
                if byte == b'[' && targets.contains_key(&pending) && depth == 1 {
                    depth += 1;
                    active_name = targets.get(&pending).cloned();
                    active_array_depth = depth;
                    continue;
                }
            }

            if active_name.is_some()
                && capture_depth == 0
                && byte == b'{'
                && depth == active_array_depth
            {
                capture.clear();
                capture.push(b'{');
                capture_depth = 1;
                depth += 1;
                continue;
            }

            match byte {
                b'{' | b'[' => {
                    if capture_depth > 0 {
                        capture_depth += 1;
                    }
                    depth += 1;
                }
                b'}' | b']' => {
                    if capture_depth > 0 {
                        capture_depth -= 1;
                        if capture_depth == 0 {
                            if let Some(ref name) = active_name {
                                emit_object(&mut writer, name, &capture)?;
                                let count = object_counts.entry(name.clone()).or_insert(0);
                                *count += 1;
                                let objects: u64 = object_counts.values().sum();
                                let bytes = compressed_bytes_read.load(Ordering::Relaxed);
                                if progress_bytes_interval > 0 && bytes >= next_progress_bytes {
                                    emit_progress(
                                        path,
                                        total_bytes,
                                        &compressed_bytes_read,
                                        &object_counts,
                                        started_at,
                                        false,
                                    );
                                    while bytes >= next_progress_bytes {
                                        next_progress_bytes += progress_bytes_interval;
                                    }
                                } else if progress_objects_interval > 0
                                    && objects >= next_progress_objects
                                {
                                    emit_progress(
                                        path,
                                        total_bytes,
                                        &compressed_bytes_read,
                                        &object_counts,
                                        started_at,
                                        false,
                                    );
                                    while objects >= next_progress_objects {
                                        next_progress_objects += progress_objects_interval;
                                    }
                                }
                            }
                            capture.clear();
                            depth = depth.saturating_sub(1);
                            continue;
                        }
                    }
                    if active_name.is_some() && byte == b']' && depth == active_array_depth {
                        active_name = None;
                        active_array_depth = 0;
                    }
                    depth = depth.saturating_sub(1);
                }
                _ => {}
            }
        }
    }
    writer.flush()?;
    emit_progress(
        path,
        total_bytes,
        &compressed_bytes_read,
        &object_counts,
        started_at,
        true,
    );
    Ok(())
}

#[derive(Clone, Debug)]
struct ProviderEntry {
    entry_hash: i64,
    provider_group_scope_hash: i64,
    provider_count: i64,
    provider_group_hashes: Vec<i64>,
    npi: Vec<i64>,
    quarantined_npi: Vec<i64>,
    quarantined_npi_text: Vec<String>,
    network_names: Vec<String>,
    source_locators: Vec<ProviderSourceLocator>,
}

impl PartialEq for ProviderEntry {
    fn eq(&self, other: &Self) -> bool {
        self.entry_hash == other.entry_hash
            && self.provider_group_scope_hash == other.provider_group_scope_hash
            && self.provider_count == other.provider_count
            && self.provider_group_hashes == other.provider_group_hashes
            && self.npi == other.npi
            && self.quarantined_npi == other.quarantined_npi
            && self.quarantined_npi_text == other.quarantined_npi_text
            && self.network_names == other.network_names
    }
}

impl Eq for ProviderEntry {}

const PROVIDER_GROUP_CONFLICT_HASH_DOMAIN: &[u8] = b"PTG2_PROVIDER_GROUP_CONFLICT_SOURCE_ID_V1\0";
const PROVIDER_GROUP_DEFINITION_HASH_DOMAIN: &[u8] =
    b"PTG2_PROVIDER_GROUP_CONFLICT_DEFINITION_V1\0";
const MAX_PROVIDER_GROUP_CONFLICTS: usize = 1024;
const MAX_PROVIDER_GROUP_CONFLICTING_DEFINITIONS: usize = 4096;

#[derive(Clone, Debug, Eq, Hash, PartialEq)]
enum ProviderRefKey {
    Signed(i64),
    Unsigned(u64),
    Text(Box<str>),
}

impl ProviderRefKey {
    fn from_number(number: serde_json::Number, field_name: &str) -> io::Result<Self> {
        if let Some(value) = number.as_i64() {
            return Ok(Self::Signed(value));
        }
        if let Some(value) = number.as_u64() {
            return Ok(Self::Unsigned(value));
        }
        let canonical = strict_integer_text(&Value::Number(number), field_name)?;
        Ok(Self::from(canonical))
    }
}

impl From<String> for ProviderRefKey {
    fn from(value: String) -> Self {
        if let Ok(integer) = value.parse::<i64>() {
            Self::Signed(integer)
        } else if let Ok(integer) = value.parse::<u64>() {
            Self::Unsigned(integer)
        } else {
            Self::Text(value.into_boxed_str())
        }
    }
}

impl From<&str> for ProviderRefKey {
    fn from(value: &str) -> Self {
        Self::from(value.to_owned())
    }
}

impl std::fmt::Display for ProviderRefKey {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Signed(value) => value.fmt(formatter),
            Self::Unsigned(value) => value.fmt(formatter),
            Self::Text(value) => value.fmt(formatter),
        }
    }
}

fn domain_sha256_hex(domain: &[u8], payload: &[u8]) -> String {
    let mut digest = Sha256::new();
    digest.update(domain);
    digest.update(payload);
    digest
        .finalize()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

fn provider_ref_key_sha256(raw_source_sha256: &[u8; 32], key: &ProviderRefKey) -> String {
    let mut digest = Sha256::new();
    digest.update(PROVIDER_GROUP_CONFLICT_HASH_DOMAIN);
    digest.update(raw_source_sha256);
    digest.update(key.to_string().as_bytes());
    digest
        .finalize()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

fn provider_entry_definition_sha256(entry: &ProviderEntry) -> io::Result<String> {
    let payload = serde_json::to_vec(&json!({
        "entry_hash": entry.entry_hash,
        "network_names": entry.network_names,
        "npi": entry.npi,
        "provider_count": entry.provider_count,
        "provider_group_hashes": entry.provider_group_hashes,
        "provider_group_scope_hash": entry.provider_group_scope_hash,
        "quarantined_npi": entry.quarantined_npi,
        "quarantined_npi_text": entry.quarantined_npi_text,
    }))
    .map_err(to_io_error)?;
    Ok(domain_sha256_hex(
        PROVIDER_GROUP_DEFINITION_HASH_DOMAIN,
        &payload,
    ))
}

#[derive(Clone, Debug, Default, Eq, PartialEq)]
struct ProviderGroupDefinitionConflicts {
    definitions_by_key: HashMap<ProviderRefKey, BTreeMap<i64, ProviderEntry>>,
    definition_count: usize,
}

impl ProviderGroupDefinitionConflicts {
    fn record_entry(&mut self, key: ProviderRefKey, entry: ProviderEntry) -> io::Result<()> {
        if !self.definitions_by_key.contains_key(&key)
            && self.definitions_by_key.len() >= MAX_PROVIDER_GROUP_CONFLICTS
        {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "provider group conflicts exceed 1024 identifiers",
            ));
        }
        let scope_hash = entry.provider_group_scope_hash;
        let definitions = self.definitions_by_key.entry(key).or_default();
        if let Some(existing) = definitions.get(&scope_hash).cloned() {
            if existing != entry {
                definitions.insert(scope_hash, combine_provider_entries(existing, entry));
            }
            return Ok(());
        }
        if self.definition_count >= MAX_PROVIDER_GROUP_CONFLICTING_DEFINITIONS {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "provider group conflicts exceed 4096 definitions",
            ));
        }
        definitions.insert(scope_hash, entry);
        self.definition_count += 1;
        Ok(())
    }

    fn keys(&self) -> HashSet<ProviderRefKey> {
        self.definitions_by_key.keys().cloned().collect()
    }

    fn payload(&self, raw_source_sha256: &[u8; 32]) -> io::Result<Vec<(String, BTreeSet<String>)>> {
        let mut entries = self
            .definitions_by_key
            .iter()
            .map(|(key, definitions)| -> io::Result<_> {
                if definitions.len() < 2 {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "provider group conflict has fewer than two definitions",
                    ));
                }
                let definition_sha256 = definitions
                    .values()
                    .map(provider_entry_definition_sha256)
                    .collect::<io::Result<BTreeSet<_>>>()?;
                if definition_sha256.len() < 2 {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "provider group conflict definitions are not distinct",
                    ));
                }
                Ok((
                    provider_ref_key_sha256(raw_source_sha256, key),
                    definition_sha256,
                ))
            })
            .collect::<io::Result<Vec<_>>>()?;
        entries.sort_unstable_by(|left, right| left.0.cmp(&right.0).then(left.1.cmp(&right.1)));
        Ok(entries)
    }
}

#[derive(Clone, Debug, Default, Eq, PartialEq)]
struct ProviderDefinitions {
    definitions_by_key: HashMap<ProviderRefKey, BTreeMap<i64, BTreeMap<String, ProviderEntry>>>,
    conflict_count: usize,
    conflicting_definition_count: usize,
}

impl ProviderDefinitions {
    fn insert(&mut self, key: ProviderRefKey, mut entry: ProviderEntry) -> io::Result<()> {
        let definition_sha256 = provider_entry_definition_sha256(&entry)?;
        let scope_hash = entry.provider_group_scope_hash;
        let prior_scope_count = self.definitions_by_key.get(&key).map_or(0, BTreeMap::len);
        let is_new_scope = !self
            .definitions_by_key
            .get(&key)
            .is_some_and(|scopes| scopes.contains_key(&scope_hash));
        if is_new_scope {
            let next_conflict_count = self
                .conflict_count
                .saturating_add(usize::from(prior_scope_count == 1));
            let next_definition_count =
                self.conflicting_definition_count
                    .saturating_add(match prior_scope_count {
                        0 => 0,
                        1 => 2,
                        _ => 1,
                    });
            if next_conflict_count > MAX_PROVIDER_GROUP_CONFLICTS {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "provider group conflicts exceed 1024 identifiers",
                ));
            }
            if next_definition_count > MAX_PROVIDER_GROUP_CONFLICTING_DEFINITIONS {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "provider group conflicts exceed 4096 definitions",
                ));
            }
            self.conflict_count = next_conflict_count;
            self.conflicting_definition_count = next_definition_count;
        }
        let definitions = self
            .definitions_by_key
            .entry(key)
            .or_default()
            .entry(scope_hash)
            .or_default();
        if let Some(existing) = definitions.get_mut(&definition_sha256) {
            if *existing != entry {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "provider definition digest collision",
                ));
            }
            existing.source_locators.append(&mut entry.source_locators);
            existing
                .source_locators
                .sort_unstable_by_key(|locator| (locator.shard, locator.offset, locator.length));
            existing.source_locators.dedup();
            existing.source_locators.truncate(1);
            return Ok(());
        }
        entry
            .source_locators
            .sort_unstable_by_key(|locator| (locator.shard, locator.offset, locator.length));
        entry.source_locators.dedup();
        entry.source_locators.truncate(1);
        definitions.insert(definition_sha256, entry);
        Ok(())
    }

    fn into_materialized(
        self,
    ) -> io::Result<(
        HashMap<ProviderRefKey, ProviderEntry>,
        ProviderGroupDefinitionConflicts,
    )> {
        let mut provider_map = HashMap::new();
        let mut conflicts = ProviderGroupDefinitionConflicts::default();
        for (key, scopes) in self.definitions_by_key {
            let is_conflict = scopes.len() > 1;
            for definitions in scopes.into_values() {
                let mut entries = definitions.into_values();
                let first = entries.next().ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "provider definition scope is empty",
                    )
                })?;
                let entry = entries.fold(first, combine_provider_entries);
                if is_conflict {
                    conflicts.record_entry(key.clone(), entry)?;
                } else {
                    provider_map.insert(key.clone(), entry);
                }
            }
        }
        Ok((provider_map, conflicts))
    }
}

enum ProviderEntryView<'a> {
    Borrowed(&'a ProviderEntry),
    Owned(ProviderEntry),
}

impl<'a> ProviderEntryView<'a> {
    fn entry_hash(&self) -> i64 {
        match self {
            Self::Borrowed(entry) => entry.entry_hash,
            Self::Owned(entry) => entry.entry_hash,
        }
    }

    fn provider_count(&self) -> i64 {
        match self {
            Self::Borrowed(entry) => entry.provider_count,
            Self::Owned(entry) => entry.provider_count,
        }
    }

    fn provider_group_hashes(&self) -> &[i64] {
        match self {
            Self::Borrowed(entry) => &entry.provider_group_hashes,
            Self::Owned(entry) => &entry.provider_group_hashes,
        }
    }

    fn npi(&self) -> &[i64] {
        match self {
            Self::Borrowed(entry) => &entry.npi,
            Self::Owned(entry) => &entry.npi,
        }
    }

    fn network_names(&self) -> &[String] {
        match self {
            Self::Borrowed(entry) => &entry.network_names,
            Self::Owned(entry) => &entry.network_names,
        }
    }
}

#[derive(Clone, Debug)]
struct RateLite {
    provider_refs: Vec<ProviderRefKey>,
    provider_groups: Vec<Value>,
    provider_groups_raw: Option<Box<RawValue>>,
    network_names: Vec<String>,
    prices: Vec<PriceLite>,
    prepared_price_set: Option<PriceSetLite>,
}

impl PartialEq for RateLite {
    fn eq(&self, other: &Self) -> bool {
        self.provider_refs == other.provider_refs
            && self.provider_groups == other.provider_groups
            && self.provider_groups_raw.as_deref().map(RawValue::get)
                == other.provider_groups_raw.as_deref().map(RawValue::get)
            && self.network_names == other.network_names
            && self.prices == other.prices
            && self.prepared_price_set == other.prepared_price_set
    }
}

impl Eq for RateLite {}

impl RateLite {
    fn price_count(&self) -> usize {
        self.prepared_price_set
            .as_ref()
            .map_or(self.prices.len(), |price_set| price_set.atoms.len())
    }

    fn has_inline_provider_groups(&self) -> bool {
        self.provider_groups_raw
            .as_deref()
            .is_some_and(|raw| !raw_provider_groups_is_empty(raw))
            || !self.provider_groups.is_empty()
    }
}

