fn npi_source_coordinate(groups: &[Value], selected_npi: i64) -> Option<(usize, usize)> {
    for (group_ordinal, group) in groups.iter().enumerate() {
        let npi_values = group.get("npi")?.as_array()?;
        for (npi_ordinal, raw_npi) in npi_values.iter().enumerate() {
            if strict_npi_integer(raw_npi, "provider group npi element").ok() == Some(selected_npi)
            {
                return Some((group_ordinal, npi_ordinal));
            }
        }
    }
    None
}

fn linked_provider_source_evidence(
    rate: &RateLite,
    inline_provider_groups: &[Value],
    provider_map: &HashMap<ProviderRefKey, ProviderEntry>,
    context: &CompactContext,
    selected_npi: i64,
) -> io::Result<(Value, Option<ProviderSourceLocator>, Option<[u8; 32]>)> {
    if let Some((group_ordinal, npi_ordinal)) =
        npi_source_coordinate(inline_provider_groups, selected_npi)
    {
        return Ok((
            json!({
                "source_kind": "inline_provider_group",
                "provider_group_ordinal": group_ordinal,
                "npi_ordinal": npi_ordinal,
            }),
            None,
            None,
        ));
    }
    for provider_reference in &rate.provider_refs {
        let provider_entry = provider_map.get(provider_reference).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!("unresolved provider reference: {provider_reference}"),
            )
        })?;
        if provider_entry.npi.binary_search(&selected_npi).is_err() {
            continue;
        }
        if provider_entry.source_locators.is_empty() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "queryable source occurrence is missing linked provider evidence",
            ));
        }
        for locator in provider_entry.source_locators.iter().copied() {
            let raw_provider = context.source_witness.read_provider_source(locator)?;
            let provider_value = parse_json_value_from_raw_bytes(&raw_provider)?;
            let provider_group_id = provider_value.get("provider_group_id").ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "linked provider evidence is missing provider_group_id",
                )
            })?;
            if provider_ref_key(provider_group_id)? != *provider_reference {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "linked provider evidence has a mismatched provider_group_id",
                ));
            }
            let groups = provider_value
                .get("provider_groups")
                .and_then(Value::as_array)
                .ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "linked provider evidence is missing provider_groups",
                    )
                })?;
            let Some((group_ordinal, npi_ordinal)) = npi_source_coordinate(groups, selected_npi)
            else {
                continue;
            };
            return Ok((
                json!({
                    "source_kind": "provider_reference",
                    "provider_reference_id": provider_reference.to_string(),
                    "provider_group_ordinal": group_ordinal,
                    "npi_ordinal": npi_ordinal,
                }),
                Some(locator),
                Some(Sha256::digest(&raw_provider).into()),
            ));
        }
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "linked provider evidence does not contain the selected NPI",
        ));
    }
    Err(io::Error::new(
        io::ErrorKind::InvalidData,
        "selected source occurrence NPI has no raw provider evidence",
    ))
}

#[derive(Clone, Copy)]
enum EmittedProviderNpis<'a> {
    Exact(&'a [i64]),
    Factor {
        provider_count: u64,
        inline_npis: &'a [i64],
    },
}

impl EmittedProviderNpis<'_> {
    fn len(self) -> u64 {
        match self {
            Self::Exact(npis) => u64::try_from(npis.len()).unwrap_or(u64::MAX),
            Self::Factor { provider_count, .. } => provider_count,
        }
    }

    fn nth(
        self,
        ordinal: u64,
        rate: &RateLite,
        provider_map: &HashMap<ProviderRefKey, ProviderEntry>,
    ) -> io::Result<i64> {
        match self {
            Self::Exact(npis) => {
                let Some(npi) = npis.get(ordinal as usize).copied() else {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "source witness NPI ordinal is outside the exact provider set",
                    ));
                };
                Ok(npi)
            }
            Self::Factor { inline_npis, .. } => {
                let mut lists = Vec::with_capacity(
                    rate.provider_refs.len() + usize::from(!inline_npis.is_empty()),
                );
                for key in &rate.provider_refs {
                    let Some(entry) = provider_map.get(key) else {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidData,
                            format!("unresolved provider reference: {key}"),
                        ));
                    };
                    lists.push(entry.npi.as_slice());
                }
                if !inline_npis.is_empty() {
                    lists.push(inline_npis);
                }
                let Some(npi) = sorted_unique_i64_nth(&lists, ordinal) else {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "source witness NPI ordinal is outside the factored provider set",
                    ));
                };
                Ok(npi)
            }
        }
    }
}

struct EmittedSourceRateWitnessInput<'a> {
    procedure: &'a Map<String, Value>,
    rate: &'a RateLite,
    inline_provider_groups: &'a [Value],
    emitted_provider_npis: EmittedProviderNpis<'a>,
    emitted_price_count: usize,
    provider_map: &'a HashMap<ProviderRefKey, ProviderEntry>,
    context: &'a CompactContext,
    coordinate: SourceWitnessCoordinate,
    procedure_json: &'a [u8],
    raw_rate: &'a [u8],
    population_delta: &'a mut SourceWitnessPopulationDelta,
}

fn capture_emitted_source_rate_occurrences(
    input: EmittedSourceRateWitnessInput<'_>,
) -> io::Result<()> {
    let EmittedSourceRateWitnessInput {
        procedure,
        rate,
        inline_provider_groups,
        emitted_provider_npis,
        emitted_price_count,
        provider_map,
        context,
        coordinate,
        procedure_json,
        raw_rate,
        population_delta,
    } = input;
    if emitted_price_count != rate.price_count() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "source witness price population differs from emitted V3 prices",
        ));
    }
    if emitted_provider_npis.len() == 0 || emitted_price_count == 0 {
        return population_delta.record_rate(0);
    }
    let provider_count = emitted_provider_npis.len();
    let price_count = u64::try_from(emitted_price_count).map_err(to_io_error)?;
    let occurrence_count = provider_count.checked_mul(price_count).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "queryable source occurrence population overflow",
        )
    })?;
    population_delta.record_rate(occurrence_count)?;
    let candidates = context
        .source_witness
        .rate_occurrence_candidates_untracked(
            coordinate,
            procedure_json,
            raw_rate,
            occurrence_count,
        )?;
    if candidates.is_empty() {
        return Ok(());
    }
    let rate_source_locator = context
        .source_witness
        .store_rate_source(coordinate, procedure, raw_rate)?;
    let price_set = rate_price_set(rate).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "source witness rate is missing its emitted price set",
        )
    })?;
    for candidate in candidates {
        let emitted_price_ordinal = candidate.occurrence_index / provider_count;
        let price_ordinal = price_set
            .as_ref()
            .atoms
            .get(emitted_price_ordinal as usize)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "source witness price ordinal is outside the emitted price set",
                )
            })?
            .source_ordinal;
        let provider_ordinal = candidate.occurrence_index % provider_count;
        let selected_npi = emitted_provider_npis.nth(provider_ordinal, rate, provider_map)?;
        let (provider_evidence, linked_provider_locator, linked_provider_sha256) =
            linked_provider_source_evidence(
                rate,
                inline_provider_groups,
                provider_map,
                context,
                selected_npi,
            )?;
        context
            .source_witness
            .commit_rate_occurrence(RateOccurrenceWitnessInput {
                candidate,
                coordinate,
                price_ordinal,
                provider_ordinal,
                provider_evidence: &provider_evidence,
                rate_source_locator,
                raw_rate,
                linked_provider_locator,
                linked_provider_sha256,
                expected: &source_rate_witness_expected(),
            })?;
    }
    Ok(())
}

