const V4_PROVIDER_FACTOR_CACHE_SHARDS: usize = 64;
const DEFAULT_V4_PROVIDER_FACTOR_CACHE_MAX_BYTES: usize = 1024 * 1024 * 1024;
const V4_INLINE_PROVIDER_TRANSFORM_CACHE_SHARDS: usize = 16;
const DEFAULT_V4_INLINE_PROVIDER_TRANSFORM_CACHE_MAX_BYTES: usize = 256 * 1024 * 1024;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum V4InlineProviderTransformCacheKeyKind {
    ExactRawJson,
    ParsedCanonicalJson,
}

fn v4_inline_provider_transform_digest(
    kind: V4InlineProviderTransformCacheKeyKind,
    bytes: &[u8],
) -> u64 {
    let mut hasher = Xxh3::new();
    hasher.update(b"ptg2_v4_inline_provider_groups_raw_v1");
    hasher.update(&[match kind {
        V4InlineProviderTransformCacheKeyKind::ExactRawJson => 1,
        V4InlineProviderTransformCacheKeyKind::ParsedCanonicalJson => 2,
    }]);
    hasher.update(&(bytes.len() as u64).to_le_bytes());
    hasher.update(bytes);
    hasher.digest()
}

#[derive(Debug)]
struct V4InlineProviderTransform {
    cache_key_kind: V4InlineProviderTransformCacheKeyKind,
    cache_key: Arc<[u8]>,
    provider_groups: Arc<[Value]>,
    entry: ProviderEntry,
    empty_npi_tin_only_normalization_count: u64,
    provider_group_attempts: u64,
}

fn estimated_json_value_heap_bytes(value: &Value) -> u64 {
    match value {
        Value::Null | Value::Bool(_) | Value::Number(_) => 0,
        Value::String(value) => value.capacity() as u64,
        Value::Array(values) => {
            (values.capacity() * std::mem::size_of::<Value>()) as u64
                + values
                    .iter()
                    .map(estimated_json_value_heap_bytes)
                    .sum::<u64>()
        }
        Value::Object(values) => values
            .iter()
            .map(|(key, value)| {
                (std::mem::size_of::<String>() + std::mem::size_of::<Value>() + 64) as u64
                    + key.capacity() as u64
                    + estimated_json_value_heap_bytes(value)
            })
            .sum(),
    }
}

fn estimated_v4_inline_provider_transform_bytes(transform: &V4InlineProviderTransform) -> u64 {
    let network_name_bytes = transform
        .entry
        .network_names
        .iter()
        .map(|value| value.capacity() as u64)
        .sum::<u64>();
    let quarantined_npi_text_bytes = transform
        .entry
        .quarantined_npi_text
        .iter()
        .map(|value| value.capacity() as u64)
        .sum::<u64>();
    (std::mem::size_of::<V4InlineProviderTransform>() as u64)
        .saturating_add(transform.cache_key.len() as u64)
        .saturating_add((transform.provider_groups.len() * std::mem::size_of::<Value>()) as u64)
        .saturating_add(
            transform
                .provider_groups
                .iter()
                .map(estimated_json_value_heap_bytes)
                .sum::<u64>(),
        )
        .saturating_add(
            (transform.entry.provider_group_hashes.capacity() * std::mem::size_of::<i64>()) as u64,
        )
        .saturating_add((transform.entry.npi.capacity() * std::mem::size_of::<i64>()) as u64)
        .saturating_add(
            (transform.entry.quarantined_npi.capacity() * std::mem::size_of::<i64>()) as u64,
        )
        .saturating_add(
            (transform.entry.quarantined_npi_text.capacity() * std::mem::size_of::<String>())
                as u64,
        )
        .saturating_add(quarantined_npi_text_bytes)
        .saturating_add(
            (transform.entry.network_names.capacity() * std::mem::size_of::<String>()) as u64,
        )
        .saturating_add(network_name_bytes)
        // Conservatively cover the Arc, collision bucket, and HashMap entry.
        .saturating_add(512)
}

#[derive(Default)]
struct V4InlineProviderTransformCacheShard {
    buckets: HashMap<u64, Vec<Arc<V4InlineProviderTransform>>>,
    entry_count: u64,
    estimated_bytes: u64,
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct V4InlineProviderTransformCacheSnapshot {
    hits: u64,
    misses: u64,
    transforms: u64,
    evictions: u64,
    evicted_entries: u64,
    bypasses: u64,
    entries: u64,
    estimated_bytes: u64,
    peak_estimated_bytes: u64,
    max_estimated_bytes: u64,
}

struct V4InlineProviderTransformSharedCache {
    shards: Vec<Mutex<V4InlineProviderTransformCacheShard>>,
    shard_max_estimated_bytes: Vec<u64>,
    hits: AtomicU64,
    misses: AtomicU64,
    transforms: AtomicU64,
    evictions: AtomicU64,
    evicted_entries: AtomicU64,
    bypasses: AtomicU64,
    entry_count: AtomicU64,
    estimated_bytes: AtomicU64,
    peak_estimated_bytes: AtomicU64,
    max_estimated_bytes: u64,
}

impl V4InlineProviderTransformSharedCache {
    fn configured() -> io::Result<Self> {
        let name = "HLTHPRT_PTG2_V4_INLINE_TRANSFORM_CACHE_MAX_BYTES";
        let max_bytes = match env::var(name) {
            Ok(raw) => raw.trim().parse::<u64>().map_err(|_| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("{name} must be a non-negative integer byte count"),
                )
            })?,
            Err(env::VarError::NotPresent) => {
                DEFAULT_V4_INLINE_PROVIDER_TRANSFORM_CACHE_MAX_BYTES as u64
            }
            Err(error) => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("{name} is unreadable: {error}"),
                ));
            }
        };
        Ok(Self::new(max_bytes))
    }

    fn new(max_estimated_bytes: u64) -> Self {
        Self::new_with_shards(
            max_estimated_bytes,
            V4_INLINE_PROVIDER_TRANSFORM_CACHE_SHARDS,
        )
    }

    fn new_with_shards(max_estimated_bytes: u64, shard_count: usize) -> Self {
        let shard_count = shard_count.max(1);
        let base = max_estimated_bytes / shard_count as u64;
        let remainder = max_estimated_bytes % shard_count as u64;
        let shard_max_estimated_bytes = (0..shard_count)
            .map(|index| base + u64::from((index as u64) < remainder))
            .collect();
        Self {
            shards: (0..shard_count)
                .map(|_| Mutex::new(V4InlineProviderTransformCacheShard::default()))
                .collect(),
            shard_max_estimated_bytes,
            hits: AtomicU64::new(0),
            misses: AtomicU64::new(0),
            transforms: AtomicU64::new(0),
            evictions: AtomicU64::new(0),
            evicted_entries: AtomicU64::new(0),
            bypasses: AtomicU64::new(0),
            entry_count: AtomicU64::new(0),
            estimated_bytes: AtomicU64::new(0),
            peak_estimated_bytes: AtomicU64::new(0),
            max_estimated_bytes,
        }
    }

    fn resolve_or_insert(
        &self,
        digest: u64,
        cache_key_kind: V4InlineProviderTransformCacheKeyKind,
        cache_key: &[u8],
        build: impl FnOnce() -> io::Result<(Vec<Value>, ProviderEntry, u64, u64)>,
    ) -> io::Result<(Arc<V4InlineProviderTransform>, bool)> {
        let shard_index = digest as usize % self.shards.len();
        let mut shard = self.shards[shard_index]
            .lock()
            .map_err(|_| io::Error::other("V4 inline transform cache lock poisoned"))?;
        if let Some(transform) = shard.buckets.get(&digest).and_then(|bucket| {
            bucket.iter().find(|entry| {
                entry.cache_key_kind == cache_key_kind && entry.cache_key.as_ref() == cache_key
            })
        }) {
            self.hits.fetch_add(1, Ordering::Relaxed);
            return Ok((Arc::clone(transform), true));
        }

        self.misses.fetch_add(1, Ordering::Relaxed);
        self.transforms.fetch_add(1, Ordering::Relaxed);
        let (
            provider_groups,
            entry,
            empty_npi_tin_only_normalization_count,
            provider_group_attempts,
        ) = build()?;
        let transform = Arc::new(V4InlineProviderTransform {
            cache_key_kind,
            cache_key: Arc::from(cache_key),
            provider_groups: provider_groups.into(),
            entry,
            empty_npi_tin_only_normalization_count,
            provider_group_attempts,
        });
        let estimated_bytes = estimated_v4_inline_provider_transform_bytes(&transform);
        let shard_max_estimated_bytes = self.shard_max_estimated_bytes[shard_index];
        if estimated_bytes > shard_max_estimated_bytes {
            self.bypasses.fetch_add(1, Ordering::Relaxed);
            return Ok((transform, false));
        }

        if shard.estimated_bytes.saturating_add(estimated_bytes) > shard_max_estimated_bytes {
            let evicted_entries = shard.entry_count;
            let evicted_bytes = shard.estimated_bytes;
            shard.buckets.clear();
            shard.entry_count = 0;
            shard.estimated_bytes = 0;
            self.entry_count
                .fetch_sub(evicted_entries, Ordering::AcqRel);
            self.estimated_bytes
                .fetch_sub(evicted_bytes, Ordering::AcqRel);
            self.evictions.fetch_add(1, Ordering::Relaxed);
            self.evicted_entries
                .fetch_add(evicted_entries, Ordering::Relaxed);
        }

        shard
            .buckets
            .entry(digest)
            .or_default()
            .push(Arc::clone(&transform));
        shard.entry_count = shard.entry_count.saturating_add(1);
        shard.estimated_bytes = shard.estimated_bytes.saturating_add(estimated_bytes);
        self.entry_count.fetch_add(1, Ordering::AcqRel);
        let total_estimated_bytes = self
            .estimated_bytes
            .fetch_add(estimated_bytes, Ordering::AcqRel)
            .saturating_add(estimated_bytes);
        self.peak_estimated_bytes
            .fetch_max(total_estimated_bytes, Ordering::AcqRel);
        debug_assert!(total_estimated_bytes <= self.max_estimated_bytes);
        Ok((transform, false))
    }

    fn snapshot(&self) -> V4InlineProviderTransformCacheSnapshot {
        V4InlineProviderTransformCacheSnapshot {
            hits: self.hits.load(Ordering::Acquire),
            misses: self.misses.load(Ordering::Acquire),
            transforms: self.transforms.load(Ordering::Acquire),
            evictions: self.evictions.load(Ordering::Acquire),
            evicted_entries: self.evicted_entries.load(Ordering::Acquire),
            bypasses: self.bypasses.load(Ordering::Acquire),
            entries: self.entry_count.load(Ordering::Acquire),
            estimated_bytes: self.estimated_bytes.load(Ordering::Acquire),
            peak_estimated_bytes: self.peak_estimated_bytes.load(Ordering::Acquire),
            max_estimated_bytes: self.max_estimated_bytes,
        }
    }
}

struct V4ProviderSetFactorSharedCache {
    buckets: Vec<Mutex<HashMap<i64, Vec<Arc<V4ProviderSetFactorCacheEntry>>>>>,
    entry_count: AtomicU64,
    estimated_bytes: AtomicU64,
    max_estimated_bytes: u64,
    semantic_progress: Option<Arc<ScannerSemanticProgress>>,
    inline_transforms: V4InlineProviderTransformSharedCache,
}

impl V4ProviderSetFactorSharedCache {
    #[cfg(test)]
    fn configured() -> io::Result<Self> {
        Self::configured_for_mode(true)
    }

    fn configured_for_mode(provider_graph_v4_factor_mode: bool) -> io::Result<Self> {
        let name = "HLTHPRT_PTG2_V4_FACTOR_CACHE_MAX_BYTES";
        let max_bytes = match env::var(name) {
            Ok(raw) => {
                let Some(max_bytes) = raw.trim().parse::<u64>().ok().filter(|value| *value > 0)
                else {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        format!("{name} must be a positive integer byte count"),
                    ));
                };
                max_bytes
            }
            Err(env::VarError::NotPresent) => DEFAULT_V4_PROVIDER_FACTOR_CACHE_MAX_BYTES as u64,
            Err(error) => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("{name} is unreadable: {error}"),
                ));
            }
        };
        let inline_transforms = if provider_graph_v4_factor_mode {
            V4InlineProviderTransformSharedCache::configured()?
        } else {
            V4InlineProviderTransformSharedCache::new(0)
        };
        Ok(Self::new_with_inline_transforms_for_mode(
            max_bytes,
            inline_transforms,
            provider_graph_v4_factor_mode,
        ))
    }

    fn new(max_estimated_bytes: u64) -> Self {
        Self::new_with_inline_transforms(
            max_estimated_bytes,
            V4InlineProviderTransformSharedCache::new(
                DEFAULT_V4_INLINE_PROVIDER_TRANSFORM_CACHE_MAX_BYTES as u64,
            ),
        )
    }

    fn new_with_inline_transforms(
        max_estimated_bytes: u64,
        inline_transforms: V4InlineProviderTransformSharedCache,
    ) -> Self {
        Self::new_with_inline_transforms_for_mode(max_estimated_bytes, inline_transforms, true)
    }

    fn new_with_inline_transforms_for_mode(
        max_estimated_bytes: u64,
        inline_transforms: V4InlineProviderTransformSharedCache,
        provider_graph_v4_factor_mode: bool,
    ) -> Self {
        Self {
            buckets: (0..V4_PROVIDER_FACTOR_CACHE_SHARDS)
                .map(|_| Mutex::new(HashMap::new()))
                .collect(),
            entry_count: AtomicU64::new(0),
            estimated_bytes: AtomicU64::new(0),
            max_estimated_bytes,
            semantic_progress: provider_graph_v4_factor_mode
                .then(|| Arc::new(ScannerSemanticProgress::default())),
            inline_transforms,
        }
    }

    fn insert_reserved_bytes(&self, amount: u64) -> io::Result<()> {
        let previous = self.estimated_bytes.fetch_add(amount, Ordering::AcqRel);
        if previous.saturating_add(amount) > self.max_estimated_bytes {
            self.estimated_bytes.fetch_sub(amount, Ordering::AcqRel);
            return Err(io::Error::new(
                io::ErrorKind::OutOfMemory,
                format!(
                    "V4 provider factor cache admission rejected estimated {} bytes above configured limit {}",
                    previous.saturating_add(amount),
                    self.max_estimated_bytes,
                ),
            ));
        }
        Ok(())
    }

    fn snapshot(&self) -> (u64, u64, u64) {
        (
            self.entry_count.load(Ordering::Acquire),
            self.estimated_bytes.load(Ordering::Acquire),
            self.max_estimated_bytes,
        )
    }

    fn semantic_progress_if_enabled(&self) -> Option<Arc<ScannerSemanticProgress>> {
        self.semantic_progress.as_ref().map(Arc::clone)
    }
}

struct V4ProviderSetFactorCache {
    enabled: bool,
    buckets: HashMap<i64, Vec<Arc<V4ProviderSetFactorCacheEntry>>>,
    shared: Arc<V4ProviderSetFactorSharedCache>,
    metrics: V4ProviderSetFactorMetrics,
}

impl V4ProviderSetFactorCache {
    fn new(enabled: bool, shared: Arc<V4ProviderSetFactorSharedCache>) -> Self {
        Self {
            enabled,
            buckets: HashMap::new(),
            shared,
            metrics: V4ProviderSetFactorMetrics::default(),
        }
    }

    fn resolve(
        &mut self,
        provider_map: &HashMap<ProviderRefKey, ProviderEntry>,
        provider_refs: &[ProviderRefKey],
        inline: Option<&ProviderEntry>,
        rate: &RateLite,
        context: &CompactContext,
    ) -> io::Result<Option<Arc<V4ProviderSetFactorCacheEntry>>> {
        debug_assert!(self.enabled);
        let semantic_progress = self
            .shared
            .semantic_progress
            .as_deref()
            .expect("enabled V4 factor cache must retain semantic progress");
        match (provider_refs.is_empty(), inline.is_some()) {
            (false, false) => {
                self.metrics.reference_only_rates =
                    self.metrics.reference_only_rates.saturating_add(1)
            }
            (true, true) => {
                self.metrics.inline_only_rates = self.metrics.inline_only_rates.saturating_add(1)
            }
            (false, true) => self.metrics.mixed_rates = self.metrics.mixed_rates.saturating_add(1),
            (true, false) => return Ok(None),
        }

        // Only component IDs and small network labels participate in the hot
        // cache probe. The exact group/NPI unions run only on a shared cache
        // miss and are streamed without retaining the expanded vectors.
        let mut component_hashes =
            Vec::with_capacity(provider_refs.len() + usize::from(inline.is_some()));
        let mut provider_network_names = Vec::new();
        let mut components = BTreeMap::new();
        for key in provider_refs {
            let Some(entry) = provider_map.get(key) else {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("unresolved provider reference: {key}"),
                ));
            };
            component_hashes.push(entry.entry_hash);
            provider_network_names.extend(entry.network_names.iter().cloned());
            components.entry(entry.entry_hash).or_insert(entry);
        }
        if let Some(entry) = inline {
            component_hashes.push(entry.entry_hash);
            provider_network_names.extend(entry.network_names.iter().cloned());
            components.entry(entry.entry_hash).or_insert(entry);
        }
        component_hashes.sort_unstable();
        component_hashes.dedup();
        provider_network_names = canonical_text_list(provider_network_names, false);
        if component_hashes.is_empty() {
            return Ok(None);
        }
        let network_names = rate_network_names(rate, &provider_network_names, context);
        let component_key =
            checksum_i64_list("provider_set_factor_components_v1", &component_hashes);
        let network_key = hash_string_list("provider_set_factor_networks_v1", &network_names);
        let mut key_payload = component_key.to_string();
        key_payload.push('\x1f');
        key_payload.push_str(&network_key);
        let bucket_key = xxh3_63(key_payload.as_bytes()) as i64;
        if let Some(entry_index) = self.buckets.get(&bucket_key).and_then(|bucket| {
            bucket.iter().position(|entry| {
                entry.component_hashes == component_hashes && entry.network_names == network_names
            })
        }) {
            self.metrics.cache_hits = self.metrics.cache_hits.saturating_add(1);
            return Ok(self
                .buckets
                .get(&bucket_key)
                .and_then(|bucket| bucket.get(entry_index))
                .cloned());
        }

        self.metrics.cache_misses = self.metrics.cache_misses.saturating_add(1);
        let shared_index = (bucket_key as u64 as usize) % self.shared.buckets.len();
        let mut shared_bucket = self.shared.buckets[shared_index].lock().unwrap();
        let shared_entry = if let Some(entry) = shared_bucket
            .get(&bucket_key)
            .and_then(|bucket| {
                bucket.iter().find(|entry| {
                    entry.component_hashes == component_hashes
                        && entry.network_names == network_names
                })
            })
            .cloned()
        {
            entry
        } else {
            let group_lists = components
                .values()
                .map(|entry| entry.provider_group_hashes.as_slice())
                .collect::<Vec<_>>();
            let npi_lists = components
                .values()
                .map(|entry| entry.npi.as_slice())
                .collect::<Vec<_>>();
            let (provider_set_hash, provider_set_global_id) =
                legacy_provider_set_identity_from_sorted_lists(
                    &group_lists,
                    &network_names,
                    semantic_progress,
                )?;
            let provider_count =
                i64::try_from(sorted_unique_i64_count_with_visits(&npi_lists, |amount| {
                    semantic_progress.record_provider_npi_union_visits(amount);
                }))
                .unwrap_or(i64::MAX);
            let entry = Arc::new(V4ProviderSetFactorCacheEntry {
                component_hashes: component_hashes.clone(),
                network_names: network_names.clone(),
                provider_set_hash,
                provider_set_global_id,
                provider_count,
            });
            let estimated_bytes = estimated_v4_factor_entry_bytes(&entry);
            self.shared.insert_reserved_bytes(estimated_bytes)?;
            shared_bucket
                .entry(bucket_key)
                .or_default()
                .push(Arc::clone(&entry));
            self.shared.entry_count.fetch_add(1, Ordering::AcqRel);
            self.metrics.flat_group_union_attempts =
                self.metrics.flat_group_union_attempts.saturating_add(1);
            self.metrics.npi_union_attempts = self.metrics.npi_union_attempts.saturating_add(1);
            entry
        };
        drop(shared_bucket);
        self.buckets
            .entry(bucket_key)
            .or_default()
            .push(Arc::clone(&shared_entry));
        Ok(Some(shared_entry))
    }
}

fn estimated_v4_factor_entry_bytes(entry: &V4ProviderSetFactorCacheEntry) -> u64 {
    let strings = entry
        .network_names
        .iter()
        .map(|value| value.capacity() as u64)
        .sum::<u64>();
    (std::mem::size_of::<V4ProviderSetFactorCacheEntry>() as u64)
        .saturating_add((entry.component_hashes.capacity() * std::mem::size_of::<i64>()) as u64)
        .saturating_add((entry.network_names.capacity() * std::mem::size_of::<String>()) as u64)
        .saturating_add(strings)
        .saturating_add(entry.provider_set_hash.capacity() as u64)
        // Conservatively cover the shared HashMap bucket plus per-worker
        // front-cache Arc/map entries without retaining any union members.
        .saturating_add(1024)
}

const SEMANTIC_UNION_VISIT_BATCH: u64 = 65_536;

fn for_each_sorted_unique_i64_with_visits(
    lists: &[&[i64]],
    mut consume: impl FnMut(i64),
    mut record_visits: impl FnMut(u64),
) -> u64 {
    let mut heap = BinaryHeap::new();
    for (list_index, list) in lists.iter().enumerate() {
        if let Some(&value) = list.first() {
            heap.push(Reverse((value, list_index, 0usize)));
        }
    }
    let mut previous = None;
    let mut count = 0u64;
    let mut pending_visits = 0u64;
    while let Some(Reverse((value, list_index, item_index))) = heap.pop() {
        pending_visits = pending_visits.saturating_add(1);
        if pending_visits >= SEMANTIC_UNION_VISIT_BATCH {
            record_visits(pending_visits);
            pending_visits = 0;
        }
        if previous != Some(value) {
            consume(value);
            count = count.saturating_add(1);
            previous = Some(value);
        }
        let next_index = item_index + 1;
        if let Some(&next) = lists[list_index].get(next_index) {
            heap.push(Reverse((next, list_index, next_index)));
        }
    }
    record_visits(pending_visits);
    count
}

fn sorted_unique_i64_count_with_visits(lists: &[&[i64]], record_visits: impl FnMut(u64)) -> u64 {
    for_each_sorted_unique_i64_with_visits(lists, |_| {}, record_visits)
}

fn sorted_unique_i64_nth(lists: &[&[i64]], wanted: u64) -> Option<i64> {
    let mut heap = BinaryHeap::new();
    for (list_index, list) in lists.iter().enumerate() {
        if let Some(&value) = list.first() {
            heap.push(Reverse((value, list_index, 0usize)));
        }
    }
    let mut previous = None;
    let mut ordinal = 0u64;
    while let Some(Reverse((value, list_index, item_index))) = heap.pop() {
        if previous != Some(value) {
            if ordinal == wanted {
                return Some(value);
            }
            ordinal = ordinal.saturating_add(1);
            previous = Some(value);
        }
        let next_index = item_index + 1;
        if let Some(&next) = lists[list_index].get(next_index) {
            heap.push(Reverse((next, list_index, next_index)));
        }
    }
    None
}

fn update_v4_factor_hash_field(hasher: &mut Xxh3, value: &[u8]) {
    let mut length = itoa::Buffer::new();
    hasher.update(b"\x1f");
    hasher.update(length.format(value.len()).as_bytes());
    hasher.update(b":");
    hasher.update(value);
}

fn legacy_provider_set_identity_from_sorted_lists(
    group_lists: &[&[i64]],
    network_names: &[String],
    semantic_progress: &ScannerSemanticProgress,
) -> io::Result<(String, GlobalId128)> {
    let group_count = sorted_unique_i64_count_with_visits(group_lists, |amount| {
        semantic_progress.record_provider_group_union_visits(amount);
    });
    let group_count = match usize::try_from(group_count) {
        Ok(group_count) => group_count,
        Err(_) => {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "V4 provider group union exceeds addressable identity width",
            ));
        }
    };
    let mut member_hasher = Xxh3::new();
    member_hasher.update(b"provider_set_members_v1");
    member_hasher.update(b"I");
    let mut count_buffer = itoa::Buffer::new();
    update_v4_factor_hash_field(
        &mut member_hasher,
        count_buffer.format(group_count).as_bytes(),
    );
    let mut global_hasher = Xxh3::new();
    global_hasher.update(b"provider_set_network_manifest_v1");
    for_each_sorted_unique_i64_with_visits(
        group_lists,
        |group| {
            let mut value_buffer = itoa::Buffer::new();
            update_v4_factor_hash_field(&mut member_hasher, value_buffer.format(group).as_bytes());
            global_hasher.update(b"\x1fgroup:");
            global_hasher.update(&group.to_le_bytes());
        },
        |amount| {
            semantic_progress.record_provider_group_union_visits(amount);
        },
    );
    let group_digest = format!("{:016x}", member_hasher.digest() & ((1u64 << 63) - 1));
    let provider_set_hash = hash_text(
        "provider_set_network_scope_v1",
        &[
            group_digest,
            hash_string_list("provider_set_network_names_v1", network_names),
        ],
    );
    update_hash_string_list(&mut global_hasher, network_names);
    Ok((
        provider_set_hash,
        GlobalId128(global_hasher.digest128().to_le_bytes()),
    ))
}

struct ProviderSetScopeCacheEntry {
    provider_group_hashes: Vec<i64>,
    provider_network_names: Vec<String>,
    rate_network_names: Vec<String>,
    provider_set_hash: String,
    provider_set_global_id: GlobalId128,
    network_names: Vec<String>,
}

struct CachedProviderSetScope<'a> {
    provider_set_hash: &'a str,
    provider_set_global_id: GlobalId128,
    network_names: &'a [String],
}

impl ProviderSetScopeCache {
    fn resolve<'a>(
        &'a mut self,
        provider_entry: &ProviderEntryView<'_>,
        rate: &RateLite,
        context: &CompactContext,
    ) -> CachedProviderSetScope<'a> {
        if self.entry_count >= PROVIDER_SET_SCOPE_CACHE_MAX_ENTRIES {
            self.buckets.clear();
            self.entry_count = 0;
        }
        let bucket = self.buckets.entry(provider_entry.entry_hash()).or_default();
        let entry_index = bucket.iter().position(|entry| {
            entry.provider_group_hashes == provider_entry.provider_group_hashes()
                && entry.provider_network_names == provider_entry.network_names()
                && entry.rate_network_names == rate.network_names
        });
        let entry_index = match entry_index {
            Some(entry_index) => entry_index,
            None => {
                let network_names =
                    rate_network_names(rate, provider_entry.network_names(), context);
                let provider_set_hash =
                    provider_set_scope_hash(provider_entry.provider_group_hashes(), &network_names);
                let provider_set_global_id =
                    provider_set_global_id_from_group_hashes_and_network_names(
                        provider_entry.provider_group_hashes(),
                        &network_names,
                    );
                bucket.push(ProviderSetScopeCacheEntry {
                    provider_group_hashes: provider_entry.provider_group_hashes().to_vec(),
                    provider_network_names: provider_entry.network_names().to_vec(),
                    rate_network_names: rate.network_names.clone(),
                    provider_set_hash,
                    provider_set_global_id,
                    network_names,
                });
                self.entry_count += 1;
                bucket.len() - 1
            }
        };
        let entry = &bucket[entry_index];
        CachedProviderSetScope {
            provider_set_hash: &entry.provider_set_hash,
            provider_set_global_id: entry.provider_set_global_id,
            network_names: &entry.network_names,
        }
    }
}

enum WorkerJob {
    Rates {
        procedure: Map<String, Value>,
        rates: Vec<RateLite>,
    },
    RawRates {
        procedure: Map<String, Value>,
        raw_rates: RawRateChunk,
    },
}

#[derive(Clone, Copy)]
struct RawRateSpan {
    start: usize,
    end: usize,
    coordinate: SourceWitnessCoordinate,
}

#[derive(Clone, Copy)]
struct SourceRateWitnessInput<'a> {
    coordinate: SourceWitnessCoordinate,
    raw_rate: &'a [u8],
}

struct RawRateChunk {
    bytes: Vec<u8>,
    spans: Vec<RawRateSpan>,
}

impl RawRateChunk {
    fn with_capacity(rate_capacity: usize, byte_capacity: usize) -> Self {
        Self {
            bytes: Vec::with_capacity(byte_capacity),
            spans: Vec::with_capacity(rate_capacity),
        }
    }

    fn is_empty(&self) -> bool {
        self.spans.is_empty()
    }

    fn len(&self) -> usize {
        self.spans.len()
    }

    fn byte_len(&self) -> usize {
        self.bytes.len()
    }

    #[cfg(test)]
    fn push_current_value_span(&mut self, start: usize) {
        let item_ordinal = self.spans.len() as u64;
        self.push_current_value_span_at(start, SourceWitnessCoordinate::new(0, item_ordinal));
    }

    fn push_current_value_span_at(&mut self, start: usize, coordinate: SourceWitnessCoordinate) {
        self.spans.push(RawRateSpan {
            start,
            end: self.bytes.len(),
            coordinate,
        });
    }

    #[cfg(test)]
    fn iter(&self) -> impl Iterator<Item = &[u8]> {
        self.spans
            .iter()
            .map(|span| &self.bytes[span.start..span.end])
    }

    fn iter_with_coordinates(&self) -> impl Iterator<Item = (SourceWitnessCoordinate, &[u8])> {
        self.spans
            .iter()
            .map(|span| (span.coordinate, &self.bytes[span.start..span.end]))
    }

    fn clear_for_recycle(&mut self) {
        self.bytes.clear();
        self.spans.clear();
    }
}

#[derive(Default)]
struct QueueByteMetrics {
    queued_bytes: AtomicU64,
    peak_queued_bytes: AtomicU64,
}

impl QueueByteMetrics {
    fn begin_send(&self, byte_count: usize) {
        let byte_count = byte_count as u64;
        let queued = self
            .queued_bytes
            .fetch_add(byte_count, Ordering::Relaxed)
            .saturating_add(byte_count);
        self.peak_queued_bytes.fetch_max(queued, Ordering::Relaxed);
    }

    fn finish_receive(&self, byte_count: usize) {
        let byte_count = byte_count as u64;
        let _ = self
            .queued_bytes
            .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |queued| {
                Some(queued.saturating_sub(byte_count))
            });
    }

    fn peak_bytes(&self) -> u64 {
        self.peak_queued_bytes.load(Ordering::Relaxed)
    }

    fn current_bytes(&self) -> u64 {
        self.queued_bytes.load(Ordering::Relaxed)
    }
}

#[derive(Default)]
struct RawChunkStats {
    chunk_count: u64,
    total_bytes: u64,
    max_bytes: usize,
    max_rates: usize,
    queue_high_water: usize,
    queue_blocked_sends: u64,
    capture_micros: u128,
    framing_micros: u128,
    buffer_allocations: u64,
    buffer_reuses: u64,
    queue_bytes: Arc<QueueByteMetrics>,
    recycle_rx: Option<Receiver<RawRateChunk>>,
}

impl RawChunkStats {
    fn merge_from(&mut self, other: &Self) {
        self.chunk_count = self.chunk_count.saturating_add(other.chunk_count);
        self.total_bytes = self.total_bytes.saturating_add(other.total_bytes);
        self.max_bytes = self.max_bytes.max(other.max_bytes);
        self.max_rates = self.max_rates.max(other.max_rates);
        self.queue_high_water = self.queue_high_water.max(other.queue_high_water);
        self.queue_blocked_sends = self
            .queue_blocked_sends
            .saturating_add(other.queue_blocked_sends);
        self.capture_micros = self.capture_micros.saturating_add(other.capture_micros);
        self.framing_micros = self.framing_micros.saturating_add(other.framing_micros);
        self.buffer_allocations = self
            .buffer_allocations
            .saturating_add(other.buffer_allocations);
        self.buffer_reuses = self.buffer_reuses.saturating_add(other.buffer_reuses);
    }

    fn record(&mut self, rate_count: usize, byte_count: usize) {
        self.chunk_count = self.chunk_count.saturating_add(1);
        self.total_bytes = self.total_bytes.saturating_add(byte_count as u64);
        self.max_bytes = self.max_bytes.max(byte_count);
        self.max_rates = self.max_rates.max(rate_count);
    }

    fn enable_recycling(&mut self, capacity: usize) -> Sender<RawRateChunk> {
        let (recycle_tx, recycle_rx) = bounded(capacity.max(1));
        self.recycle_rx = Some(recycle_rx);
        recycle_tx
    }

    fn allocate_chunk(&mut self, rate_capacity: usize, byte_capacity: usize) -> RawRateChunk {
        self.buffer_allocations = self.buffer_allocations.saturating_add(1);
        RawRateChunk::with_capacity(rate_capacity, byte_capacity)
    }

    fn acquire_chunk(
        &mut self,
        rate_capacity: usize,
        byte_capacity: usize,
        max_retain_byte_capacity: usize,
    ) -> RawRateChunk {
        let byte_capacity = byte_capacity.min(max_retain_byte_capacity);
        if let Some(mut recycled) = self
            .recycle_rx
            .as_ref()
            .and_then(|recycle_rx| recycle_rx.try_recv().ok())
        {
            self.buffer_reuses = self.buffer_reuses.saturating_add(1);
            if recycled.bytes.capacity() > max_retain_byte_capacity {
                recycled.bytes = Vec::with_capacity(byte_capacity);
            } else {
                recycled.bytes.clear();
            }
            if recycled.spans.capacity() > rate_capacity {
                recycled.spans = Vec::with_capacity(rate_capacity);
            } else {
                recycled.spans.clear();
            }
            return recycled;
        }
        self.allocate_chunk(rate_capacity, byte_capacity)
    }

    fn take_filled_chunk(
        &mut self,
        chunk: &mut RawRateChunk,
        rate_capacity: usize,
        max_retain_byte_capacity: usize,
    ) -> RawRateChunk {
        let retained_byte_capacity = chunk.bytes.capacity().min(max_retain_byte_capacity);
        let mut replacement = self.acquire_chunk(
            rate_capacity,
            retained_byte_capacity,
            max_retain_byte_capacity,
        );
        std::mem::swap(chunk, &mut replacement);
        replacement
    }

    fn record_queue_depth(&mut self, depth: usize) {
        self.queue_high_water = self.queue_high_water.max(depth);
    }

    fn record_queue_blocked(&mut self) {
        self.queue_blocked_sends = self.queue_blocked_sends.saturating_add(1);
    }

    fn record_capture_batch(&mut self, started_at: Option<Instant>) {
        if let Some(started_at) = started_at {
            self.capture_micros = self
                .capture_micros
                .saturating_add(started_at.elapsed().as_micros());
        }
    }
}

fn take_vec_replacing_with_capacity<T>(values: &mut Vec<T>, capacity: usize) -> Vec<T> {
    let mut replacement = Vec::with_capacity(capacity);
    std::mem::swap(values, &mut replacement);
    replacement
}

fn clear_vec_retain_bounded_capacity<T>(values: &mut Vec<T>, max_retain_capacity: usize) {
    if values.capacity() > max_retain_capacity {
        *values = Vec::with_capacity(max_retain_capacity);
    } else {
        values.clear();
    }
}

#[derive(Default)]
