#[cfg(test)]
fn read_rate_lite_from_reader<R: Read>(reader: R) -> io::Result<Option<RateLite>> {
    let mut json_reader = JsonStreamReader::new(reader);
    let rate = read_rate_lite_struson(&mut json_reader, false)?;
    json_reader
        .consume_trailing_whitespace()
        .map_err(to_io_error)?;
    Ok(rate)
}

fn read_price_lite_struson<R: Read>(
    json_reader: &mut JsonStreamReader<R>,
) -> io::Result<Option<PriceLite>> {
    let mut negotiated_type: Option<String> = None;
    let mut negotiated_rate: Option<String> = None;
    let mut expiration_date: Option<String> = None;
    let mut service_code: Vec<String> = Vec::new();
    let mut billing_class: Option<String> = None;
    let mut setting: Option<String> = None;
    let mut billing_code_modifier: Vec<String> = Vec::new();
    let mut additional_information: Option<String> = None;

    json_reader.begin_object().map_err(to_io_error)?;
    while json_reader.has_next().map_err(to_io_error)? {
        let field = match json_reader.next_name().map_err(to_io_error)? {
            "negotiated_type" => 1,
            "negotiated_rate" => 2,
            "expiration_date" => 3,
            "service_code" => 4,
            "billing_class" => 5,
            "setting" => 6,
            "billing_code_modifier" => 7,
            "additional_information" => 8,
            _ => 0,
        };
        match field {
            1 => {
                negotiated_type =
                    strict_nullable_string_from_reader(json_reader, "negotiated_type")?;
            }
            2 => {
                negotiated_rate = strict_money_number_from_reader(json_reader)?;
            }
            3 => {
                expiration_date =
                    strict_nullable_string_from_reader(json_reader, "expiration_date")?;
            }
            4 => {
                service_code = canonical_text_list(
                    strict_string_array_from_reader(json_reader, "service_code")?,
                    false,
                );
            }
            5 => {
                billing_class = strict_nullable_string_from_reader(json_reader, "billing_class")?;
            }
            6 => {
                setting = strict_nullable_string_from_reader(json_reader, "setting")?;
            }
            7 => {
                billing_code_modifier = canonical_modifier_list(strict_string_array_from_reader(
                    json_reader,
                    "billing_code_modifier",
                )?);
            }
            8 => {
                additional_information =
                    strict_nullable_string_from_reader(json_reader, "additional_information")?;
            }
            _ => {
                json_reader.skip_value().map_err(to_io_error)?;
            }
        }
    }
    json_reader.end_object().map_err(to_io_error)?;
    let negotiated_rate = negotiated_rate.ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "negotiated price is missing required negotiated_rate",
        )
    })?;
    Ok(Some(PriceLite {
        negotiated_type,
        negotiated_rate,
        expiration_date,
        service_code,
        billing_class,
        setting,
        billing_code_modifier,
        additional_information,
    }))
}

fn strict_nullable_string_from_reader<R: Read>(
    json_reader: &mut JsonStreamReader<R>,
    field_name: &str,
) -> io::Result<Option<String>> {
    match json_reader.peek().map_err(to_io_error)? {
        ValueType::String => {
            let value = json_reader.next_string().map_err(to_io_error)?;
            let trimmed = value.trim();
            Ok((!trimmed.is_empty()).then(|| trimmed.to_owned()))
        }
        ValueType::Null => {
            json_reader.next_null().map_err(to_io_error)?;
            Ok(None)
        }
        _ => Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("{field_name} must be a JSON string or null"),
        )),
    }
}

fn strict_string_or_array_from_reader<R: Read>(
    json_reader: &mut JsonStreamReader<R>,
    field_name: &str,
) -> io::Result<Vec<String>> {
    match json_reader.peek().map_err(to_io_error)? {
        ValueType::String => Ok(vec![json_reader.next_string().map_err(to_io_error)?]),
        ValueType::Array => strict_string_array_from_reader(json_reader, field_name),
        ValueType::Null => {
            json_reader.next_null().map_err(to_io_error)?;
            Ok(Vec::new())
        }
        _ => Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("{field_name} must be a JSON string, an array of strings, or null"),
        )),
    }
}

fn procedure_has_queryable_code(procedure: &Map<String, Value>) -> bool {
    ["billing_code_type", "billing_code"]
        .iter()
        .all(|field_name| {
            matches!(
                procedure.get(*field_name),
                Some(Value::String(value)) if !value.trim().is_empty()
            )
        })
}

fn validate_procedure_for_rate_dispatch(procedure: &Map<String, Value>) -> io::Result<()> {
    if !procedure.contains_key("billing_code_type") || !procedure.contains_key("billing_code") {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "negotiated_rates reached a dispatch boundary before billing_code_type and billing_code",
        ));
    }
    for field_name in ["billing_code_type", "billing_code"] {
        match procedure.get(field_name) {
            Some(Value::String(_)) => {}
            Some(_) => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("{field_name} must be a JSON string"),
                ));
            }
            None => unreachable!("required procedure fields were checked above"),
        }
    }
    if let Some(value) = procedure.get("negotiation_arrangement") {
        if !matches!(value, Value::String(_) | Value::Null) {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "negotiation_arrangement must be a JSON string or null",
            ));
        }
    }
    for field_name in ["billing_code_type_version", "name", "description"] {
        validate_optional_string_value(procedure.get(field_name), field_name)?;
    }
    Ok(())
}

fn reject_late_procedure_field(name: &str, rates_dispatched: bool) -> io::Result<()> {
    if !rates_dispatched {
        return Ok(());
    }
    Err(io::Error::new(
        io::ErrorKind::InvalidData,
        format!("procedure field {name} appeared after negotiated rates were dispatched"),
    ))
}

#[derive(Clone, Copy)]
struct InNetworkEnqueueOptions {
    chunk_size: usize,
    raw_chunk_byte_limit: usize,
    parse_in_workers: bool,
    object_ordinal: u64,
}

struct InNetworkEnqueueIo<'a, W: Write> {
    tx: &'a Sender<WorkerJob>,
    event_rx: &'a Receiver<CopyFileEvent>,
    writer: &'a mut W,
    copy_file_event_gate: &'a mut CopyFileEventGate,
    cancelled: Option<&'a AtomicBool>,
    producer_blocked_micros: &'a mut u128,
    raw_chunk_stats: &'a mut RawChunkStats,
}

fn enqueue_in_network_raw_byte_scan<R: Read, W: Write>(
    reader: &mut BufferedJsonByteReader<R>,
    io_state: &mut InNetworkEnqueueIo<'_, W>,
    options: InNetworkEnqueueOptions,
) -> io::Result<u64> {
    let framing_started_at = Instant::now();
    let chunk_size = options.chunk_size;
    let raw_chunk_byte_limit = options.raw_chunk_byte_limit;
    let mut procedure = Map::new();
    let mut raw_rate_chunk = io_state.raw_chunk_stats.acquire_chunk(
        chunk_size,
        raw_chunk_byte_limit.min(READ_BUF_SIZE),
        raw_chunk_byte_limit,
    );
    let mut scratch_value = Vec::new();
    let mut name_bytes = Vec::with_capacity(32);
    let mut decoded_name = String::new();
    let mut rate_count = 0u64;
    let mut rates_dispatched = false;
    let mut capture_batch_started_at = None;
    reader.expect_byte(b'{')?;
    let mut first_field = true;
    loop {
        reader.skip_whitespace()?;
        if reader.consume_if(b'}')? {
            break;
        }
        if first_field {
            first_field = false;
        } else {
            reader.expect_byte(b',')?;
        }
        let name = reader.read_string_name(&mut name_bytes, &mut decoded_name)?;
        reader.expect_byte(b':')?;
        match name {
            "billing_code_type"
            | "billing_code_type_version"
            | "billing_code"
            | "negotiation_arrangement"
            | "name"
            | "description" => {
                reject_late_procedure_field(name, rates_dispatched)?;
                reader.capture_value_bytes_into(&mut scratch_value)?;
                let value = parse_json_value_from_raw_bytes(&scratch_value)?;
                procedure.insert(name.to_string(), value);
                clear_vec_retain_bounded_capacity(&mut scratch_value, MAX_RETAINED_CAPTURE_BYTES);
            }
            "negotiated_rates" => {
                reader.expect_byte(b'[')?;
                let mut first_rate = true;
                capture_batch_started_at = Some(Instant::now());
                loop {
                    let raw_start = raw_rate_chunk.byte_len();
                    if !reader.capture_next_array_object_bytes_append(
                        &mut raw_rate_chunk.bytes,
                        &mut first_rate,
                    )? {
                        break;
                    }
                    rate_count += 1;
                    raw_rate_chunk.push_current_value_span_at(
                        raw_start,
                        SourceWitnessCoordinate::new(
                            options.object_ordinal,
                            rate_count.saturating_sub(1),
                        ),
                    );
                    if raw_rate_chunk.len() >= chunk_size
                        || raw_rate_chunk.byte_len() >= raw_chunk_byte_limit
                    {
                        io_state
                            .raw_chunk_stats
                            .record_capture_batch(capture_batch_started_at.take());
                        validate_procedure_for_rate_dispatch(&procedure)?;
                        let raw_rates = io_state.raw_chunk_stats.take_filled_chunk(
                            &mut raw_rate_chunk,
                            chunk_size,
                            raw_chunk_byte_limit,
                        );
                        let raw_bytes = raw_rates.byte_len();
                        io_state.raw_chunk_stats.record(raw_rates.len(), raw_bytes);
                        send_worker_job(
                            io_state,
                            WorkerJob::RawRates {
                                procedure: procedure.clone(),
                                raw_rates,
                            },
                        )?;
                        rates_dispatched = true;
                        drain_copy_file_events(
                            io_state.event_rx,
                            io_state.writer,
                            io_state.copy_file_event_gate,
                        )?;
                        capture_batch_started_at = Some(Instant::now());
                    }
                }
            }
            _ => {
                reader.capture_value_bytes_into(&mut scratch_value)?;
                clear_vec_retain_bounded_capacity(&mut scratch_value, MAX_RETAINED_CAPTURE_BYTES);
            }
        }
    }
    validate_procedure_for_rate_dispatch(&procedure)?;
    if !raw_rate_chunk.is_empty() {
        io_state
            .raw_chunk_stats
            .record_capture_batch(capture_batch_started_at.take());
        validate_procedure_for_rate_dispatch(&procedure)?;
        io_state
            .raw_chunk_stats
            .record(raw_rate_chunk.len(), raw_rate_chunk.byte_len());
        send_worker_job(
            io_state,
            WorkerJob::RawRates {
                procedure,
                raw_rates: raw_rate_chunk,
            },
        )?;
        drain_copy_file_events(
            io_state.event_rx,
            io_state.writer,
            io_state.copy_file_event_gate,
        )?;
    }
    io_state.raw_chunk_stats.framing_micros = io_state
        .raw_chunk_stats
        .framing_micros
        .saturating_add(framing_started_at.elapsed().as_micros());
    Ok(rate_count)
}

fn enqueue_in_network_struson<R: Read, W: Write>(
    json_reader: &mut JsonStreamReader<R>,
    io_state: &mut InNetworkEnqueueIo<'_, W>,
    options: InNetworkEnqueueOptions,
) -> io::Result<u64> {
    let framing_started_at = Instant::now();
    let chunk_size = options.chunk_size;
    let raw_chunk_byte_limit = options.raw_chunk_byte_limit;
    let parse_in_workers = options.parse_in_workers;
    let mut procedure = Map::new();
    let mut rate_chunk: Vec<RateLite> = Vec::with_capacity(chunk_size);
    let mut raw_rate_chunk = io_state.raw_chunk_stats.acquire_chunk(
        chunk_size,
        raw_chunk_byte_limit.min(READ_BUF_SIZE),
        raw_chunk_byte_limit,
    );
    let mut rate_count = 0u64;
    let mut rates_dispatched = false;
    let mut capture_batch_started_at = None;
    json_reader.begin_object().map_err(to_io_error)?;
    while json_reader.has_next().map_err(to_io_error)? {
        let name = json_reader.next_name_owned().map_err(to_io_error)?;
        match name.as_str() {
            "billing_code_type"
            | "billing_code_type_version"
            | "billing_code"
            | "negotiation_arrangement"
            | "name"
            | "description" => {
                reject_late_procedure_field(&name, rates_dispatched)?;
                let value: Value = json_reader.deserialize_next().map_err(to_io_error)?;
                procedure.insert(name, value);
            }
            "negotiated_rates" => {
                json_reader.begin_array().map_err(to_io_error)?;
                if parse_in_workers {
                    capture_batch_started_at = Some(Instant::now());
                }
                while json_reader.has_next().map_err(to_io_error)? {
                    rate_count += 1;
                    if parse_in_workers {
                        let raw_start = raw_rate_chunk.byte_len();
                        transfer_next_value_to_bytes_append(
                            json_reader,
                            &mut raw_rate_chunk.bytes,
                        )?;
                        raw_rate_chunk.push_current_value_span_at(
                            raw_start,
                            SourceWitnessCoordinate::new(
                                options.object_ordinal,
                                rate_count.saturating_sub(1),
                            ),
                        );
                        if raw_rate_chunk.len() >= chunk_size
                            || raw_rate_chunk.byte_len() >= raw_chunk_byte_limit
                        {
                            io_state
                                .raw_chunk_stats
                                .record_capture_batch(capture_batch_started_at.take());
                            validate_procedure_for_rate_dispatch(&procedure)?;
                            let raw_rates = io_state.raw_chunk_stats.take_filled_chunk(
                                &mut raw_rate_chunk,
                                chunk_size,
                                raw_chunk_byte_limit,
                            );
                            let raw_bytes = raw_rates.byte_len();
                            io_state.raw_chunk_stats.record(raw_rates.len(), raw_bytes);
                            send_worker_job(
                                io_state,
                                WorkerJob::RawRates {
                                    procedure: procedure.clone(),
                                    raw_rates,
                                },
                            )?;
                            rates_dispatched = true;
                            drain_copy_file_events(
                                io_state.event_rx,
                                io_state.writer,
                                io_state.copy_file_event_gate,
                            )?;
                            capture_batch_started_at = Some(Instant::now());
                        }
                    } else if let Some(rate) = read_rate_lite_struson(json_reader, false)? {
                        rate_chunk.push(rate);
                        if rate_chunk.len() >= chunk_size {
                            validate_procedure_for_rate_dispatch(&procedure)?;
                            let rates =
                                take_vec_replacing_with_capacity(&mut rate_chunk, chunk_size);
                            send_worker_job(
                                io_state,
                                WorkerJob::Rates {
                                    procedure: procedure.clone(),
                                    rates,
                                },
                            )?;
                            rates_dispatched = true;
                            drain_copy_file_events(
                                io_state.event_rx,
                                io_state.writer,
                                io_state.copy_file_event_gate,
                            )?;
                        }
                    }
                }
                json_reader.end_array().map_err(to_io_error)?;
            }
            _ => {
                json_reader.skip_value().map_err(to_io_error)?;
            }
        }
    }
    json_reader.end_object().map_err(to_io_error)?;
    validate_procedure_for_rate_dispatch(&procedure)?;
    if !raw_rate_chunk.is_empty() {
        io_state
            .raw_chunk_stats
            .record_capture_batch(capture_batch_started_at.take());
        validate_procedure_for_rate_dispatch(&procedure)?;
        io_state
            .raw_chunk_stats
            .record(raw_rate_chunk.len(), raw_rate_chunk.byte_len());
        send_worker_job(
            io_state,
            WorkerJob::RawRates {
                procedure,
                raw_rates: raw_rate_chunk,
            },
        )?;
        drain_copy_file_events(
            io_state.event_rx,
            io_state.writer,
            io_state.copy_file_event_gate,
        )?;
    } else if !rate_chunk.is_empty() {
        validate_procedure_for_rate_dispatch(&procedure)?;
        send_worker_job(
            io_state,
            WorkerJob::Rates {
                procedure,
                rates: rate_chunk,
            },
        )?;
        drain_copy_file_events(
            io_state.event_rx,
            io_state.writer,
            io_state.copy_file_event_gate,
        )?;
    }
    io_state.raw_chunk_stats.framing_micros = io_state
        .raw_chunk_stats
        .framing_micros
        .saturating_add(framing_started_at.elapsed().as_micros());
    Ok(rate_count)
}

fn finish_worker_outputs(
    compact_copy_writer: Option<CompactCopySink>,
    manifest_serving_copy_writer: Option<V3ServingRunSink>,
    dictionary_copy_sinks: DictionaryCopySinks,
) -> io::Result<(Vec<CopyFileEvent>, ServingRunMetrics)> {
    let mut events = Vec::new();
    let mut serving_run_metrics = ServingRunMetrics::default();
    if let Some(copy_writer) = compact_copy_writer {
        if let Some(event) = copy_writer.finish_silent()? {
            events.push(event);
        }
    }
    if let Some(copy_writer) = manifest_serving_copy_writer {
        let (serving_events, metrics) = copy_writer.finish_silent()?;
        events.extend(serving_events);
        serving_run_metrics = metrics;
    }
    events.extend(dictionary_copy_sinks.finish_silent()?);
    Ok((events, serving_run_metrics))
}

struct CompactWorkerConfig {
    event_tx: Sender<CopyFileEvent>,
    provider_map: Arc<HashMap<ProviderRefKey, ProviderEntry>>,
    provider_group_conflicts: Arc<HashSet<ProviderRefKey>>,
    dedupe: Arc<SharedDedupe>,
    manifest_sidecars: Option<Arc<Mutex<ManifestSidecarCollector>>>,
    queue_bytes: Arc<QueueByteMetrics>,
    recycle_tx: Option<Sender<RawRateChunk>>,
    copy_paths: CopyPathConfig,
    rotate_bytes: u64,
    context: CompactContext,
    provider_graph_v4_factor_cache: Arc<V4ProviderSetFactorSharedCache>,
    provider_graph_v4_factor_mode: bool,
}

fn compact_sink_write_micros(
    compact_copy_writer: &Option<CompactCopySink>,
    manifest_serving_copy_writer: &Option<V3ServingRunSink>,
    dictionary_copy_sinks: &DictionaryCopySinks,
) -> u128 {
    compact_copy_writer
        .as_ref()
        .map_or(0, CompactCopySink::write_micros)
        .saturating_add(
            manifest_serving_copy_writer
                .as_ref()
                .map_or(0, V3ServingRunSink::write_micros),
        )
        .saturating_add(dictionary_copy_sinks.write_micros())
}

fn compact_worker_loop(
    worker_id: usize,
    rx: Receiver<WorkerJob>,
    config: CompactWorkerConfig,
) -> io::Result<CompactWorkerOutput> {
    let started_at = Instant::now();
    let _ = take_sidecar_lock_wait_micros();
    let worker_paths = config.copy_paths.for_worker(worker_id);
    let mut compact_copy_writer = worker_paths
        .compact
        .as_ref()
        .map(|path| CompactCopySink::new_file(path.clone(), config.rotate_bytes))
        .transpose()?;
    let serving_run_directory = worker_paths
        .v3_serving_run_directory
        .as_deref()
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "strict V3 worker is missing its serving-run directory",
            )
        })?;
    let coverage_scope_id = worker_paths.v3_coverage_scope_id.ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "strict V3 worker is missing its coverage-scope identity",
        )
    })?;
    let mut manifest_serving_copy_writer = Some(V3ServingRunSink::new(
        serving_run_directory,
        &format!("worker{worker_id:04}"),
        coverage_scope_id,
    )?);
    let mut dictionary_copy_sinks =
        DictionaryCopySinks::from_paths(&worker_paths, config.rotate_bytes)?;
    let mut sink = io::sink();
    let mut provider_set_scope_cache = ProviderSetScopeCache::configured(
        Arc::clone(&config.provider_graph_v4_factor_cache),
        config.provider_graph_v4_factor_mode,
    );
    let mut manifest_global_id_cache = ManifestGlobalIdCache::default();
    let mut worker_dedupe_cache = WorkerDedupeCache::from_env();
    let mut metrics = CompactWorkerMetrics {
        worker_id,
        ..CompactWorkerMetrics::default()
    };
    let mut invalid_price_exclusions = Vec::new();
    let mut invalid_price_emptied_rates = 0u64;
    let semantic_progress = config
        .provider_graph_v4_factor_cache
        .semantic_progress_if_enabled();

    for job in rx.iter() {
        config.queue_bytes.finish_receive(job.raw_byte_len());
        metrics.jobs = metrics.jobs.saturating_add(1);
        match job {
            WorkerJob::Rates { procedure, rates } => {
                metrics.rates_seen = metrics.rates_seen.saturating_add(rates.len() as u64);
                metrics.rates_parsed = metrics.rates_parsed.saturating_add(rates.len() as u64);
                if let Some(semantic_progress) = semantic_progress.as_ref() {
                    semantic_progress.record_negotiated_rates_parsed(rates.len() as u64);
                }
                validate_unreferenced_provider_group_conflicts(
                    &rates,
                    &config.provider_group_conflicts,
                )?;
                let procedure_value = Value::Object(procedure);
                let write_micros_before = compact_sink_write_micros(
                    &compact_copy_writer,
                    &manifest_serving_copy_writer,
                    &dictionary_copy_sinks,
                );
                let transform_started_at = Instant::now();
                let mut state = SharedCompactState {
                    writer: &mut sink,
                    compact_copy_writer: &mut compact_copy_writer,
                    manifest_serving_copy_writer: &mut manifest_serving_copy_writer,
                    dictionary_copy_sinks: &mut dictionary_copy_sinks,
                    manifest_sidecars: config.manifest_sidecars.clone(),
                    record_price_forward_sidecar: config
                        .copy_paths
                        .manifest_price_forward_sidecar
                        .is_some(),
                    suppress_legacy_row_output: config.copy_paths.manifest_only,
                    provider_map: &config.provider_map,
                    dedupe: &config.dedupe,
                    worker_dedupe_cache: &mut worker_dedupe_cache,
                    provider_set_scope_cache: &mut provider_set_scope_cache,
                    manifest_global_id_cache: &mut manifest_global_id_cache,
                    context: &config.context,
                };
                process_compact_rate_lites_worker(&mut state, &rates, &procedure_value)?;
                let transform_micros = transform_started_at.elapsed().as_micros();
                let write_micros = compact_sink_write_micros(
                    &compact_copy_writer,
                    &manifest_serving_copy_writer,
                    &dictionary_copy_sinks,
                )
                .saturating_sub(write_micros_before);
                let sidecar_lock_wait_micros = take_sidecar_lock_wait_micros();
                metrics.write_micros = metrics.write_micros.saturating_add(write_micros);
                metrics.sidecar_lock_wait_micros = metrics
                    .sidecar_lock_wait_micros
                    .saturating_add(sidecar_lock_wait_micros);
                metrics.transform_micros = metrics.transform_micros.saturating_add(
                    transform_micros
                        .saturating_sub(write_micros)
                        .saturating_sub(sidecar_lock_wait_micros),
                );
            }
            WorkerJob::RawRates {
                procedure,
                mut raw_rates,
            } => {
                metrics.rates_seen = metrics.rates_seen.saturating_add(raw_rates.len() as u64);
                metrics.raw_bytes = metrics
                    .raw_bytes
                    .saturating_add(raw_rates.byte_len() as u64);
                let parse_started_at = Instant::now();
                let mut rates = Vec::with_capacity(raw_rates.len());
                let mut source_inputs = Vec::with_capacity(raw_rates.len());
                for (coordinate, raw_rate) in raw_rates.iter_with_coordinates() {
                    let (parsed, typed) = read_rate_lite_bytes_profiled_with_exclusion(
                        raw_rate,
                        config.provider_graph_v4_factor_mode,
                        coordinate,
                        config.context.invalid_price_exclusion.as_deref(),
                    )?;
                    if let Some(semantic_progress) = semantic_progress.as_ref() {
                        semantic_progress.record_negotiated_rate_parsed();
                    }
                    if typed {
                        metrics.typed_rate_parses = metrics.typed_rate_parses.saturating_add(1);
                    } else {
                        metrics.streaming_rate_parse_fallbacks =
                            metrics.streaming_rate_parse_fallbacks.saturating_add(1);
                    }
                    invalid_price_exclusions.extend(parsed.exclusions);
                    if parsed.emptied_rate {
                        invalid_price_emptied_rates = invalid_price_emptied_rates.saturating_add(1);
                    }
                    rates.push(parsed.rate);
                    source_inputs.push(SourceRateWitnessInput {
                        coordinate,
                        raw_rate,
                    });
                }
                metrics.parse_micros = metrics
                    .parse_micros
                    .saturating_add(parse_started_at.elapsed().as_micros());
                metrics.rates_parsed = metrics.rates_parsed.saturating_add(rates.len() as u64);
                validate_unreferenced_provider_group_conflicts(
                    &rates,
                    &config.provider_group_conflicts,
                )?;
                let procedure_value = Value::Object(procedure);
                let write_micros_before = compact_sink_write_micros(
                    &compact_copy_writer,
                    &manifest_serving_copy_writer,
                    &dictionary_copy_sinks,
                );
                let transform_started_at = Instant::now();
                let mut state = SharedCompactState {
                    writer: &mut sink,
                    compact_copy_writer: &mut compact_copy_writer,
                    manifest_serving_copy_writer: &mut manifest_serving_copy_writer,
                    dictionary_copy_sinks: &mut dictionary_copy_sinks,
                    manifest_sidecars: config.manifest_sidecars.clone(),
                    record_price_forward_sidecar: config
                        .copy_paths
                        .manifest_price_forward_sidecar
                        .is_some(),
                    suppress_legacy_row_output: config.copy_paths.manifest_only,
                    provider_map: &config.provider_map,
                    dedupe: &config.dedupe,
                    worker_dedupe_cache: &mut worker_dedupe_cache,
                    provider_set_scope_cache: &mut provider_set_scope_cache,
                    manifest_global_id_cache: &mut manifest_global_id_cache,
                    context: &config.context,
                };
                process_compact_rate_lites_worker_with_source(
                    &mut state,
                    &rates,
                    &procedure_value,
                    &source_inputs,
                )?;
                let transform_micros = transform_started_at.elapsed().as_micros();
                let write_micros = compact_sink_write_micros(
                    &compact_copy_writer,
                    &manifest_serving_copy_writer,
                    &dictionary_copy_sinks,
                )
                .saturating_sub(write_micros_before);
                let sidecar_lock_wait_micros = take_sidecar_lock_wait_micros();
                metrics.write_micros = metrics.write_micros.saturating_add(write_micros);
                metrics.sidecar_lock_wait_micros = metrics
                    .sidecar_lock_wait_micros
                    .saturating_add(sidecar_lock_wait_micros);
                metrics.transform_micros = metrics.transform_micros.saturating_add(
                    transform_micros
                        .saturating_sub(write_micros)
                        .saturating_sub(sidecar_lock_wait_micros),
                );
                drop(source_inputs);
                if let Some(recycle_tx) = config.recycle_tx.as_ref() {
                    raw_rates.clear_for_recycle();
                    let _ = recycle_tx.try_send(raw_rates);
                }
            }
        }
        if let Some(semantic_progress) = semantic_progress.as_ref() {
            semantic_progress.record_rate_chunk_completed();
        }
        let write_started_at = Instant::now();
        if let Some(copy_writer) = compact_copy_writer.as_mut() {
            if let Some(event) = copy_writer.maybe_rotate_silent()? {
                config.event_tx.send(event).map_err(|err| {
                    io::Error::new(
                        io::ErrorKind::BrokenPipe,
                        format!("compact copy event queue closed: {err}"),
                    )
                })?;
            }
        }
        if let Some(copy_writer) = manifest_serving_copy_writer.as_mut() {
            for event in copy_writer.maybe_rotate_silent()? {
                config.event_tx.send(event).map_err(|err| {
                    io::Error::new(
                        io::ErrorKind::BrokenPipe,
                        format!("manifest serving copy event queue closed: {err}"),
                    )
                })?;
            }
        }
        for event in dictionary_copy_sinks.maybe_rotate_silent()? {
            config.event_tx.send(event).map_err(|err| {
                io::Error::new(
                    io::ErrorKind::BrokenPipe,
                    format!("dictionary copy event queue closed: {err}"),
                )
            })?;
        }
        metrics.write_micros = metrics
            .write_micros
            .saturating_add(write_started_at.elapsed().as_micros());
    }

    worker_dedupe_cache.flush_duplicate_counts(&config.dedupe);
    let write_started_at = Instant::now();
    let (events, serving_run_metrics) = finish_worker_outputs(
        compact_copy_writer,
        manifest_serving_copy_writer,
        dictionary_copy_sinks,
    )?;
    metrics.serving_run_files = serving_run_metrics.file_count;
    metrics.serving_run_rows = serving_run_metrics.row_count;
    metrics.serving_run_bytes = serving_run_metrics.bytes;
    metrics.serving_code_dictionary_files = serving_run_metrics.code_dictionary_file_count;
    metrics.serving_code_dictionary_rows = serving_run_metrics.code_dictionary_row_count;
    metrics.serving_code_dictionary_bytes = serving_run_metrics.code_dictionary_bytes;
    metrics.local_price_set_dedupe_hits = worker_dedupe_cache.price_set_hits;
    metrics.local_price_atom_dedupe_hits = worker_dedupe_cache.price_atom_hits;
    metrics.local_provider_set_dedupe_hits = worker_dedupe_cache.provider_set_hits;
    metrics.local_price_set_dedupe_resets = worker_dedupe_cache.price_set_resets;
    metrics.local_price_atom_dedupe_resets = worker_dedupe_cache.price_atom_resets;
    metrics.local_provider_set_dedupe_resets = worker_dedupe_cache.provider_set_resets;
    let factor_metrics = provider_set_scope_cache.v4_factors.metrics;
    metrics.provider_graph_v4_factor_mode = provider_set_scope_cache.v4_factor_mode();
    metrics.provider_graph_v4_reference_only_rates = factor_metrics.reference_only_rates;
    metrics.provider_graph_v4_inline_only_rates = factor_metrics.inline_only_rates;
    metrics.provider_graph_v4_mixed_rates = factor_metrics.mixed_rates;
    metrics.provider_graph_v4_factor_cache_hits = factor_metrics.cache_hits;
    metrics.provider_graph_v4_factor_cache_misses = factor_metrics.cache_misses;
    metrics.provider_graph_v4_factor_cache_resets = factor_metrics.cache_resets;
    metrics.provider_graph_v4_npi_union_attempts = factor_metrics.npi_union_attempts;
    metrics.provider_graph_v4_flat_group_union_attempts = factor_metrics.flat_group_union_attempts;
    metrics.write_micros = metrics
        .write_micros
        .saturating_add(write_started_at.elapsed().as_micros());
    metrics.sidecar_lock_wait_micros = metrics
        .sidecar_lock_wait_micros
        .saturating_add(take_sidecar_lock_wait_micros());
    metrics.elapsed_micros = started_at.elapsed().as_micros();
    Ok(CompactWorkerOutput {
        events,
        metrics,
        invalid_price_exclusions,
        invalid_price_emptied_rates,
    })
}

#[derive(Clone, Copy)]
enum CompactTopLevelArrayKey {
    ProviderReferences,
    InNetwork,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct TopLevelArrayRange {
    offset: u64,
    length: u64,
}

struct TemporaryRapidgzipIndex {
    _directory: tempfile::TempDir,
    path: PathBuf,
}

impl TemporaryRapidgzipIndex {
    fn new() -> io::Result<Self> {
        let directory = tempfile::Builder::new()
            .prefix("ptg2-rapidgzip-index-")
            .tempdir()?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;

            std::fs::set_permissions(directory.path(), std::fs::Permissions::from_mode(0o700))?;
        }
        let path = directory.path().join("input.index");
        Ok(Self {
            _directory: directory,
            path,
        })
    }

    fn byte_len(&self) -> u64 {
        self.path
            .metadata()
            .map(|metadata| metadata.len())
            .unwrap_or(0)
    }

    fn harden_file_permissions(&self) -> io::Result<()> {
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;

            std::fs::set_permissions(&self.path, std::fs::Permissions::from_mode(0o600))?;
        }
        Ok(())
    }
}

struct CompactIndexedReorder {
    index: TemporaryRapidgzipIndex,
    provider_references: TopLevelArrayRange,
    in_network_ranges: Vec<IndexedInNetworkRange>,
    indexed_range_producers_requested: usize,
    in_network_object_count: u64,
    decoder_threads: usize,
}

struct CompactPlainReorder {
    provider_references: TopLevelArrayRange,
    in_network: TopLevelArrayRange,
    in_network_object_count: u64,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct IndexedInNetworkRange {
    offset: u64,
    length: u64,
    object_count: u64,
}

impl IndexedInNetworkRange {
    fn end(self) -> u64 {
        self.offset.saturating_add(self.length)
    }

    fn payload(self, range_id: usize, decoder_threads: usize) -> Value {
        json!({
            "range_id": range_id,
            "offset": self.offset,
            "length": self.length,
            "object_count": self.object_count,
            "decoder_threads": decoder_threads,
        })
    }
}

struct CompactByteScanOptions {
    preflight_metrics: CompactPreflightMetrics,
    rapidgzip_config: RapidgzipConfig,
    indexed_reorder: Option<CompactIndexedReorder>,
    plain_reorder: Option<CompactPlainReorder>,
}

enum IndexedReaderStage {
    Prefix,
    Range,
    Suffix,
    Complete,
}

struct WrappedIndexedRangeReader {
    prefix: Cursor<Vec<u8>>,
    range: Box<dyn Read>,
    suffix: Cursor<Vec<u8>>,
    bytes_remaining: u64,
    stage: IndexedReaderStage,
}

impl WrappedIndexedRangeReader {
    fn new(range: Box<dyn Read>, length: u64, prefix: &[u8], suffix: &[u8]) -> Self {
        Self {
            prefix: Cursor::new(prefix.to_vec()),
            range,
            suffix: Cursor::new(suffix.to_vec()),
            bytes_remaining: length,
            stage: IndexedReaderStage::Prefix,
        }
    }

    fn finish_range(&mut self) -> io::Result<()> {
        let mut trailing_byte = [0u8; 1];
        match self.range.read(&mut trailing_byte)? {
            0 => Ok(()),
            _ => Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "rapidgzip indexed range emitted extra bytes",
            )),
        }
    }
}

impl Read for WrappedIndexedRangeReader {
    fn read(&mut self, buffer: &mut [u8]) -> io::Result<usize> {
        if buffer.is_empty() {
            return Ok(0);
        }
        loop {
            match self.stage {
                IndexedReaderStage::Prefix => {
                    let read = self.prefix.read(buffer)?;
                    if read > 0 {
                        return Ok(read);
                    }
                    self.stage = IndexedReaderStage::Range;
                }
                IndexedReaderStage::Range => {
                    if self.bytes_remaining == 0 {
                        self.finish_range()?;
                        self.stage = IndexedReaderStage::Suffix;
                        continue;
                    }
                    let read_limit = buffer
                        .len()
                        .min(self.bytes_remaining.try_into().unwrap_or(usize::MAX));
                    let read = self.range.read(&mut buffer[..read_limit])?;
                    if read == 0 {
                        return Err(io::Error::new(
                            io::ErrorKind::UnexpectedEof,
                            "rapidgzip indexed range ended early",
                        ));
                    }
                    self.bytes_remaining = self.bytes_remaining.saturating_sub(read as u64);
                    return Ok(read);
                }
                IndexedReaderStage::Suffix => {
                    let read = self.suffix.read(buffer)?;
                    if read > 0 {
                        return Ok(read);
                    }
                    self.stage = IndexedReaderStage::Complete;
                }
                IndexedReaderStage::Complete => return Ok(0),
            }
        }
    }
}

struct IndexedRangeProducerOutput {
    range_id: usize,
    range: IndexedInNetworkRange,
    decoder_threads: usize,
    elapsed_seconds: f64,
    rate_count: u64,
    blocked_micros: u128,
    compressed_bytes: u64,
    raw_chunk_stats: RawChunkStats,
}

impl IndexedRangeProducerOutput {
    fn payload(&self) -> Value {
        json!({
            "range_id": self.range_id,
            "offset": self.range.offset,
            "length": self.range.length,
            "object_count": self.range.object_count,
            "decoder_threads": self.decoder_threads,
            "elapsed_seconds": self.elapsed_seconds,
            "rate_count": self.rate_count,
            "blocked_seconds": seconds_from_micros(self.blocked_micros),
            "raw_chunk_count": self.raw_chunk_stats.chunk_count,
            "raw_chunk_total_bytes": self.raw_chunk_stats.total_bytes,
            "raw_chunk_max_bytes": self.raw_chunk_stats.max_bytes,
            "raw_chunk_max_rates": self.raw_chunk_stats.max_rates,
            "queue_high_water": self.raw_chunk_stats.queue_high_water,
            "queue_blocked_sends": self.raw_chunk_stats.queue_blocked_sends,
            "compressed_bytes": self.compressed_bytes,
        })
    }
}

struct IndexedRangeProducerConfig {
    path: PathBuf,
    rapidgzip_config: RapidgzipConfig,
    index_path: PathBuf,
    range_id: usize,
    range: IndexedInNetworkRange,
    object_ordinal_base: u64,
    tx: Sender<WorkerJob>,
    cancelled: Arc<AtomicBool>,
    queue_bytes: Arc<QueueByteMetrics>,
    recycle_rx: Receiver<RawRateChunk>,
    progress: Arc<IndexedProducerProgress>,
    enqueue_options: InNetworkEnqueueOptions,
}

#[derive(Default)]
struct IndexedProducerProgress {
    completed_objects: AtomicU64,
    completed_rates: AtomicU64,
    completed_raw_bytes: AtomicU64,
}

impl IndexedProducerProgress {
    fn record_object(&self, rate_count: u64, raw_bytes: u64) {
        self.completed_rates
            .fetch_add(rate_count, Ordering::Relaxed);
        self.completed_raw_bytes
            .fetch_add(raw_bytes, Ordering::Relaxed);
        self.completed_objects.fetch_add(1, Ordering::Release);
    }
}

fn indexed_range_decoder_thread_allocation(
    total_decoder_threads: usize,
    range_count: usize,
) -> Vec<usize> {
    if range_count == 0 {
        return Vec::new();
    }
    debug_assert!(total_decoder_threads >= range_count);
    let base = total_decoder_threads / range_count;
    let remainder = total_decoder_threads % range_count;
    (0..range_count)
        .map(|range_id| base + usize::from(range_id < remainder))
        .collect()
}

fn emit_indexed_range_progress(
    path: &Path,
    expected_objects: u64,
    progress: &IndexedProducerProgress,
    started_at: Instant,
    done: bool,
) {
    let completed_objects = progress
        .completed_objects
        .load(Ordering::Acquire)
        .min(expected_objects);
    let completed_rates = progress.completed_rates.load(Ordering::Relaxed);
    let completed_raw_bytes = progress.completed_raw_bytes.load(Ordering::Relaxed);
    let elapsed_seconds = started_at.elapsed().as_secs_f64();
    let percent = if expected_objects > 0 {
        completed_objects as f64 * 100.0 / expected_objects as f64
    } else {
        0.0
    };
    let eta_seconds = if completed_objects > 0 && completed_objects < expected_objects {
        Some(
            elapsed_seconds * (expected_objects - completed_objects) as f64
                / completed_objects as f64,
        )
    } else {
        None
    };
    eprintln!(
        "PTG2_SCANNER_PROGRESS\tpath={}\tprogress_basis=indexed_objects\tindexed_objects_completed={}\tindexed_objects_total={}\tpercent={:.2}\tindexed_rates_completed={}\tindexed_raw_bytes_completed={}\telapsed_seconds={:.1}\teta_seconds={}\tdone={}",
        path.display(),
        completed_objects,
        expected_objects,
        percent,
        completed_rates,
        completed_raw_bytes,
        elapsed_seconds,
        eta_seconds
            .map(|value| format!("{value:.1}"))
            .unwrap_or_else(|| "unknown".to_string()),
        if done { "true" } else { "false" },
    );
}

fn emit_plain_reorder_progress(
    path: &Path,
    expected_objects: u64,
    completed_objects: u64,
    completed_rates: u64,
    started_at: Instant,
    done: bool,
) {
    let completed_objects = completed_objects.min(expected_objects);
    let elapsed_seconds = started_at.elapsed().as_secs_f64();
    let percent = if expected_objects > 0 {
        completed_objects as f64 * 100.0 / expected_objects as f64
    } else {
        0.0
    };
    let eta_seconds = if completed_objects > 0 && completed_objects < expected_objects {
        Some(
            elapsed_seconds * (expected_objects - completed_objects) as f64
                / completed_objects as f64,
        )
    } else {
        None
    };
    eprintln!(
        "PTG2_SCANNER_PROGRESS\tpath={}\tprogress_basis=plain_reordered_objects\tin_network_objects_completed={}\tin_network_objects_total={}\tpercent={:.2}\tnegotiated_rates_completed={}\telapsed_seconds={:.1}\teta_seconds={}\tdone={}",
        path.display(),
        completed_objects,
        expected_objects,
        percent,
        completed_rates,
        elapsed_seconds,
        eta_seconds
            .map(|value| format!("{value:.1}"))
            .unwrap_or_else(|| "unknown".to_string()),
        if done { "true" } else { "false" },
    );
}

fn produce_indexed_in_network_range(
    config: IndexedRangeProducerConfig,
) -> io::Result<IndexedRangeProducerOutput> {
    let started_at = Instant::now();
    let compressed_bytes_read = Arc::new(AtomicU64::new(0));
    let range_spec = format!("{}@{}", config.range.length, config.range.offset);
    let range_reader = config
        .rapidgzip_config
        .open_indexed_ranges_reader_cancellable(
            &config.path,
            Arc::clone(&compressed_bytes_read),
            &config.index_path,
            &range_spec,
            Arc::clone(&config.cancelled),
        )?;
    let range_reader = strict_utf8_reader_preserving_bom(range_reader);
    let wrapped_reader =
        WrappedIndexedRangeReader::new(range_reader, config.range.length, b"[", b"]");
    let (_event_tx, event_rx) = unbounded::<CopyFileEvent>();
    let mut sink = io::sink();
    let mut copy_file_event_gate = CopyFileEventGate::passthrough();
    let mut blocked_micros = 0u128;
    let mut raw_chunk_stats = RawChunkStats {
        queue_bytes: config.queue_bytes,
        recycle_rx: Some(config.recycle_rx),
        ..RawChunkStats::default()
    };
    let mut object_count = 0u64;
    let mut rate_count = 0u64;
    let mut reported_raw_bytes = 0u64;

    if config.enqueue_options.parse_in_workers {
        let mut byte_reader = BufferedJsonByteReader::new(wrapped_reader);
        byte_reader.expect_byte(b'[')?;
        let mut first_item = true;
        while next_array_value(&mut byte_reader, &mut first_item)? {
            let mut enqueue_io = InNetworkEnqueueIo {
                tx: &config.tx,
                event_rx: &event_rx,
                writer: &mut sink,
                copy_file_event_gate: &mut copy_file_event_gate,
                cancelled: Some(&config.cancelled),
                producer_blocked_micros: &mut blocked_micros,
                raw_chunk_stats: &mut raw_chunk_stats,
            };
            let object_rate_count = enqueue_in_network_raw_byte_scan(
                &mut byte_reader,
                &mut enqueue_io,
                InNetworkEnqueueOptions {
                    object_ordinal: config.object_ordinal_base.saturating_add(object_count),
                    ..config.enqueue_options
                },
            )?;
            rate_count = rate_count.saturating_add(object_rate_count);
            object_count = object_count.saturating_add(1);
            let current_raw_bytes = raw_chunk_stats.total_bytes;
            config.progress.record_object(
                object_rate_count,
                current_raw_bytes.saturating_sub(reported_raw_bytes),
            );
            reported_raw_bytes = current_raw_bytes;
        }
        byte_reader.drain_inner_to_eof()?;
    } else {
        let mut json_reader = JsonStreamReader::new(wrapped_reader);
        json_reader.begin_array().map_err(to_io_error)?;
        while json_reader.has_next().map_err(to_io_error)? {
            let mut enqueue_io = InNetworkEnqueueIo {
                tx: &config.tx,
                event_rx: &event_rx,
                writer: &mut sink,
                copy_file_event_gate: &mut copy_file_event_gate,
                cancelled: Some(&config.cancelled),
                producer_blocked_micros: &mut blocked_micros,
                raw_chunk_stats: &mut raw_chunk_stats,
            };
            let object_rate_count = enqueue_in_network_struson(
                &mut json_reader,
                &mut enqueue_io,
                InNetworkEnqueueOptions {
                    object_ordinal: config.object_ordinal_base.saturating_add(object_count),
                    ..config.enqueue_options
                },
            )?;
            rate_count = rate_count.saturating_add(object_rate_count);
            object_count = object_count.saturating_add(1);
            let current_raw_bytes = raw_chunk_stats.total_bytes;
            config.progress.record_object(
                object_rate_count,
                current_raw_bytes.saturating_sub(reported_raw_bytes),
            );
            reported_raw_bytes = current_raw_bytes;
        }
        json_reader.end_array().map_err(to_io_error)?;
        drain_reader_to_eof(json_reader.reader_mut())?;
    }
    if object_count != config.range.object_count {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "indexed range {} parsed {object_count} in-network objects, expected {}",
                config.range_id, config.range.object_count
            ),
        ));
    }

    Ok(IndexedRangeProducerOutput {
        range_id: config.range_id,
        range: config.range,
        decoder_threads: config.rapidgzip_config.decoder_threads,
        elapsed_seconds: started_at.elapsed().as_secs_f64(),
        rate_count,
        blocked_micros,
        compressed_bytes: compressed_bytes_read.load(Ordering::Relaxed),
        raw_chunk_stats,
    })
}

fn start_semantic_progress_reporter(
    path: &Path,
    total_bytes: u64,
    compressed_bytes_read: &Arc<AtomicU64>,
    semantic_progress: Option<&Arc<ScannerSemanticProgress>>,
    started_at: Instant,
) -> io::Result<Option<ScannerSemanticProgressReporter>> {
    semantic_progress
        .map(|progress| {
            ScannerSemanticProgressReporter::start(
                path,
                total_bytes,
                Arc::clone(compressed_bytes_read),
                Arc::clone(progress),
                started_at,
            )
        })
        .transpose()
}

fn validate_provider_source_capture_append(
    buffered_bytes: usize,
    capture_start: usize,
) -> io::Result<()> {
    let captured_bytes = buffered_bytes
        .checked_sub(capture_start)
        .and_then(|value| value.checked_add(1))
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "provider source capture byte count is invalid",
            )
        })?;
    validate_provider_source_record_size(captured_bytes)
}

fn scan_compact_byte_top_level_parallel(
    path: &Path,
    context: CompactContext,
    worker_count: usize,
    queue_size: usize,
    copy_paths: CopyPathConfig,
    compact_copy_rotate_bytes: u64,
    options: CompactByteScanOptions,
) -> io::Result<()> {
    let factor_mode = configured_v4_factor_mode(&copy_paths)?;
    let CompactByteScanOptions {
        preflight_metrics,
        rapidgzip_config,
        indexed_reorder,
        plain_reorder,
    } = options;
    let total_bytes = path.metadata().map(|metadata| metadata.len()).unwrap_or(0);
    let compressed_bytes_read = Arc::new(AtomicU64::new(0));
    let indexed_reorder_used = indexed_reorder.is_some();
    let plain_reorder_used = plain_reorder.is_some();
    let top_level_reorder_used = indexed_reorder_used || plain_reorder_used;
    let provider_reference_order_label = if top_level_reorder_used {
        "after_in_network"
    } else {
        "before_in_network"
    };
    let indexed_reorder_bytes = indexed_reorder
        .as_ref()
        .map(|reorder| reorder.index.byte_len())
        .unwrap_or(0);
    let indexed_reorder_decoder_threads = indexed_reorder
        .as_ref()
        .map(|reorder| reorder.decoder_threads)
        .unwrap_or(0);
    let indexed_range_producers_requested = indexed_reorder
        .as_ref()
        .map(|reorder| reorder.indexed_range_producers_requested)
        .unwrap_or(0);
    let indexed_range_count = indexed_reorder
        .as_ref()
        .map(|reorder| reorder.in_network_ranges.len())
        .unwrap_or(0);
    let indexed_range_producers_selected = indexed_range_count;
    let indexed_range_decoder_threads = indexed_range_decoder_thread_allocation(
        rapidgzip_config.decoder_threads,
        indexed_range_count,
    );
    let indexed_range_decoder_threads_selected: usize = indexed_range_decoder_threads.iter().sum();
    let indexed_range_coverage_bytes: u64 = indexed_reorder
        .as_ref()
        .map(|reorder| {
            reorder
                .in_network_ranges
                .iter()
                .map(|range| range.length)
                .sum()
        })
        .unwrap_or(0);
    let indexed_range_coverage_objects = indexed_reorder
        .as_ref()
        .map(|reorder| reorder.in_network_object_count)
        .unwrap_or(0);
    let plain_provider_range_offset = plain_reorder
        .as_ref()
        .map(|reorder| reorder.provider_references.offset);
    let plain_provider_range_bytes = plain_reorder
        .as_ref()
        .map(|reorder| reorder.provider_references.length)
        .unwrap_or(0);
    let plain_in_network_range_offset = plain_reorder
        .as_ref()
        .map(|reorder| reorder.in_network.offset);
    let plain_in_network_range_bytes = plain_reorder
        .as_ref()
        .map(|reorder| reorder.in_network.length)
        .unwrap_or(0);
    let plain_in_network_object_count = plain_reorder
        .as_ref()
        .map(|reorder| reorder.in_network_object_count)
        .unwrap_or(0);
    let indexed_range_config_payload = indexed_reorder
        .as_ref()
        .map(|reorder| {
            reorder
                .in_network_ranges
                .iter()
                .copied()
                .enumerate()
                .map(|(range_id, range)| {
                    range.payload(range_id, indexed_range_decoder_threads[range_id])
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let mut reader: Box<dyn Read> = if let Some(reorder) = indexed_reorder.as_ref() {
        let ranges = format!(
            "{}@{}",
            reorder.provider_references.length, reorder.provider_references.offset,
        );
        let range_reader = open_indexed_ranges_reader(
            path,
            Arc::clone(&compressed_bytes_read),
            &rapidgzip_config,
            &reorder.index.path,
            &ranges,
        )?;
        let range_reader = strict_utf8_reader_preserving_bom(range_reader);
        Box::new(WrappedIndexedRangeReader::new(
            range_reader,
            reorder.provider_references.length,
            br#"{"provider_references":"#,
            br#","in_network":[]}"#,
        ))
    } else if let Some(reorder) = plain_reorder.as_ref() {
        let range_reader = open_plain_range_json_reader(
            path,
            reorder.provider_references.offset,
            reorder.provider_references.length,
            Arc::clone(&compressed_bytes_read),
        )?;
        Box::new(WrappedIndexedRangeReader::new(
            range_reader,
            reorder.provider_references.length,
            br#"{"provider_references":"#,
            br#","in_network":[]}"#,
        ))
    } else {
        open_full_scan_json_reader(path, Arc::clone(&compressed_bytes_read), &rapidgzip_config)?
    };
    let progress_bytes_interval = progress_interval(
        "HLTHPRT_PTG2_SCANNER_PROGRESS_BYTES",
        DEFAULT_PROGRESS_BYTES,
    );
    let mut next_progress_bytes = progress_bytes_interval;
    let progress_objects_interval = progress_interval(
        "HLTHPRT_PTG2_SCANNER_PROGRESS_OBJECTS",
        DEFAULT_PROGRESS_OBJECTS,
    );
    let mut next_progress_objects = progress_objects_interval;
    let mut object_counts: HashMap<String, u64> = HashMap::new();
    let started_at = Instant::now();
    let negotiated_rate_chunk_size = split_interval(
        "HLTHPRT_PTG2_RUST_SPLIT_NEGOTIATED_RATES",
        DEFAULT_SPLIT_NEGOTIATED_RATES,
    );
    let raw_chunk_byte_limit =
        env_usize("HLTHPRT_PTG2_RUST_RAW_CHUNK_BYTES", DEFAULT_RAW_CHUNK_BYTES);
    let provider_ref_worker_count =
        env_usize("HLTHPRT_PTG2_RUST_PROVIDER_REF_WORKERS", worker_count).max(1);
    if copy_paths
        .manifest_provider_group_tax_identity_sidecar
        .is_some()
        || copy_paths
            .manifest_provider_group_tax_identity_v2_sidecar
            .is_some()
    {
        let token_secret_path = env::var(TIN_TOKEN_SECRET_FILE_ENV).map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "PTG TIN token secret file must be configured",
            )
        })?;
        let source_witness_scratch_path =
            env::var_os("HLTHPRT_PTG2_SOURCE_WITNESS_SCRATCH_DIR").map(PathBuf::from);
        validate_runtime_tax_identity_output_paths(
            &copy_paths,
            path,
            Path::new(&token_secret_path),
            source_witness_scratch_path.as_deref(),
            worker_count,
            provider_ref_worker_count,
        )?;
    }
    context
        .source_witness
        .configure_provider_spools(provider_ref_worker_count)?;
    context.source_witness.configure_rate_spools(worker_count)?;
    let provider_ref_queue_size = env_usize(
        "HLTHPRT_PTG2_RUST_PROVIDER_REF_QUEUE",
        provider_ref_worker_count.max(queue_size).max(1),
    )
    .max(provider_ref_worker_count)
    .max(1);
    let provider_ref_chunk_items = env_usize(
        "HLTHPRT_PTG2_RUST_PROVIDER_REF_CHUNK_ITEMS",
        DEFAULT_PROVIDER_REF_CHUNK_ITEMS,
    )
    .max(1);
    let provider_ref_raw_chunk_byte_limit = env_usize(
        "HLTHPRT_PTG2_RUST_PROVIDER_REF_RAW_CHUNK_BYTES",
        raw_chunk_byte_limit,
    )
    .max(1);
    let parse_in_workers = env_bool(
        "HLTHPRT_PTG2_RUST_PARSE_IN_WORKERS",
        DEFAULT_PARSE_IN_WORKERS,
    );
    let bounded_queue_size = queue_size.max(worker_count).max(1);
    let event_queue_size = env_usize(
        "HLTHPRT_PTG2_RUST_EVENT_QUEUE",
        (bounded_queue_size * 4).max(worker_count),
    )
    .max(1);
    let dedupe = Arc::new(configured_shared_dedupe(
        worker_count,
        !copy_paths.manifest_only,
        factor_mode,
        copy_paths
            .manifest_provider_group_tax_identity_v2_sidecar
            .is_some(),
    )?);
    let provider_graph_v4_factor_cache = Arc::new(
        V4ProviderSetFactorSharedCache::configured_for_mode(factor_mode)?,
    );
    let semantic_progress = provider_graph_v4_factor_cache.semantic_progress_if_enabled();
    let mut semantic_progress_reporter = start_semantic_progress_reporter(
        path,
        total_bytes,
        &compressed_bytes_read,
        semantic_progress.as_ref(),
        started_at,
    )?;
    let manifest_sidecars = if copy_paths.has_manifest_sidecar_paths() {
        Some(Arc::new(Mutex::new(ManifestSidecarCollector::for_import(
            &copy_paths,
        )?)))
    } else {
        None
    };
    let (tx, rx) = bounded::<WorkerJob>(bounded_queue_size);
    let (event_tx, event_rx) = bounded::<CopyFileEvent>(event_queue_size);
    let mut copy_file_event_gate = if context.invalid_price_exclusion.is_some() {
        CopyFileEventGate::deferred_for_scan(&copy_paths, worker_count, provider_ref_worker_count)?
    } else {
        CopyFileEventGate::passthrough()
    };
    let indexed_cancelled = Arc::new(AtomicBool::new(false));
    let indexed_producer_progress = Arc::new(IndexedProducerProgress::default());
    let stdout = io::stdout();
    let mut writer = BufWriter::new(stdout.lock());
    let mut producer_blocked_micros = 0u128;
    let mut provider_ref_producer_blocked_micros = 0u128;
    let mut raw_chunk_stats = RawChunkStats::default();
    let mut provider_ref_raw_chunk_stats = RawChunkStats::default();
    let raw_recycle_tx = raw_chunk_stats.enable_recycling(
        bounded_queue_size
            .saturating_add(worker_count)
            .saturating_add(1),
    );
    let provider_ref_recycle_tx = provider_ref_raw_chunk_stats.enable_recycling(
        provider_ref_queue_size
            .saturating_add(provider_ref_worker_count)
            .saturating_add(1),
    );
    let mut provider_refs_seconds = 0.0f64;
    let mut provider_capture_seconds = 0.0f64;
    let mut provider_worker_join_seconds = 0.0f64;
    let mut provider_map_merge_seconds = 0.0f64;
    let mut provider_definition_output_seconds = 0.0f64;
    let provider_capture_compressed_bytes: u64;
    let mut in_network_enqueue_seconds = 0.0f64;
    let in_network_compressed_bytes: u64;
    let mut worker_join_seconds = 0.0f64;
    let mut sidecar_finalize_lock_wait_seconds = 0.0f64;
    let mut sidecar_merge_write_seconds = 0.0f64;
    let mut provider_worker_metrics: Vec<ProviderRefWorkerMetrics>;
    let mut compact_worker_metrics = Vec::new();
    let mut invalid_price_exclusions = Vec::new();
    let mut invalid_price_emptied_rates = 0u64;
    let mut indexed_range_metrics = Vec::new();

    emit_json_record(
        &mut writer,
        "scanner_config",
        &json!({
            "worker_count": worker_count,
            "work_queue": bounded_queue_size,
            "event_queue": event_queue_size,
            "event_queue_unbounded": false,
            "split_negotiated_rates": negotiated_rate_chunk_size,
            "raw_chunk_bytes": raw_chunk_byte_limit,
            "read_buffer_bytes": READ_BUF_SIZE,
            "parse_in_workers": parse_in_workers,
            "local_dedupe_entries_per_kind_per_worker": env_usize_allow_zero("HLTHPRT_PTG2_RUST_LOCAL_DEDUPE_ENTRIES", 131_072),
            "raw_rate_byte_capture": parse_in_workers,
            "provider_refs_in_workers": true,
            "provider_ref_workers": provider_ref_worker_count,
            "provider_ref_queue": provider_ref_queue_size,
            "provider_ref_chunk_items": provider_ref_chunk_items,
            "provider_ref_raw_chunk_bytes": provider_ref_raw_chunk_byte_limit,
            "provider_source_record_max_bytes": PROVIDER_SOURCE_RECORD_MAX_BYTES,
            "top_level_byte_scan": true,
            "top_level_byte_scan_requested": true,
            "top_level_byte_scan_selected": true,
            "top_level_byte_scan_fallback_reason": Value::Null,
            "execution_mode": if indexed_reorder_used {
                "parallel_top_level_bytes_indexed_reorder"
            } else if plain_reorder_used {
                "parallel_top_level_bytes_plain_range_reorder"
            } else {
                "parallel_top_level_bytes"
            },
            "decompression": if rapidgzip_config.enabled { "rapidgzip" } else { "flate2" },
            "rapidgzip_threads": if rapidgzip_config.enabled {
                Some(rapidgzip_config.decoder_threads)
            } else {
                None
            },
            "provider_reference_order": provider_reference_order_label,
            "rapidgzip_index_bytes": indexed_reorder_bytes,
            "rapidgzip_index_threads": indexed_reorder_decoder_threads,
            "indexed_range_producers_requested": indexed_range_producers_requested,
            "indexed_range_producers_selected": indexed_range_producers_selected,
            "indexed_range_decoder_threads_selected": indexed_range_decoder_threads_selected,
            "indexed_range_count": indexed_range_count,
            "indexed_ranges": indexed_range_config_payload,
            "indexed_range_coverage_bytes": indexed_range_coverage_bytes,
            "indexed_range_coverage_object_count": indexed_range_coverage_objects,
            "plain_range_reorder": plain_reorder_used,
            "plain_provider_range_offset": plain_provider_range_offset,
            "plain_provider_range_bytes": plain_provider_range_bytes,
            "plain_in_network_range_offset": plain_in_network_range_offset,
            "plain_in_network_range_bytes": plain_in_network_range_bytes,
            "plain_in_network_object_count": plain_in_network_object_count,
            "full_decompression_passes": if indexed_reorder_used { 2 } else { 1 },
            "order_probe_partial_pass": provider_reference_order_label != "missing",
            "order_detection_seconds": preflight_metrics.order_detection_seconds,
            "order_detection_compressed_bytes": preflight_metrics.order_detection_compressed_bytes,
            "order_detection_compressed_mib_s": preflight_metrics.compressed_mib_s(),
            "raw_buffer_recycling": true,
            "provider_map_merge": "ordered_pairwise_parallel",
            "scanner_metric_contract_version": 2,
            "snapshot_arch": REQUIRED_SNAPSHOT_ARCH,
            "storage_generation": REQUIRED_STORAGE_GENERATION,
            "serving_row_semantics": "source_multiset_v1",
            "group_negotiated_rate_chunks": false,
            "factor_mode": factor_mode,
            "provider_graph_v4_factor_mode": factor_mode,
            "provider_graph_v4_factor_cache_max_bytes": provider_graph_v4_factor_cache.max_estimated_bytes,
            "provider_graph_v4_inline_transform_cache_max_bytes": provider_graph_v4_factor_cache.inline_transforms.snapshot().max_estimated_bytes,
            "provider_npi_sidecar": copy_paths.manifest_provider_npi_sidecar.is_some(),
            "price_forward_sidecar": copy_paths.manifest_price_forward_sidecar.is_some(),
            "serving_run_format": SERVING_RUN_FORMAT,
            "serving_run_version": SERVING_RUN_FORMAT_VERSION,
            "serving_run_partition_count": env_usize("HLTHPRT_PTG2_V3_SERVING_RUN_PARTITIONS", DEFAULT_V3_SERVING_RUN_PARTITIONS),
            "serving_run_partition_buffer_bytes": env_usize("HLTHPRT_PTG2_V3_SERVING_RUN_PARTITION_BUFFER_BYTES", DEFAULT_V3_SERVING_RUN_PARTITION_BUFFER_BYTES),
            "panic_strategy": "unwind",
        }),
    )?;
    writer.flush()?;

    let provider_ref_paths = copy_paths.for_provider_refs();
    let (provider_tx, mut provider_handles) = spawn_provider_ref_workers(
        provider_ref_worker_count,
        provider_ref_queue_size,
        ProviderRefWorkerConfig {
            dedupe: Arc::clone(&dedupe),
            source_witness: Arc::clone(&context.source_witness),
            manifest_sidecars: None,
            copy_paths: CopyPathConfig::default(),
            rotate_bytes: compact_copy_rotate_bytes,
            queue_bytes: Arc::clone(&provider_ref_raw_chunk_stats.queue_bytes),
            recycle_tx: Some(provider_ref_recycle_tx),
            allow_empty_npi_tin_only: factor_mode,
        },
    );
    let mut raw_refs = provider_ref_raw_chunk_stats.allocate_chunk(
        provider_ref_chunk_items,
        provider_ref_raw_chunk_byte_limit.min(READ_BUF_SIZE),
    );
    let provider_refs_started_at = Instant::now();
    let provider_refs_compressed_started_at = compressed_bytes_read.load(Ordering::Relaxed);

    let mut buffer = vec![0u8; READ_BUF_SIZE];
    let mut depth: usize = 0;
    let mut in_provider_refs = false;
    let mut active_array_depth: usize = 0;
    let mut capture_depth: usize = 0;
    let mut capture_start: usize = 0;
    let mut provider_capture_started_at: Option<Instant> = None;
    let mut in_string = false;
    let mut escape = false;
    let mut top_level_key_buffer = Vec::with_capacity(32);
    let mut capturing_top_level_key = false;
    let mut candidate_key: Option<CompactTopLevelArrayKey> = None;
    let mut pending_key: Option<CompactTopLevelArrayKey> = None;

    loop {
        let read = match reader.read(&mut buffer) {
            Ok(read) => read,
            Err(error) => {
                drop(provider_tx);
                match join_provider_ref_workers(&mut writer, std::mem::take(&mut provider_handles))
                {
                    Ok(joined_provider_refs) => {
                        for event in joined_provider_refs.events {
                            copy_file_event_gate.publish(&mut writer, event)?;
                        }
                    }
                    Err(cleanup_error) => {
                        eprintln!("PTG2_SCANNER_PROVIDER_CLEANUP_FAILED\terror={cleanup_error}");
                    }
                }
                drain_copy_file_events(&event_rx, &mut writer, &mut copy_file_event_gate)?;
                writer.flush()?;
                return Err(error);
            }
        };
        if read == 0 {
            break;
        }
        for (idx, &byte) in buffer[..read].iter().enumerate() {
            if capture_depth > 0 {
                validate_provider_source_capture_append(raw_refs.byte_len(), capture_start)?;
                raw_refs.bytes.push(byte);
            }

            if in_string {
                if escape {
                    if capturing_top_level_key {
                        top_level_key_buffer.push(byte);
                    }
                    escape = false;
                } else if byte == b'\\' {
                    if capturing_top_level_key {
                        top_level_key_buffer.push(byte);
                    }
                    escape = true;
                } else if byte == b'"' {
                    in_string = false;
                    if capturing_top_level_key {
                        candidate_key = match top_level_key_buffer.as_slice() {
                            b"provider_references" => {
                                Some(CompactTopLevelArrayKey::ProviderReferences)
                            }
                            b"in_network" => Some(CompactTopLevelArrayKey::InNetwork),
                            _ => None,
                        };
                        capturing_top_level_key = false;
                    }
                } else if capturing_top_level_key {
                    top_level_key_buffer.push(byte);
                }
                continue;
            }

            if byte == b'"' {
                in_string = true;
                escape = false;
                if depth == 1 && !in_provider_refs && capture_depth == 0 {
                    top_level_key_buffer.clear();
                    capturing_top_level_key = true;
                } else {
                    capturing_top_level_key = false;
                }
                continue;
            }

            if let Some(candidate) = candidate_key.take() {
                if byte.is_ascii_whitespace() {
                    candidate_key = Some(candidate);
                    continue;
                }
                if byte == b':' {
                    pending_key = Some(candidate);
                    continue;
                }
            }

            if let Some(pending) = pending_key.take() {
                if byte.is_ascii_whitespace() {
                    pending_key = Some(pending);
                    continue;
                }
                if byte == b'['
                    && depth == 1
                    && matches!(pending, CompactTopLevelArrayKey::ProviderReferences)
                {
                    depth += 1;
                    in_provider_refs = true;
                    active_array_depth = depth;
                    provider_capture_started_at = Some(Instant::now());
                    continue;
                }
                if byte == b'['
                    && depth == 1
                    && matches!(pending, CompactTopLevelArrayKey::InNetwork)
                {
                    if !raw_refs.is_empty() {
                        provider_ref_raw_chunk_stats
                            .record_capture_batch(provider_capture_started_at.take());
                        provider_ref_raw_chunk_stats.record(raw_refs.len(), raw_refs.byte_len());
                        let batch = provider_ref_raw_chunk_stats.take_filled_chunk(
                            &mut raw_refs,
                            provider_ref_chunk_items,
                            provider_ref_raw_chunk_byte_limit,
                        );
                        send_provider_ref_batch(
                            &provider_tx,
                            &event_rx,
                            &mut writer,
                            &mut provider_ref_producer_blocked_micros,
                            &mut provider_ref_raw_chunk_stats,
                            &mut copy_file_event_gate,
                            batch,
                        )?;
                    }
                    drop(provider_tx);
                    provider_capture_seconds += provider_refs_started_at.elapsed().as_secs_f64();
                    provider_capture_compressed_bytes = compressed_bytes_read
                        .load(Ordering::Relaxed)
                        .saturating_sub(provider_refs_compressed_started_at);
                    let mut joined_provider_refs = join_provider_ref_workers(
                        &mut writer,
                        std::mem::take(&mut provider_handles),
                    )?;
                    context.source_witness.seal_provider_sources()?;
                    let provider_definition_output_started_at = Instant::now();
                    let provider_definition_outputs = emit_provider_definition_outputs(
                        &joined_provider_refs.provider_map,
                        provider_ref_worker_count,
                        &provider_ref_paths,
                        compact_copy_rotate_bytes,
                        ProviderRefBatchContext {
                            dedupe: &dedupe,
                            source_witness: &context.source_witness,
                            manifest_sidecars: manifest_sidecars.as_ref(),
                            allow_empty_npi_tin_only: factor_mode,
                            defer_definition_outputs: false,
                        },
                    )?;
                    provider_definition_output_seconds += provider_definition_output_started_at
                        .elapsed()
                        .as_secs_f64();
                    provider_worker_join_seconds += joined_provider_refs.worker_join_seconds;
                    provider_map_merge_seconds += joined_provider_refs.map_merge_seconds;
                    provider_refs_seconds += provider_capture_seconds
                        + joined_provider_refs.worker_join_seconds
                        + joined_provider_refs.map_merge_seconds
                        + provider_definition_output_seconds;
                    provider_worker_metrics = joined_provider_refs.worker_metrics;
                    for output in provider_definition_outputs {
                        if let Some(metrics) = provider_worker_metrics
                            .iter_mut()
                            .find(|metrics| metrics.worker_id == output.worker_id)
                        {
                            metrics.elapsed_micros =
                                metrics.elapsed_micros.saturating_add(output.elapsed_micros);
                        }
                        joined_provider_refs.events.extend(output.events);
                    }
                    drain_copy_file_events(&event_rx, &mut writer, &mut copy_file_event_gate)?;
                    for event in joined_provider_refs.events {
                        copy_file_event_gate.publish(&mut writer, event)?;
                    }
                    writer.flush()?;

                    let provider_group_conflicts = joined_provider_refs.provider_group_conflicts;
                    let conflicting_provider_refs = Arc::new(provider_group_conflicts.keys());
                    let mut provider_map = joined_provider_refs.provider_map;
                    record_and_clear_provider_identifier_quarantine(&mut provider_map, &dedupe)?;
                    let provider_map = Arc::new(provider_map);
                    let mut handles = Vec::with_capacity(worker_count);
                    for worker_id in 0..worker_count {
                        let worker_rx = rx.clone();
                        let worker_event_tx = event_tx.clone();
                        let worker_provider_map = Arc::clone(&provider_map);
                        let worker_provider_group_conflicts =
                            Arc::clone(&conflicting_provider_refs);
                        let worker_dedupe = Arc::clone(&dedupe);
                        let worker_manifest_sidecars = manifest_sidecars.as_ref().map(Arc::clone);
                        let worker_copy_paths = copy_paths.clone();
                        let worker_context = context.clone();
                        let worker_provider_graph_v4_factor_cache =
                            Arc::clone(&provider_graph_v4_factor_cache);
                        let worker_queue_bytes = Arc::clone(&raw_chunk_stats.queue_bytes);
                        let worker_recycle_tx = raw_recycle_tx.clone();
                        let worker_cancelled = Arc::clone(&indexed_cancelled);
                        handles.push((
                            worker_id,
                            thread::spawn(move || {
                                let result = panic::catch_unwind(AssertUnwindSafe(|| {
                                    compact_worker_loop(
                                        worker_id,
                                        worker_rx,
                                        CompactWorkerConfig {
                                            event_tx: worker_event_tx,
                                            provider_map: worker_provider_map,
                                            provider_group_conflicts:
                                                worker_provider_group_conflicts,
                                            dedupe: worker_dedupe,
                                            manifest_sidecars: worker_manifest_sidecars,
                                            queue_bytes: worker_queue_bytes,
                                            recycle_tx: Some(worker_recycle_tx),
                                            copy_paths: worker_copy_paths,
                                            rotate_bytes: compact_copy_rotate_bytes,
                                            context: worker_context,
                                            provider_graph_v4_factor_cache:
                                                worker_provider_graph_v4_factor_cache,
                                            provider_graph_v4_factor_mode: factor_mode,
                                        },
                                    )
                                }));
                                match result {
                                    Ok(Ok(events)) => Ok(events),
                                    Ok(Err(err)) => {
                                        worker_cancelled.store(true, Ordering::Release);
                                        Err(err)
                                    }
                                    Err(payload) => {
                                        worker_cancelled.store(true, Ordering::Release);
                                        let message = panic_payload_message(payload.as_ref());
                                        Err(io::Error::other(format!(
                                            "compact worker {worker_id} panicked: {message}"
                                        )))
                                    }
                                }
                            }),
                        ));
                    }
                    drop(rx);

                    let mut prefix = Vec::with_capacity(read.saturating_sub(idx) + 1);
                    prefix.push(b'[');
                    prefix.extend_from_slice(&buffer[idx + 1..read]);
                    let in_network_started_at = Instant::now();
                    let in_network_compressed_started_at =
                        compressed_bytes_read.load(Ordering::Relaxed);
                    let producer_error: Option<io::Error>;
                    if let Some(reorder) = indexed_reorder.as_ref() {
                        let mut prefixed_reader = PrefixReader::new(prefix, reader);
                        drain_reader_to_eof(&mut prefixed_reader)?;
                        let mut producer_handles =
                            Vec::with_capacity(reorder.in_network_ranges.len());
                        let (producer_result_tx, producer_result_rx) =
                            unbounded::<(usize, io::Result<IndexedRangeProducerOutput>)>();
                        let mut object_ordinal_base = 0u64;
                        for (range_id, range) in
                            reorder.in_network_ranges.iter().copied().enumerate()
                        {
                            let mut range_rapidgzip_config = rapidgzip_config.clone();
                            range_rapidgzip_config.decoder_threads =
                                indexed_range_decoder_threads[range_id];
                            let producer_config = IndexedRangeProducerConfig {
                                path: path.to_path_buf(),
                                rapidgzip_config: range_rapidgzip_config,
                                index_path: reorder.index.path.clone(),
                                range_id,
                                range,
                                object_ordinal_base,
                                tx: tx.clone(),
                                cancelled: Arc::clone(&indexed_cancelled),
                                queue_bytes: Arc::clone(&raw_chunk_stats.queue_bytes),
                                recycle_rx: raw_chunk_stats
                                    .recycle_rx
                                    .as_ref()
                                    .expect("raw chunk recycling is enabled")
                                    .clone(),
                                progress: Arc::clone(&indexed_producer_progress),
                                enqueue_options: InNetworkEnqueueOptions {
                                    chunk_size: negotiated_rate_chunk_size,
                                    raw_chunk_byte_limit,
                                    parse_in_workers,
                                    object_ordinal: 0,
                                },
                            };
                            object_ordinal_base =
                                object_ordinal_base.saturating_add(range.object_count);
                            let producer_cancelled = Arc::clone(&indexed_cancelled);
                            let range_result_tx = producer_result_tx.clone();
                            producer_handles.push((
                                range_id,
                                thread::spawn(move || {
                                    let result = panic::catch_unwind(AssertUnwindSafe(|| {
                                        produce_indexed_in_network_range(producer_config)
                                    }));
                                    let result = match result {
                                        Ok(Ok(output)) => Ok(output),
                                        Ok(Err(error)) => {
                                            producer_cancelled.store(true, Ordering::Release);
                                            Err(error)
                                        }
                                        Err(payload) => {
                                            producer_cancelled.store(true, Ordering::Release);
                                            Err(io::Error::other(format!(
                                                "indexed range producer panicked: {}",
                                                panic_payload_message(payload.as_ref())
                                            )))
                                        }
                                    };
                                    let _ = range_result_tx.send((range_id, result));
                                }),
                            ));
                        }
                        drop(producer_result_tx);
                        let expected_results = producer_handles.len();
                        let mut received_results = 0usize;
                        let mut producer_failures = Vec::new();
                        let mut last_reported_objects = 0u64;
                        let mut last_progress_emitted_at = Instant::now();
                        while received_results < expected_results {
                            match producer_result_rx.recv_timeout(Duration::from_millis(250)) {
                                Ok((_range_id, Ok(output))) => {
                                    indexed_range_metrics.push(output);
                                    received_results += 1;
                                }
                                Ok((range_id, Err(error))) => {
                                    producer_failures.push((range_id, error));
                                    received_results += 1;
                                }
                                Err(RecvTimeoutError::Timeout) => {}
                                Err(RecvTimeoutError::Disconnected) => {
                                    indexed_cancelled.store(true, Ordering::Release);
                                    producer_failures.push((
                                        usize::MAX,
                                        io::Error::new(
                                            io::ErrorKind::BrokenPipe,
                                            format!(
                                                "indexed producer result channel closed after {received_results} of {expected_results} results"
                                            ),
                                        ),
                                    ));
                                    break;
                                }
                            }
                            drain_copy_file_events(
                                &event_rx,
                                &mut writer,
                                &mut copy_file_event_gate,
                            )?;
                            let completed_objects = indexed_producer_progress
                                .completed_objects
                                .load(Ordering::Acquire)
                                .min(indexed_range_coverage_objects);
                            if received_results < expected_results
                                && completed_objects < indexed_range_coverage_objects
                                && (completed_objects != last_reported_objects
                                    || last_progress_emitted_at.elapsed() >= Duration::from_secs(1))
                            {
                                emit_indexed_range_progress(
                                    path,
                                    indexed_range_coverage_objects,
                                    &indexed_producer_progress,
                                    in_network_started_at,
                                    false,
                                );
                                last_reported_objects = completed_objects;
                                last_progress_emitted_at = Instant::now();
                            }
                        }
                        for (range_id, handle) in producer_handles {
                            if let Err(payload) = handle.join() {
                                indexed_cancelled.store(true, Ordering::Release);
                                producer_failures.push((
                                    range_id,
                                    io::Error::other(format!(
                                        "indexed range producer join panicked: {}",
                                        panic_payload_message(payload.as_ref())
                                    )),
                                ));
                            }
                        }
                        drain_copy_file_events(&event_rx, &mut writer, &mut copy_file_event_gate)?;
                        producer_failures.sort_by_key(|(range_id, error)| {
                            (error.kind() == io::ErrorKind::Interrupted, *range_id)
                        });
                        producer_error =
                            producer_failures
                                .into_iter()
                                .next()
                                .map(|(range_id, error)| {
                                    if range_id == usize::MAX {
                                        error
                                    } else {
                                        io::Error::new(
                                            error.kind(),
                                            format!(
                                                "indexed range producer {range_id} failed: {error}"
                                            ),
                                        )
                                    }
                                });
                        indexed_range_metrics.sort_unstable_by_key(|metrics| metrics.range_id);
                        for metrics in &indexed_range_metrics {
                            raw_chunk_stats.merge_from(&metrics.raw_chunk_stats);
                            producer_blocked_micros =
                                producer_blocked_micros.saturating_add(metrics.blocked_micros);
                            *object_counts.entry("in_network".to_string()).or_insert(0) +=
                                metrics.range.object_count;
                            if let Some(semantic_progress) = semantic_progress.as_ref() {
                                semantic_progress.record_in_network_objects_completed(
                                    metrics.range.object_count,
                                );
                            }
                            *object_counts
                                .entry("negotiated_rates".to_string())
                                .or_insert(0) += metrics.rate_count;
                        }
                    } else {
                        let producer_result = (|| -> io::Result<()> {
                            let rate_reader: Box<dyn Read> = if let Some(reorder) =
                                plain_reorder.as_ref()
                            {
                                let mut provider_range_reader = PrefixReader::new(prefix, reader);
                                drain_reader_to_eof(&mut provider_range_reader)?;
                                let range_reader = open_plain_range_json_reader(
                                    path,
                                    reorder.in_network.offset,
                                    reorder.in_network.length,
                                    Arc::clone(&compressed_bytes_read),
                                )?;
                                Box::new(WrappedIndexedRangeReader::new(
                                    range_reader,
                                    reorder.in_network.length,
                                    br#"{"in_network":"#,
                                    b"}",
                                ))
                            } else {
                                let array_and_suffix = PrefixReader::new(prefix, reader);
                                Box::new(PrefixReader::new(
                                    br#"{"in_network":"#.to_vec(),
                                    array_and_suffix,
                                ))
                            };
                            if parse_in_workers {
                                let mut byte_reader = BufferedJsonByteReader::new(rate_reader);
                                byte_reader.expect_byte(b'{')?;
                                let mut name_bytes = Vec::with_capacity(16);
                                let mut decoded_name = String::new();
                                let name = byte_reader
                                    .read_string_name(&mut name_bytes, &mut decoded_name)?;
                                if name != "in_network" {
                                    return Err(io::Error::new(
                                        io::ErrorKind::InvalidData,
                                        "synthetic rate object must start with in_network",
                                    ));
                                }
                                byte_reader.expect_byte(b':')?;
                                byte_reader.expect_byte(b'[')?;
                                let mut first_item = true;
                                while next_array_value(&mut byte_reader, &mut first_item)? {
                                    let mut enqueue_io = InNetworkEnqueueIo {
                                        tx: &tx,
                                        event_rx: &event_rx,
                                        writer: &mut writer,
                                        copy_file_event_gate: &mut copy_file_event_gate,
                                        cancelled: Some(&indexed_cancelled),
                                        producer_blocked_micros: &mut producer_blocked_micros,
                                        raw_chunk_stats: &mut raw_chunk_stats,
                                    };
                                    let rate_count = enqueue_in_network_raw_byte_scan(
                                        &mut byte_reader,
                                        &mut enqueue_io,
                                        InNetworkEnqueueOptions {
                                            chunk_size: negotiated_rate_chunk_size,
                                            raw_chunk_byte_limit,
                                            parse_in_workers,
                                            object_ordinal: *object_counts
                                                .get("in_network")
                                                .unwrap_or(&0),
                                        },
                                    )?;
                                    drain_copy_file_events(
                                        &event_rx,
                                        &mut writer,
                                        &mut copy_file_event_gate,
                                    )?;
                                    *object_counts.entry("in_network".to_string()).or_insert(0) +=
                                        1;
                                    if let Some(semantic_progress) = semantic_progress.as_ref() {
                                        semantic_progress.record_in_network_object_completed();
                                    }
                                    *object_counts
                                        .entry("negotiated_rates".to_string())
                                        .or_insert(0) += rate_count;
                                    let bytes = compressed_bytes_read.load(Ordering::Relaxed);
                                    let objects: u64 = object_counts.values().sum();
                                    if progress_bytes_interval > 0 && bytes >= next_progress_bytes {
                                        emit_progress(
                                            path,
                                            total_bytes,
                                            &compressed_bytes_read,
                                            &object_counts,
                                            started_at,
                                            false,
                                        );
                                        while bytes >= next_progress_bytes {
                                            next_progress_bytes += progress_bytes_interval;
                                        }
                                    } else if progress_objects_interval > 0
                                        && objects >= next_progress_objects
                                    {
                                        emit_progress(
                                            path,
                                            total_bytes,
                                            &compressed_bytes_read,
                                            &object_counts,
                                            started_at,
                                            false,
                                        );
                                        while objects >= next_progress_objects {
                                            next_progress_objects += progress_objects_interval;
                                        }
                                    }
                                }
                                validate_compact_rate_object_suffix(
                                    byte_reader.into_unread_reader(),
                                )?;
                            } else {
                                let mut json_reader = JsonStreamReader::new(rate_reader);
                                json_reader.begin_object().map_err(to_io_error)?;
                                let name = json_reader.next_name_owned().map_err(to_io_error)?;
                                if name != "in_network" {
                                    return Err(io::Error::new(
                                        io::ErrorKind::InvalidData,
                                        "synthetic rate object must start with in_network",
                                    ));
                                }
                                json_reader.begin_array().map_err(to_io_error)?;
                                while json_reader.has_next().map_err(to_io_error)? {
                                    let mut enqueue_io = InNetworkEnqueueIo {
                                        tx: &tx,
                                        event_rx: &event_rx,
                                        writer: &mut writer,
                                        copy_file_event_gate: &mut copy_file_event_gate,
                                        cancelled: Some(&indexed_cancelled),
                                        producer_blocked_micros: &mut producer_blocked_micros,
                                        raw_chunk_stats: &mut raw_chunk_stats,
                                    };
                                    let rate_count = enqueue_in_network_struson(
                                        &mut json_reader,
                                        &mut enqueue_io,
                                        InNetworkEnqueueOptions {
                                            chunk_size: negotiated_rate_chunk_size,
                                            raw_chunk_byte_limit,
                                            parse_in_workers,
                                            object_ordinal: *object_counts
                                                .get("in_network")
                                                .unwrap_or(&0),
                                        },
                                    )?;
                                    drain_copy_file_events(
                                        &event_rx,
                                        &mut writer,
                                        &mut copy_file_event_gate,
                                    )?;
                                    *object_counts.entry("in_network".to_string()).or_insert(0) +=
                                        1;
                                    if let Some(semantic_progress) = semantic_progress.as_ref() {
                                        semantic_progress.record_in_network_object_completed();
                                    }
                                    *object_counts
                                        .entry("negotiated_rates".to_string())
                                        .or_insert(0) += rate_count;
                                    let bytes = compressed_bytes_read.load(Ordering::Relaxed);
                                    let objects: u64 = object_counts.values().sum();
                                    if progress_bytes_interval > 0 && bytes >= next_progress_bytes {
                                        emit_progress(
                                            path,
                                            total_bytes,
                                            &compressed_bytes_read,
                                            &object_counts,
                                            started_at,
                                            false,
                                        );
                                        while bytes >= next_progress_bytes {
                                            next_progress_bytes += progress_bytes_interval;
                                        }
                                    } else if progress_objects_interval > 0
                                        && objects >= next_progress_objects
                                    {
                                        emit_progress(
                                            path,
                                            total_bytes,
                                            &compressed_bytes_read,
                                            &object_counts,
                                            started_at,
                                            false,
                                        );
                                        while objects >= next_progress_objects {
                                            next_progress_objects += progress_objects_interval;
                                        }
                                    }
                                }
                                json_reader.end_array().map_err(to_io_error)?;
                                finish_compact_rate_object(json_reader, true, true)?;
                            }
                            Ok(())
                        })();
                        producer_error =
                            capture_producer_error(&indexed_cancelled, producer_result);
                    }
                    in_network_enqueue_seconds += in_network_started_at.elapsed().as_secs_f64();
                    in_network_compressed_bytes = if indexed_reorder_used {
                        indexed_range_metrics
                            .iter()
                            .map(|metrics| metrics.compressed_bytes)
                            .max()
                            .unwrap_or(0)
                    } else {
                        compressed_bytes_read
                            .load(Ordering::Relaxed)
                            .saturating_sub(in_network_compressed_started_at)
                    };

                    if let Some(diagnostic) = producer_error
                        .as_ref()
                        .and_then(primary_producer_failure_diagnostic)
                    {
                        eprintln!("{diagnostic}");
                    }
                    drop(tx);
                    drop(event_tx);
                    let worker_join_started_at = Instant::now();
                    drain_copy_file_events_until_workers_finish(
                        &event_rx,
                        &handles,
                        &mut writer,
                        &mut copy_file_event_gate,
                    )?;
                    let mut worker_error: Option<io::Error> = None;
                    let mut copy_file_events = Vec::new();
                    for (worker_id, handle) in handles {
                        match handle.join() {
                            Ok(Ok(mut output)) => {
                                copy_file_events.append(&mut output.events);
                                invalid_price_exclusions
                                    .append(&mut output.invalid_price_exclusions);
                                invalid_price_emptied_rates = invalid_price_emptied_rates
                                    .checked_add(output.invalid_price_emptied_rates)
                                    .ok_or_else(|| {
                                        io::Error::new(
                                            io::ErrorKind::InvalidData,
                                            "invalid price emptied-rate count overflow",
                                        )
                                    })?;
                                compact_worker_metrics.push(output.metrics);
                            }
                            Ok(Err(err)) => {
                                let message = err.to_string();
                                emit_worker_failure(&mut writer, worker_id, "error", &message)?;
                                if worker_error.is_none() {
                                    worker_error = Some(err);
                                }
                            }
                            Err(payload) => {
                                let message = panic_payload_message(payload.as_ref());
                                emit_worker_failure(&mut writer, worker_id, "panic", &message)?;
                                if worker_error.is_none() {
                                    worker_error = Some(io::Error::other(format!(
                                        "compact worker {worker_id} panicked: {message}"
                                    )));
                                }
                            }
                        }
                    }
                    worker_join_seconds += worker_join_started_at.elapsed().as_secs_f64();
                    compact_worker_metrics.sort_unstable_by_key(|metrics| metrics.worker_id);
                    if copy_paths.manifest_only {
                        dedupe.record_unmeasured_serving_rates(
                            compact_worker_metrics
                                .iter()
                                .map(|metrics| metrics.serving_run_rows)
                                .sum(),
                        );
                    }
                    drain_copy_file_events(&event_rx, &mut writer, &mut copy_file_event_gate)?;
                    for event in copy_file_events {
                        copy_file_event_gate.publish(&mut writer, event)?;
                    }
                    writer.flush()?;
                    if let Some(err) = compact_pipeline_error(worker_error, producer_error) {
                        return Err(err);
                    }
                    let invalid_price_exclusion_evidence =
                        match context.invalid_price_exclusion.as_deref() {
                            Some(policy) => policy.validate_observed(
                                invalid_price_exclusions,
                                invalid_price_emptied_rates,
                            )?,
                            None if invalid_price_exclusions.is_empty()
                                && invalid_price_emptied_rates == 0 =>
                            {
                                Value::Null
                            }
                            None => {
                                return Err(io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    "invalid price exclusions require an exact expectation",
                                ));
                            }
                        };
                    copy_file_event_gate.release(&mut writer)?;
                    if plain_reorder_used {
                        let completed_objects =
                            object_counts.get("in_network").copied().unwrap_or(0);
                        if completed_objects != plain_in_network_object_count {
                            return Err(io::Error::new(
                                io::ErrorKind::InvalidData,
                                format!(
                                    "plain reordered in-network scan completed {completed_objects} objects, expected {plain_in_network_object_count}"
                                ),
                            ));
                        }
                    }
                    emit_dedupe_summary(&dedupe, &object_counts);
                    emit_provider_group_tax_identity_sidecars(&mut writer, &copy_paths, &dedupe)?;
                    if let Some(sidecars) = manifest_sidecars.as_ref() {
                        let sidecar_finalize_started_at = Instant::now();
                        let sidecar_lock_started_at = Instant::now();
                        let mut sidecars = sidecars.lock().unwrap();
                        sidecar_finalize_lock_wait_seconds +=
                            sidecar_lock_started_at.elapsed().as_secs_f64();
                        emit_configured_manifest_sidecars(
                            &mut writer,
                            &copy_paths,
                            Some(&mut sidecars),
                            semantic_progress.as_ref().map(Arc::clone),
                        )?;
                        sidecar_merge_write_seconds +=
                            sidecar_finalize_started_at.elapsed().as_secs_f64();
                    }
                    emit_json_record(
                        &mut writer,
                        "dedupe_summary",
                        &dedupe_summary_payload(&dedupe, &object_counts),
                    )?;
                    let elapsed_seconds = started_at.elapsed().as_secs_f64();
                    let scan_compressed_bytes = compressed_bytes_read.load(Ordering::Relaxed);
                    let producer_blocked_seconds = seconds_from_micros(producer_blocked_micros);
                    let producer_nonblocked_seconds =
                        (in_network_enqueue_seconds - producer_blocked_seconds).max(0.0);
                    let producer_backpressure_pct = if in_network_enqueue_seconds > 0.0 {
                        producer_blocked_seconds * 100.0 / in_network_enqueue_seconds
                    } else {
                        0.0
                    };
                    let provider_parse_seconds: f64 = provider_worker_metrics
                        .iter()
                        .map(|metrics| seconds_from_micros(metrics.parse_micros))
                        .sum();
                    let provider_transform_seconds: f64 = provider_worker_metrics
                        .iter()
                        .map(|metrics| seconds_from_micros(metrics.transform_micros))
                        .sum();
                    let provider_write_seconds: f64 = provider_worker_metrics
                        .iter()
                        .map(|metrics| seconds_from_micros(metrics.write_micros))
                        .sum();
                    let worker_sidecar_lock_wait_seconds: f64 = compact_worker_metrics
                        .iter()
                        .map(|metrics| seconds_from_micros(metrics.sidecar_lock_wait_micros))
                        .sum();
                    emit_json_record(
                        &mut writer,
                        "scanner_summary",
                        &scanner_summary_with_v4_empty_npi_audit(
                            json!({
                                "invalid_price_exclusion": invalid_price_exclusion_evidence,
                                "provider_identifier_quarantine": provider_identifier_quarantine_payload(
                                    &provider_map,
                                    dedupe.provider_identifier_quarantine()?,
                                    &provider_group_conflicts,
                                    context.source_witness.raw_source_sha256(),
                                )?,
                                "worker_count": worker_count,
                                "work_queue": bounded_queue_size,
                                "event_queue": event_queue_size,
                                "event_queue_unbounded": false,
                                "split_negotiated_rates": negotiated_rate_chunk_size,
                                "raw_chunk_bytes": raw_chunk_byte_limit,
                                "raw_chunk_count": raw_chunk_stats.chunk_count,
                                "raw_chunk_total_bytes": raw_chunk_stats.total_bytes,
                                "raw_chunk_max_bytes": raw_chunk_stats.max_bytes,
                                "raw_chunk_max_rates": raw_chunk_stats.max_rates,
                                "raw_buffer_allocations": raw_chunk_stats.buffer_allocations,
                                "raw_buffer_reuses": raw_chunk_stats.buffer_reuses,
                                "work_queue_high_water": raw_chunk_stats.queue_high_water,
                                "work_queue_blocked_sends": raw_chunk_stats.queue_blocked_sends,
                                "peak_queued_bytes": raw_chunk_stats.queue_bytes.peak_bytes(),
                                "queued_bytes_at_finish": raw_chunk_stats.queue_bytes.current_bytes(),
                                "producer_byte_framing_seconds": seconds_from_micros(raw_chunk_stats.framing_micros),
                                "producer_byte_capture_seconds": seconds_from_micros(raw_chunk_stats.capture_micros),
                                "producer_byte_capture_bytes": raw_chunk_stats.total_bytes,
                                "producer_byte_capture_timing_granularity": "raw_chunk",
                                "provider_ref_raw_chunk_count": provider_ref_raw_chunk_stats.chunk_count,
                                "provider_ref_raw_chunk_total_bytes": provider_ref_raw_chunk_stats.total_bytes,
                                "provider_ref_raw_chunk_max_bytes": provider_ref_raw_chunk_stats.max_bytes,
                                "provider_ref_raw_chunk_max_items": provider_ref_raw_chunk_stats.max_rates,
                                "provider_ref_buffer_allocations": provider_ref_raw_chunk_stats.buffer_allocations,
                                "provider_ref_buffer_reuses": provider_ref_raw_chunk_stats.buffer_reuses,
                                "provider_ref_queue_high_water": provider_ref_raw_chunk_stats.queue_high_water,
                                "provider_ref_queue_blocked_sends": provider_ref_raw_chunk_stats.queue_blocked_sends,
                                "provider_ref_peak_queued_bytes": provider_ref_raw_chunk_stats.queue_bytes.peak_bytes(),
                                "provider_ref_queued_bytes_at_finish": provider_ref_raw_chunk_stats.queue_bytes.current_bytes(),
                                "provider_capture_bytes": provider_ref_raw_chunk_stats.total_bytes,
                                "provider_capture_seconds": provider_capture_seconds,
                                "provider_capture_compressed_bytes": provider_capture_compressed_bytes,
                                "provider_capture_compressed_mib_s": compressed_mib_per_second(provider_capture_compressed_bytes, provider_capture_seconds),
                                "provider_parse_seconds": provider_parse_seconds,
                                "provider_transform_seconds": provider_transform_seconds,
                                "provider_write_seconds": provider_write_seconds,
                                "provider_worker_join_seconds": provider_worker_join_seconds,
                                "provider_map_merge_seconds": provider_map_merge_seconds,
                                "provider_definition_output_seconds": provider_definition_output_seconds,
                                "provider_workers": provider_worker_metrics.iter().map(ProviderRefWorkerMetrics::payload).collect::<Vec<_>>(),
                                "parse_in_workers": parse_in_workers,
                                "producer_blocked_micros": producer_blocked_micros,
                                "producer_blocked_seconds": producer_blocked_seconds,
                                "producer_nonblocked_seconds": producer_nonblocked_seconds,
                                "producer_backpressure_pct": producer_backpressure_pct,
                                "producer_raw_mib_s": compressed_mib_per_second(raw_chunk_stats.total_bytes, in_network_enqueue_seconds),
                                "producer_nonblocked_raw_mib_s": compressed_mib_per_second(raw_chunk_stats.total_bytes, producer_nonblocked_seconds),
                                "producer_nonblocked_compressed_mib_s": compressed_mib_per_second(in_network_compressed_bytes, producer_nonblocked_seconds),
                                "provider_ref_producer_blocked_micros": provider_ref_producer_blocked_micros,
                                "provider_refs_seconds": provider_refs_seconds,
                                "in_network_enqueue_seconds": in_network_enqueue_seconds,
                                "in_network_compressed_bytes": in_network_compressed_bytes,
                                "in_network_compressed_mib_s": compressed_mib_per_second(in_network_compressed_bytes, in_network_enqueue_seconds),
                                "worker_join_seconds": worker_join_seconds,
                                "worker_sidecar_lock_wait_seconds": worker_sidecar_lock_wait_seconds,
                                "sidecar_finalize_lock_wait_seconds": sidecar_finalize_lock_wait_seconds,
                                "sidecar_merge_write_seconds": sidecar_merge_write_seconds,
                                "typed_rate_parses": compact_worker_metrics.iter().map(|metrics| metrics.typed_rate_parses).sum::<u64>(),
                                "streaming_rate_parse_fallbacks": compact_worker_metrics.iter().map(|metrics| metrics.streaming_rate_parse_fallbacks).sum::<u64>(),
                                "local_price_set_dedupe_hits": compact_worker_metrics.iter().map(|metrics| metrics.local_price_set_dedupe_hits).sum::<u64>(),
                                "local_price_atom_dedupe_hits": compact_worker_metrics.iter().map(|metrics| metrics.local_price_atom_dedupe_hits).sum::<u64>(),
                                "local_provider_set_dedupe_hits": compact_worker_metrics.iter().map(|metrics| metrics.local_provider_set_dedupe_hits).sum::<u64>(),
                                "local_price_set_dedupe_resets": compact_worker_metrics.iter().map(|metrics| metrics.local_price_set_dedupe_resets).sum::<u64>(),
                                "local_price_atom_dedupe_resets": compact_worker_metrics.iter().map(|metrics| metrics.local_price_atom_dedupe_resets).sum::<u64>(),
                                "local_provider_set_dedupe_resets": compact_worker_metrics.iter().map(|metrics| metrics.local_provider_set_dedupe_resets).sum::<u64>(),
                                "serving_run_files": compact_worker_metrics.iter().map(|metrics| metrics.serving_run_files).sum::<u64>(),
                                "serving_run_rows": compact_worker_metrics.iter().map(|metrics| metrics.serving_run_rows).sum::<u64>(),
                                "serving_run_bytes": compact_worker_metrics.iter().map(|metrics| metrics.serving_run_bytes).sum::<u64>(),
                                "serving_code_dictionary_files": compact_worker_metrics.iter().map(|metrics| metrics.serving_code_dictionary_files).sum::<u64>(),
                                "serving_code_dictionary_rows": compact_worker_metrics.iter().map(|metrics| metrics.serving_code_dictionary_rows).sum::<u64>(),
                                "serving_code_dictionary_bytes": compact_worker_metrics.iter().map(|metrics| metrics.serving_code_dictionary_bytes).sum::<u64>(),
                                "factor_mode": factor_mode,
                                "provider_graph_v4_factor_mode": factor_mode,
                                "provider_graph_v4_reference_only_rates": compact_worker_metrics.iter().map(|metrics| metrics.provider_graph_v4_reference_only_rates).sum::<u64>(),
                                "provider_graph_v4_inline_only_rates": compact_worker_metrics.iter().map(|metrics| metrics.provider_graph_v4_inline_only_rates).sum::<u64>(),
                                "provider_graph_v4_mixed_rates": compact_worker_metrics.iter().map(|metrics| metrics.provider_graph_v4_mixed_rates).sum::<u64>(),
                                "provider_graph_v4_factor_cache_hits": compact_worker_metrics.iter().map(|metrics| metrics.provider_graph_v4_factor_cache_hits).sum::<u64>(),
                                "provider_graph_v4_factor_cache_misses": compact_worker_metrics.iter().map(|metrics| metrics.provider_graph_v4_factor_cache_misses).sum::<u64>(),
                                "provider_graph_v4_factor_cache_resets": compact_worker_metrics.iter().map(|metrics| metrics.provider_graph_v4_factor_cache_resets).sum::<u64>(),
                                "provider_graph_v4_npi_union_attempts": compact_worker_metrics.iter().map(|metrics| metrics.provider_graph_v4_npi_union_attempts).sum::<u64>(),
                                "provider_graph_v4_flat_group_union_attempts": compact_worker_metrics.iter().map(|metrics| metrics.provider_graph_v4_flat_group_union_attempts).sum::<u64>(),
                                "provider_graph_v4_factor_cache_entries": provider_graph_v4_factor_cache.snapshot().0,
                                "provider_graph_v4_factor_cache_estimated_bytes": provider_graph_v4_factor_cache.snapshot().1,
                                "provider_graph_v4_factor_cache_max_bytes": provider_graph_v4_factor_cache.snapshot().2,
                                "provider_graph_v4_inline_transform_cache_hits": provider_graph_v4_factor_cache.inline_transforms.snapshot().hits,
                                "provider_graph_v4_inline_transform_cache_misses": provider_graph_v4_factor_cache.inline_transforms.snapshot().misses,
                                "provider_graph_v4_inline_transform_cache_transforms": provider_graph_v4_factor_cache.inline_transforms.snapshot().transforms,
                                "provider_graph_v4_inline_transform_cache_evictions": provider_graph_v4_factor_cache.inline_transforms.snapshot().evictions,
                                "provider_graph_v4_inline_transform_cache_evicted_entries": provider_graph_v4_factor_cache.inline_transforms.snapshot().evicted_entries,
                                "provider_graph_v4_inline_transform_cache_bypasses": provider_graph_v4_factor_cache.inline_transforms.snapshot().bypasses,
                                "provider_graph_v4_inline_transform_cache_entries": provider_graph_v4_factor_cache.inline_transforms.snapshot().entries,
                                "provider_graph_v4_inline_transform_cache_estimated_bytes": provider_graph_v4_factor_cache.inline_transforms.snapshot().estimated_bytes,
                                "provider_graph_v4_inline_transform_cache_peak_estimated_bytes": provider_graph_v4_factor_cache.inline_transforms.snapshot().peak_estimated_bytes,
                                "provider_graph_v4_inline_transform_cache_max_bytes": provider_graph_v4_factor_cache.inline_transforms.snapshot().max_estimated_bytes,
                                "workers": compact_worker_metrics.iter().map(CompactWorkerMetrics::payload).collect::<Vec<_>>(),
                                "top_level_byte_scan": true,
                                "top_level_byte_scan_selected": true,
                                "decompression": if rapidgzip_config.enabled { "rapidgzip" } else { "flate2" },
                                "rapidgzip_threads": if rapidgzip_config.enabled {
                                    Some(rapidgzip_config.decoder_threads)
                                } else {
                                    None
                                },
                                "provider_reference_order": provider_reference_order_label,
                                "rapidgzip_index_bytes": indexed_reorder_bytes,
                                "rapidgzip_index_threads": indexed_reorder_decoder_threads,
                            "indexed_range_producers_requested": indexed_range_producers_requested,
                            "indexed_range_producers_selected": indexed_range_producers_selected,
                                "indexed_range_decoder_threads_selected": indexed_range_decoder_threads_selected,
                                "indexed_range_count": indexed_range_count,
                                "indexed_ranges": indexed_range_metrics.iter().map(IndexedRangeProducerOutput::payload).collect::<Vec<_>>(),
                                "indexed_range_coverage_bytes": indexed_range_coverage_bytes,
                                "indexed_range_coverage_object_count": indexed_range_coverage_objects,
                                "plain_range_reorder": plain_reorder_used,
                                "plain_provider_range_offset": plain_provider_range_offset,
                                "plain_provider_range_bytes": plain_provider_range_bytes,
                                "plain_in_network_range_offset": plain_in_network_range_offset,
                                "plain_in_network_range_bytes": plain_in_network_range_bytes,
                                "plain_in_network_object_count": plain_in_network_object_count,
                                "indexed_range_completed_object_count": indexed_producer_progress.completed_objects.load(Ordering::Acquire),
                                "indexed_range_completed_rate_count": indexed_producer_progress.completed_rates.load(Ordering::Relaxed),
                                "indexed_range_completed_raw_bytes": indexed_producer_progress.completed_raw_bytes.load(Ordering::Relaxed),
                                "indexed_range_peer_cancellation_can_interrupt_external_read": if indexed_reorder_used {
                                    Some(false)
                                } else {
                                    None
                                },
                                "indexed_range_cancellation_limitation": if indexed_reorder_used {
                                    Some("peer cancellation cannot interrupt a child blocked inside external rapidgzip read")
                                } else {
                                    None
                                },
                                "full_decompression_passes": if indexed_reorder_used { 2 } else { 1 },
                                "order_probe_partial_pass": provider_reference_order_label != "missing",
                                "order_detection_seconds": preflight_metrics.order_detection_seconds,
                                "order_detection_compressed_bytes": preflight_metrics.order_detection_compressed_bytes,
                                "order_detection_compressed_mib_s": preflight_metrics.compressed_mib_s(),
                                "raw_rate_byte_capture": parse_in_workers,
                                "scan_compressed_bytes": scan_compressed_bytes,
                                "scan_compressed_mib_s": compressed_mib_per_second(scan_compressed_bytes, elapsed_seconds),
                                "elapsed_seconds": elapsed_seconds,
                            }),
                            factor_mode,
                            dedupe.empty_npi_tin_only_normalization_count(),
                        ),
                    )?;
                    writer.flush()?;
                    if indexed_reorder_used {
                        emit_indexed_range_progress(
                            path,
                            indexed_range_coverage_objects,
                            &indexed_producer_progress,
                            in_network_started_at,
                            true,
                        );
                    } else if plain_reorder_used {
                        emit_plain_reorder_progress(
                            path,
                            plain_in_network_object_count,
                            object_counts.get("in_network").copied().unwrap_or(0),
                            object_counts.get("negotiated_rates").copied().unwrap_or(0),
                            in_network_started_at,
                            true,
                        );
                    } else {
                        emit_progress(
                            path,
                            total_bytes,
                            &compressed_bytes_read,
                            &object_counts,
                            started_at,
                            true,
                        );
                    }
                    return Ok(());
                }
            }

            if in_provider_refs && capture_depth == 0 && byte == b'{' && depth == active_array_depth
            {
                capture_start = raw_refs.byte_len();
                raw_refs.bytes.push(b'{');
                capture_depth = 1;
                depth += 1;
                continue;
            }

            match byte {
                b'{' | b'[' => {
                    if capture_depth > 0 {
                        capture_depth += 1;
                    }
                    depth += 1;
                }
                b'}' | b']' => {
                    if capture_depth > 0 {
                        capture_depth -= 1;
                        if capture_depth == 0 {
                            raw_refs.push_current_value_span_at(
                                capture_start,
                                SourceWitnessCoordinate::new(
                                    *object_counts.get("provider_references").unwrap_or(&0),
                                    0,
                                ),
                            );
                            *object_counts
                                .entry("provider_references".to_string())
                                .or_insert(0) += 1;
                            if raw_refs.len() >= provider_ref_chunk_items
                                || raw_refs.byte_len() >= provider_ref_raw_chunk_byte_limit
                            {
                                provider_ref_raw_chunk_stats
                                    .record_capture_batch(provider_capture_started_at.take());
                                let batch = provider_ref_raw_chunk_stats.take_filled_chunk(
                                    &mut raw_refs,
                                    provider_ref_chunk_items,
                                    provider_ref_raw_chunk_byte_limit,
                                );
                                provider_ref_raw_chunk_stats.record(batch.len(), batch.byte_len());
                                send_provider_ref_batch(
                                    &provider_tx,
                                    &event_rx,
                                    &mut writer,
                                    &mut provider_ref_producer_blocked_micros,
                                    &mut provider_ref_raw_chunk_stats,
                                    &mut copy_file_event_gate,
                                    batch,
                                )?;
                                drain_copy_file_events(
                                    &event_rx,
                                    &mut writer,
                                    &mut copy_file_event_gate,
                                )?;
                                provider_capture_started_at = Some(Instant::now());
                            }
                            if !indexed_reorder_used {
                                let bytes = compressed_bytes_read.load(Ordering::Relaxed);
                                let objects: u64 = object_counts.values().sum();
                                if progress_bytes_interval > 0 && bytes >= next_progress_bytes {
                                    emit_progress(
                                        path,
                                        total_bytes,
                                        &compressed_bytes_read,
                                        &object_counts,
                                        started_at,
                                        false,
                                    );
                                    while bytes >= next_progress_bytes {
                                        next_progress_bytes += progress_bytes_interval;
                                    }
                                } else if progress_objects_interval > 0
                                    && objects >= next_progress_objects
                                {
                                    emit_progress(
                                        path,
                                        total_bytes,
                                        &compressed_bytes_read,
                                        &object_counts,
                                        started_at,
                                        false,
                                    );
                                    while objects >= next_progress_objects {
                                        next_progress_objects += progress_objects_interval;
                                    }
                                }
                            }
                            depth = depth.saturating_sub(1);
                            continue;
                        }
                    }
                    if in_provider_refs && byte == b']' && depth == active_array_depth {
                        in_provider_refs = false;
                        active_array_depth = 0;
                    }
                    depth = depth.saturating_sub(1);
                }
                _ => {}
            }
        }
    }

    drop(provider_tx);
    let _ = join_provider_ref_workers(&mut writer, provider_handles)?;
    if context.invalid_price_exclusion.is_some() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "observed invalid price exclusions do not match the exact expectation",
        ));
    }
    writer.flush()?;
    drop(semantic_progress_reporter.take());
    emit_progress(
        path,
        total_bytes,
        &compressed_bytes_read,
        &object_counts,
        started_at,
        true,
    );
    Ok(())
}

enum CompactProviderReferenceOrder {
    None,
    BeforeInNetwork,
    AfterInNetwork,
    AfterInNetworkIndexed(CompactIndexedReorder),
    AfterInNetworkPlain(CompactPlainReorder),
}

impl CompactProviderReferenceOrder {
    fn label(&self) -> &'static str {
        match self {
            Self::None => "missing",
            Self::BeforeInNetwork => "before_in_network",
            Self::AfterInNetwork
            | Self::AfterInNetworkIndexed(_)
            | Self::AfterInNetworkPlain(_) => "after_in_network",
        }
    }
}

#[derive(Clone, Copy)]
struct CompactPreflightMetrics {
    order_detection_seconds: f64,
    order_detection_compressed_bytes: u64,
}

impl CompactPreflightMetrics {
    fn compressed_mib_s(&self) -> f64 {
        compressed_mib_per_second(
            self.order_detection_compressed_bytes,
            self.order_detection_seconds,
        )
    }
}

struct CompactProviderReferencePreflight {
    order: CompactProviderReferenceOrder,
    metrics: CompactPreflightMetrics,
}

fn finish_provider_reference_preflight(
    order: CompactProviderReferenceOrder,
    started_at: Instant,
    compressed_bytes_read: &AtomicU64,
) -> CompactProviderReferencePreflight {
    CompactProviderReferencePreflight {
        order,
        metrics: CompactPreflightMetrics {
            order_detection_seconds: started_at.elapsed().as_secs_f64(),
            order_detection_compressed_bytes: compressed_bytes_read.load(Ordering::Relaxed),
        },
    }
}

fn set_top_level_array_range(
    key: CompactTopLevelArrayKey,
    range: TopLevelArrayRange,
    provider_references: &mut Option<TopLevelArrayRange>,
    in_network: &mut Option<TopLevelArrayRange>,
) -> io::Result<()> {
    let destination = match key {
        CompactTopLevelArrayKey::ProviderReferences => provider_references,
        CompactTopLevelArrayKey::InNetwork => in_network,
    };
    if destination.replace(range).is_some() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "duplicate PTG top-level array",
        ));
    }
    Ok(())
}

fn indexed_range_producers_requested() -> io::Result<usize> {
    let name = "HLTHPRT_PTG2_RUST_INDEXED_RANGE_PRODUCERS";
    let Some(raw) = env::var_os(name) else {
        return Ok(DEFAULT_INDEXED_RANGE_PRODUCERS);
    };
    let value = raw.to_string_lossy().trim().parse::<usize>().map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{name} must be an integer from 1 through {MAX_INDEXED_RANGE_PRODUCERS}"),
        )
    })?;
    if !(1..=MAX_INDEXED_RANGE_PRODUCERS).contains(&value) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{name} must be from 1 through {MAX_INDEXED_RANGE_PRODUCERS}, got {value}"),
        ));
    }
    Ok(value)
}

fn retain_coalesced_indexed_range(
    ranges: &mut Vec<IndexedInNetworkRange>,
    span: TopLevelArrayRange,
    target_count: usize,
) {
    ranges.push(IndexedInNetworkRange {
        offset: span.offset,
        length: span.length,
        object_count: 1,
    });
    while ranges.len() > target_count {
        let merge_at = (0..ranges.len() - 1)
            .min_by_key(|index| {
                ranges[index + 1]
                    .end()
                    .saturating_sub(ranges[*index].offset)
            })
            .expect("more than one indexed range has an adjacent pair");
        let right = ranges.remove(merge_at + 1);
        let left = &mut ranges[merge_at];
        left.length = right.end().saturating_sub(left.offset);
        left.object_count = left.object_count.saturating_add(right.object_count);
    }
}

fn validate_indexed_in_network_ranges(
    ranges: &[IndexedInNetworkRange],
    in_network: TopLevelArrayRange,
    expected_object_count: u64,
) -> io::Result<()> {
    if ranges.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "indexed in-network object coverage is empty",
        ));
    }
    let array_end = in_network.offset.saturating_add(in_network.length);
    let mut previous_end = in_network.offset.saturating_add(1);
    let mut object_count = 0u64;
    for range in ranges {
        if range.length == 0 || range.object_count == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "indexed in-network range must have positive length and object count",
            ));
        }
        if range.offset < previous_end || range.end() >= array_end {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "indexed in-network ranges are unsorted, overlapping, or cross array brackets",
            ));
        }
        previous_end = range.end();
        object_count = object_count.saturating_add(range.object_count);
    }
    if object_count != expected_object_count {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "indexed in-network ranges cover {object_count} objects, expected {expected_object_count}"
            ),
        ));
    }
    Ok(())
}

#[derive(Debug)]
struct CompactTopLevelArrayScan {
    provider_references: TopLevelArrayRange,
    in_network: TopLevelArrayRange,
    in_network_ranges: Vec<IndexedInNetworkRange>,
    in_network_object_count: u64,
}

struct CompactTopLevelArrayIndexer {
    range_producers_selected: usize,
    stream_offset: u64,
    depth: usize,
    in_string: bool,
    escape: bool,
    top_level_key_buffer: Vec<u8>,
    capturing_top_level_key: bool,
    candidate_key: Option<CompactTopLevelArrayKey>,
    pending_key: Option<CompactTopLevelArrayKey>,
    active_array: Option<(CompactTopLevelArrayKey, usize, u64)>,
    provider_references: Option<TopLevelArrayRange>,
    in_network: Option<TopLevelArrayRange>,
    in_network_ranges: Vec<IndexedInNetworkRange>,
    in_network_object_start: Option<u64>,
    in_network_object_count: u64,
    in_network_after_value: bool,
}

impl CompactTopLevelArrayIndexer {
    fn new(range_producers_selected: usize) -> io::Result<Self> {
        if range_producers_selected == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "top-level range scan requires at least one selected producer",
            ));
        }
        Ok(Self {
            range_producers_selected,
            stream_offset: 0,
            depth: 0,
            in_string: false,
            escape: false,
            top_level_key_buffer: Vec::with_capacity(32),
            capturing_top_level_key: false,
            candidate_key: None,
            pending_key: None,
            active_array: None,
            provider_references: None,
            in_network: None,
            in_network_ranges: Vec::with_capacity(range_producers_selected),
            in_network_object_start: None,
            in_network_object_count: 0,
            in_network_after_value: false,
        })
    }

    fn ingest(&mut self, bytes: &[u8]) -> io::Result<()> {
        for (idx, &byte) in bytes.iter().enumerate() {
            let absolute_offset = self.stream_offset.saturating_add(idx as u64);
            if self.in_string {
                if self.escape {
                    if self.capturing_top_level_key {
                        self.top_level_key_buffer.push(byte);
                    }
                    self.escape = false;
                } else if byte == b'\\' {
                    if self.capturing_top_level_key {
                        self.top_level_key_buffer.push(byte);
                    }
                    self.escape = true;
                } else if byte == b'"' {
                    self.in_string = false;
                    if self.capturing_top_level_key {
                        self.candidate_key = match self.top_level_key_buffer.as_slice() {
                            b"provider_references" => {
                                Some(CompactTopLevelArrayKey::ProviderReferences)
                            }
                            b"in_network" => Some(CompactTopLevelArrayKey::InNetwork),
                            _ => None,
                        };
                        self.capturing_top_level_key = false;
                    }
                } else if self.capturing_top_level_key {
                    self.top_level_key_buffer.push(byte);
                }
                continue;
            }

            if byte == b'"' {
                self.in_string = true;
                self.escape = false;
                if self.depth == 1 && self.active_array.is_none() {
                    self.top_level_key_buffer.clear();
                    self.capturing_top_level_key = true;
                } else {
                    self.capturing_top_level_key = false;
                }
                continue;
            }

            if let Some(candidate) = self.candidate_key.take() {
                if byte.is_ascii_whitespace() {
                    self.candidate_key = Some(candidate);
                    continue;
                }
                if byte == b':' {
                    self.pending_key = Some(candidate);
                    continue;
                }
            }
            if let Some(pending) = self.pending_key.take() {
                if byte.is_ascii_whitespace() {
                    self.pending_key = Some(pending);
                    continue;
                }
                if byte == b'[' && self.depth == 1 {
                    self.depth += 1;
                    self.active_array = Some((pending, self.depth, absolute_offset));
                    if matches!(pending, CompactTopLevelArrayKey::InNetwork) {
                        self.in_network_after_value = false;
                    }
                    continue;
                }
            }

            if let Some((CompactTopLevelArrayKey::InNetwork, array_depth, array_offset)) =
                self.active_array
            {
                if let Some(object_offset) = self.in_network_object_start {
                    if byte == b'}' && self.depth == array_depth.saturating_add(1) {
                        retain_coalesced_indexed_range(
                            &mut self.in_network_ranges,
                            TopLevelArrayRange {
                                offset: object_offset,
                                length: absolute_offset
                                    .saturating_sub(object_offset)
                                    .saturating_add(1),
                            },
                            self.range_producers_selected,
                        );
                        self.in_network_object_start = None;
                        self.in_network_object_count =
                            self.in_network_object_count.saturating_add(1);
                        self.in_network_after_value = true;
                        self.depth = self.depth.saturating_sub(1);
                        continue;
                    }
                } else if self.depth == array_depth {
                    if byte.is_ascii_whitespace() {
                        continue;
                    }
                    match byte {
                        b'{' if !self.in_network_after_value => {
                            self.in_network_object_start = Some(absolute_offset);
                            self.depth += 1;
                            continue;
                        }
                        b',' if self.in_network_after_value => {
                            self.in_network_after_value = false;
                            continue;
                        }
                        b']' if self.in_network_after_value
                            || self.in_network_object_count == 0 =>
                        {
                            set_top_level_array_range(
                                CompactTopLevelArrayKey::InNetwork,
                                TopLevelArrayRange {
                                    offset: array_offset,
                                    length: absolute_offset
                                        .saturating_sub(array_offset)
                                        .saturating_add(1),
                                },
                                &mut self.provider_references,
                                &mut self.in_network,
                            )?;
                            self.active_array = None;
                            self.depth = self.depth.saturating_sub(1);
                            continue;
                        }
                        _ => {
                            return Err(io::Error::new(
                                io::ErrorKind::InvalidData,
                                "in-network array contains a non-object child or invalid separator",
                            ));
                        }
                    }
                }
            }

            match byte {
                b'{' | b'[' => self.depth += 1,
                b']' => {
                    if let Some((key, array_depth, array_offset)) = self.active_array {
                        if self.depth == array_depth {
                            set_top_level_array_range(
                                key,
                                TopLevelArrayRange {
                                    offset: array_offset,
                                    length: absolute_offset
                                        .saturating_sub(array_offset)
                                        .saturating_add(1),
                                },
                                &mut self.provider_references,
                                &mut self.in_network,
                            )?;
                            self.active_array = None;
                        }
                    }
                    self.depth = self.depth.saturating_sub(1);
                }
                b'}' => self.depth = self.depth.saturating_sub(1),
                _ => {}
            }
        }
        self.stream_offset = self.stream_offset.saturating_add(bytes.len() as u64);
        Ok(())
    }

    fn finish(&mut self) -> io::Result<Option<CompactTopLevelArrayScan>> {
        if self.in_string
            || self.active_array.is_some()
            || self.in_network_object_start.is_some()
            || self.depth != 0
        {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "incomplete JSON while indexing PTG top-level arrays",
            ));
        }
        let (Some(provider_references), Some(in_network)) =
            (self.provider_references.take(), self.in_network.take())
        else {
            return Ok(None);
        };
        if self.in_network_object_count == 0 {
            return Ok(None);
        }
        validate_indexed_in_network_ranges(
            &self.in_network_ranges,
            in_network,
            self.in_network_object_count,
        )?;
        Ok(Some(CompactTopLevelArrayScan {
            provider_references,
            in_network,
            in_network_ranges: std::mem::take(&mut self.in_network_ranges),
            in_network_object_count: self.in_network_object_count,
        }))
    }
}

struct CompactTopLevelArrayIndexingReader {
    inner: Box<dyn Read>,
    indexer: Arc<Mutex<CompactTopLevelArrayIndexer>>,
}

impl Read for CompactTopLevelArrayIndexingReader {
    fn read(&mut self, buffer: &mut [u8]) -> io::Result<usize> {
        let read = self.inner.read(buffer)?;
        if read > 0 {
            self.indexer
                .lock()
                .map_err(|_| io::Error::other("top-level range indexer mutex is poisoned"))?
                .ingest(&buffer[..read])?;
        }
        Ok(read)
    }
}

fn scan_compact_top_level_array_ranges(
    reader: Box<dyn Read>,
    range_producers_selected: usize,
) -> io::Result<Option<CompactTopLevelArrayScan>> {
    let indexer = Arc::new(Mutex::new(CompactTopLevelArrayIndexer::new(
        range_producers_selected,
    )?));
    let indexing_reader = CompactTopLevelArrayIndexingReader {
        inner: reader,
        indexer: Arc::clone(&indexer),
    };
    // The indexer sees original bytes (including a BOM) while the strict reader strips the BOM
    // for the parser. This preserves seek offsets and validates every JSON token in one pass.
    let mut json_reader = JsonStreamReader::new(strict_utf8_reader(indexing_reader));
    json_reader.skip_value().map_err(to_io_error)?;
    json_reader
        .consume_trailing_whitespace()
        .map_err(to_io_error)?;
    let result = indexer
        .lock()
        .map_err(|_| io::Error::other("top-level range indexer mutex is poisoned"))?
        .finish();
    result
}

fn build_indexed_top_level_reorder(
    path: &Path,
    rapidgzip_config: &RapidgzipConfig,
    compressed_bytes_read: Arc<AtomicU64>,
    range_producers_requested: usize,
    range_producers_selected: usize,
) -> io::Result<Option<CompactIndexedReorder>> {
    let index = TemporaryRapidgzipIndex::new()?;
    let reader = open_full_scan_reader_exporting_index(
        path,
        compressed_bytes_read,
        rapidgzip_config,
        &index.path,
    )?;
    let reader = strict_utf8_reader_preserving_bom(reader);
    let Some(scan) = scan_compact_top_level_array_ranges(reader, range_producers_selected)? else {
        return Ok(None);
    };
    if index.byte_len() == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "rapidgzip produced an empty seek index",
        ));
    }
    index.harden_file_permissions()?;
    Ok(Some(CompactIndexedReorder {
        index,
        provider_references: scan.provider_references,
        in_network_ranges: scan.in_network_ranges,
        indexed_range_producers_requested: range_producers_requested,
        in_network_object_count: scan.in_network_object_count,
        decoder_threads: rapidgzip_config.decoder_threads,
    }))
}

fn build_plain_top_level_reorder(
    path: &Path,
    rapidgzip_config: &RapidgzipConfig,
    bytes_read: Arc<AtomicU64>,
) -> io::Result<Option<CompactPlainReorder>> {
    let reader = open_full_scan_reader(path, bytes_read, rapidgzip_config)?;
    let reader = strict_utf8_reader_preserving_bom(reader);
    let Some(scan) = scan_compact_top_level_array_ranges(reader, 1)? else {
        return Ok(None);
    };
    Ok(Some(CompactPlainReorder {
        provider_references: scan.provider_references,
        in_network: scan.in_network,
        in_network_object_count: scan.in_network_object_count,
    }))
}

fn compact_provider_reference_order(
    path: &Path,
    use_indexed_reorder: bool,
    use_plain_reorder: bool,
    rapidgzip_config: &RapidgzipConfig,
    indexed_range_producers_requested: usize,
    indexed_range_producers_selected: usize,
) -> io::Result<CompactProviderReferencePreflight> {
    let started_at = Instant::now();
    let compressed_bytes_read = Arc::new(AtomicU64::new(0));
    let reader = open_json_reader(path, Arc::clone(&compressed_bytes_read))?;
    let mut json_reader = JsonStreamReader::new(reader);
    let mut saw_in_network = false;
    json_reader.begin_object().map_err(to_io_error)?;
    while json_reader.has_next().map_err(to_io_error)? {
        let name = json_reader.next_name_owned().map_err(to_io_error)?;
        match name.as_str() {
            "provider_references" if !saw_in_network => {
                return Ok(finish_provider_reference_preflight(
                    CompactProviderReferenceOrder::BeforeInNetwork,
                    started_at,
                    &compressed_bytes_read,
                ));
            }
            "provider_references" => {
                return Ok(finish_provider_reference_preflight(
                    CompactProviderReferenceOrder::AfterInNetwork,
                    started_at,
                    &compressed_bytes_read,
                ));
            }
            "in_network" => {
                saw_in_network = true;
                if use_indexed_reorder {
                    drop(json_reader);
                    let indexed_bytes_read = Arc::new(AtomicU64::new(0));
                    if let Some(indexed_reorder) = build_indexed_top_level_reorder(
                        path,
                        rapidgzip_config,
                        Arc::clone(&indexed_bytes_read),
                        indexed_range_producers_requested,
                        indexed_range_producers_selected,
                    )? {
                        return Ok(finish_provider_reference_preflight(
                            CompactProviderReferenceOrder::AfterInNetworkIndexed(indexed_reorder),
                            started_at,
                            &indexed_bytes_read,
                        ));
                    }
                    return compact_provider_reference_order(
                        path,
                        false,
                        false,
                        rapidgzip_config,
                        indexed_range_producers_requested,
                        indexed_range_producers_selected,
                    );
                }
                if use_plain_reorder {
                    drop(json_reader);
                    let plain_bytes_read = Arc::new(AtomicU64::new(0));
                    if let Some(plain_reorder) = build_plain_top_level_reorder(
                        path,
                        rapidgzip_config,
                        Arc::clone(&plain_bytes_read),
                    )? {
                        return Ok(finish_provider_reference_preflight(
                            CompactProviderReferenceOrder::AfterInNetworkPlain(plain_reorder),
                            started_at,
                            &plain_bytes_read,
                        ));
                    }
                    return compact_provider_reference_order(
                        path,
                        false,
                        false,
                        rapidgzip_config,
                        indexed_range_producers_requested,
                        indexed_range_producers_selected,
                    );
                }
                json_reader.skip_value().map_err(to_io_error)?;
            }
            _ => json_reader.skip_value().map_err(to_io_error)?,
        }
    }
    json_reader.end_object().map_err(to_io_error)?;
    json_reader
        .consume_trailing_whitespace()
        .map_err(to_io_error)?;
    Ok(finish_provider_reference_preflight(
        CompactProviderReferenceOrder::None,
        started_at,
        &compressed_bytes_read,
    ))
}

struct ServingRunScanGuard {
    directory: Option<PathBuf>,
    baseline_paths: HashSet<PathBuf>,
    committed: bool,
}

impl ServingRunScanGuard {
    fn from_config(copy_paths: &CopyPathConfig) -> Self {
        let directory = copy_paths
            .v3_serving_run_directory
            .as_ref()
            .map(PathBuf::from);
        let baseline_paths = directory
            .as_deref()
            .and_then(|directory| std::fs::read_dir(directory).ok())
            .into_iter()
            .flatten()
            .filter_map(Result::ok)
            .map(|entry| entry.path())
            .collect();
        Self {
            directory,
            baseline_paths,
            committed: false,
        }
    }

    fn commit(&mut self) {
        self.committed = true;
    }
}

impl Drop for ServingRunScanGuard {
    fn drop(&mut self) {
        if self.committed {
            return;
        }
        let Some(directory) = self.directory.as_deref() else {
            return;
        };
        let Ok(entries) = std::fs::read_dir(directory) else {
            return;
        };
        for entry in entries.filter_map(Result::ok) {
            let path = entry.path();
            let file_name = entry.file_name();
            let file_name = file_name.to_string_lossy();
            if self.baseline_paths.contains(&path)
                || !(file_name.starts_with(".ptg2-v3-serving-")
                    || file_name.starts_with("ptg2-v3-serving-")
                    || file_name.starts_with("ptg2-v3-source-witness-"))
            {
                continue;
            }
            let _ = std::fs::remove_file(path);
        }
    }
}

fn scan_compact_struson(path: &Path) -> io::Result<()> {
    let copy_paths = CopyPathConfig::from_env()?;
    let mut serving_run_guard = ServingRunScanGuard::from_config(&copy_paths);
    let source_witness_directory =
        copy_paths.v3_serving_run_directory.clone().ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "strict V3 scan is missing its source-witness output directory",
            )
        })?;
    let raw_source_sha256 = env::var(V3_RAW_SOURCE_SHA256_ENV).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("strict V3 scan requires {V3_RAW_SOURCE_SHA256_ENV}"),
        )
    })?;
    let invalid_price_exclusion =
        InvalidPriceExclusionPolicy::from_env(&raw_source_sha256)?.map(Arc::new);
    let source_witness = Arc::new(SourceWitnessCollector::new(&raw_source_sha256)?);
    let result = scan_compact_struson_inner(
        path,
        copy_paths,
        Arc::clone(&source_witness),
        invalid_price_exclusion,
    )
    .and_then(|()| {
        let summary = source_witness.write_bundle(Path::new(&source_witness_directory))?;
        let stdout = io::stdout();
        let mut writer = BufWriter::new(stdout.lock());
        emit_json_record(&mut writer, "source_audit_witness_file", &summary)?;
        writer.flush()
    });
    if result.is_ok() {
        serving_run_guard.commit();
    }
    result
}

fn scan_compact_struson_inner(
    path: &Path,
    copy_paths: CopyPathConfig,
    source_witness: Arc<SourceWitnessCollector>,
    invalid_price_exclusion: Option<Arc<InvalidPriceExclusionPolicy>>,
) -> io::Result<()> {
    configured_v4_factor_mode(&copy_paths)?;
    let snapshot_id = env::var("HLTHPRT_PTG2_COMPACT_SNAPSHOT_ID").unwrap_or_default();
    let plan_id = env::var("HLTHPRT_PTG2_COMPACT_PLAN_ID").unwrap_or_default();
    let plan_month_id = env::var("HLTHPRT_PTG2_COMPACT_PLAN_MONTH_ID").unwrap_or_default();
    let source_trace_set_hash =
        env::var("HLTHPRT_PTG2_COMPACT_SOURCE_TRACE_SET_HASH").unwrap_or_default();
    let confidence_code = env::var("HLTHPRT_PTG2_COMPACT_CONFIDENCE_CODE")
        .unwrap_or_else(|_| "tic_rate_npi_tin".to_string());
    let compact_copy_rotate_bytes = progress_interval(
        "HLTHPRT_PTG2_COMPACT_SERVING_COPY_ROTATE_BYTES",
        DEFAULT_COMPACT_COPY_ROTATE_BYTES,
    );
    let rust_worker_count =
        env_usize("HLTHPRT_PTG2_RUST_WORKERS", DEFAULT_COMPACT_RUST_WORKERS).max(1);
    let rust_queue_size = env_usize(
        "HLTHPRT_PTG2_RUST_WORK_QUEUE",
        DEFAULT_COMPACT_RUST_WORK_QUEUE,
    );
    if !env_bool(
        "HLTHPRT_PTG2_RUST_PARSE_IN_WORKERS",
        DEFAULT_PARSE_IN_WORKERS,
    ) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "strict V3 source attestation requires worker-side raw rate parsing",
        ));
    }
    if !copy_paths.has_file_paths() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "strict V3 source attestation requires configured file outputs",
        ));
    }
    let top_level_byte_scan_requested = env_bool(
        "HLTHPRT_PTG2_RUST_TOP_LEVEL_BYTE_SCAN",
        DEFAULT_TOP_LEVEL_BYTE_SCAN,
    );
    let provider_refs_in_workers_requested =
        env_bool("HLTHPRT_PTG2_RUST_PROVIDER_REFS_IN_WORKERS", true);
    let rapidgzip_config = RapidgzipConfig {
        enabled: env_bool("HLTHPRT_PTG2_RUST_RAPIDGZIP_ENABLED", true),
        executable: env::var("HLTHPRT_PTG2_RUST_RAPIDGZIP_BIN")
            .map(PathBuf::from)
            .unwrap_or_else(|_| PathBuf::from("rapidgzip")),
        decoder_threads: env_usize("HLTHPRT_PTG2_RUST_RAPIDGZIP_THREADS", 4),
    };
    let rapidgzip_index_config = RapidgzipConfig {
        enabled: rapidgzip_config.enabled,
        executable: rapidgzip_config.executable.clone(),
        decoder_threads: env_usize(
            "HLTHPRT_PTG2_RUST_RAPIDGZIP_INDEX_THREADS",
            rapidgzip_config
                .decoder_threads
                .saturating_mul(2)
                .min(8)
                .max(rapidgzip_config.decoder_threads),
        ),
    };
    let gzip_input = is_gzip(path)?;
    let use_indexed_reorder = top_level_byte_scan_requested
        && provider_refs_in_workers_requested
        && rapidgzip_config.enabled
        && gzip_input;
    let use_plain_reorder =
        top_level_byte_scan_requested && provider_refs_in_workers_requested && !gzip_input;
    let indexed_range_producers_requested = if use_indexed_reorder {
        indexed_range_producers_requested()?
    } else {
        1
    };
    let indexed_range_producers_selected =
        indexed_range_producers_requested.min(rapidgzip_config.decoder_threads.max(1));
    let provider_reference_preflight = compact_provider_reference_order(
        path,
        use_indexed_reorder,
        use_plain_reorder,
        &rapidgzip_index_config,
        indexed_range_producers_requested,
        indexed_range_producers_selected,
    )?;
    let provider_reference_order_label = provider_reference_preflight.order.label();
    let parallel_top_level_order_supported = matches!(
        &provider_reference_preflight.order,
        CompactProviderReferenceOrder::None
            | CompactProviderReferenceOrder::BeforeInNetwork
            | CompactProviderReferenceOrder::AfterInNetworkIndexed(_)
            | CompactProviderReferenceOrder::AfterInNetworkPlain(_)
    );
    if !top_level_byte_scan_requested
        || !provider_refs_in_workers_requested
        || !parallel_top_level_order_supported
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "strict V3 source attestation requires the parallel top-level byte scanner; provider_reference_order={provider_reference_order_label}"
            ),
        ));
    }
    let (indexed_reorder, plain_reorder) = match provider_reference_preflight.order {
        CompactProviderReferenceOrder::None | CompactProviderReferenceOrder::BeforeInNetwork => {
            (None, None)
        }
        CompactProviderReferenceOrder::AfterInNetworkIndexed(indexed_reorder) => {
            (Some(indexed_reorder), None)
        }
        CompactProviderReferenceOrder::AfterInNetworkPlain(plain_reorder) => {
            (None, Some(plain_reorder))
        }
        _ => unreachable!("parallel top-level order was checked above"),
    };
    scan_compact_byte_top_level_parallel(
        path,
        CompactContext {
            snapshot_id,
            plan_id,
            plan_month_id,
            source_trace_set_hash,
            confidence_code,
            source_witness: Arc::clone(&source_witness),
            invalid_price_exclusion,
        },
        rust_worker_count,
        rust_queue_size,
        copy_paths,
        compact_copy_rotate_bytes,
        CompactByteScanOptions {
            preflight_metrics: provider_reference_preflight.metrics,
            rapidgzip_config,
            indexed_reorder,
            plain_reorder,
        },
    )
}

fn scan_compact(path: &Path) -> io::Result<()> {
    scan_compact_struson(path)
}

fn manifest_copy_key(kind: &str, line: &[u8]) -> Vec<u8> {
    match kind {
        "manifest_lean_serving" => line.strip_suffix(b"\n").unwrap_or(line).to_vec(),
        "price_set_atom" => line.strip_suffix(b"\n").unwrap_or(line).to_vec(),
        "provider_group_member" => {
            let mut tabs_seen = 0;
            for (index, byte) in line.iter().enumerate() {
                if *byte == b'\t' {
                    tabs_seen += 1;
                    if tabs_seen == 2 {
                        return line[..index].to_vec();
                    }
                }
            }
            line.strip_suffix(b"\n").unwrap_or(line).to_vec()
        }
        _ => {
            let end = line
                .iter()
                .position(|byte| *byte == b'\t' || *byte == b'\n')
                .unwrap_or(line.len());
            line[..end].to_vec()
        }
    }
}

fn manifest_serving_trace_is_null(line: &[u8]) -> bool {
    let mut column = 0usize;
    let mut start = 0usize;
    for (index, byte) in line.iter().enumerate() {
        if *byte == b'\t' || *byte == b'\n' {
            if column == 8 {
                return &line[start..index] == b"\\N";
            }
            column += 1;
            start = index + 1;
        }
    }
    column <= 8
}

fn manifest_prefer_row(kind: &str, current: Vec<u8>, candidate: Vec<u8>) -> Vec<u8> {
    if kind == "manifest_serving"
        && manifest_serving_trace_is_null(&current)
        && !manifest_serving_trace_is_null(&candidate)
    {
        return candidate;
    }
    current
}

struct ManifestChunkRow {
    key: Vec<u8>,
    line: Vec<u8>,
}

fn manifest_sort_chunk(
    kind: &str,
    rows: Vec<Vec<u8>>,
    chunk_index: usize,
    temp_dir: &Path,
) -> io::Result<PathBuf> {
    let mut keyed_rows: Vec<ManifestChunkRow> = rows
        .into_iter()
        .map(|line| ManifestChunkRow {
            key: manifest_copy_key(kind, &line),
            line,
        })
        .collect();
    keyed_rows.sort_unstable_by(|left, right| {
        left.key
            .cmp(&right.key)
            .then_with(|| left.line.cmp(&right.line))
    });
    let path = temp_dir.join(format!(
        "ptg2_manifest_merge_{}_{}_{}.chunk",
        kind,
        std::process::id(),
        chunk_index
    ));
    let mut writer = BufWriter::new(File::create(&path)?);
    for row in keyed_rows {
        writer.write_all(&row.line)?;
    }
    writer.flush()?;
    Ok(path)
}

fn manifest_spawn_sort_chunk(
    kind: &str,
    rows: Vec<Vec<u8>>,
    chunk_index: usize,
    temp_dir: &Path,
) -> thread::JoinHandle<io::Result<(usize, PathBuf)>> {
    let kind = kind.to_string();
    let temp_dir = temp_dir.to_path_buf();
    thread::spawn(move || {
        manifest_sort_chunk(&kind, rows, chunk_index, &temp_dir).map(|path| (chunk_index, path))
    })
}

fn manifest_join_sort_chunk(
    handle: thread::JoinHandle<io::Result<(usize, PathBuf)>>,
) -> io::Result<(usize, PathBuf)> {
    match handle.join() {
        Ok(result) => result,
        Err(payload) => Err(io::Error::other(format!(
            "manifest copy merge sort worker panicked: {}",
            panic_payload_message(payload.as_ref())
        ))),
    }
}

fn manifest_flush_sort_handles(
    handles: &mut Vec<thread::JoinHandle<io::Result<(usize, PathBuf)>>>,
    sorted_chunks: &mut Vec<(usize, PathBuf)>,
    max_pending: usize,
) -> io::Result<()> {
    while handles.len() >= max_pending {
        let handle = handles.remove(0);
        sorted_chunks.push(manifest_join_sort_chunk(handle)?);
    }
    Ok(())
}

#[derive(Eq)]
struct ManifestMergeItem {
    key: Vec<u8>,
    line: Vec<u8>,
    reader_index: usize,
}

impl Ord for ManifestMergeItem {
    fn cmp(&self, other: &Self) -> CmpOrdering {
        other
            .key
            .cmp(&self.key)
            .then_with(|| other.line.cmp(&self.line))
            .then_with(|| other.reader_index.cmp(&self.reader_index))
    }
}

impl PartialOrd for ManifestMergeItem {
    fn partial_cmp(&self, other: &Self) -> Option<CmpOrdering> {
        Some(self.cmp(other))
    }
}

impl PartialEq for ManifestMergeItem {
    fn eq(&self, other: &Self) -> bool {
        self.key == other.key && self.line == other.line && self.reader_index == other.reader_index
    }
}

fn manifest_merge_read_next(
    kind: &str,
    reader_index: usize,
    readers: &mut [BufReader<File>],
    heap: &mut BinaryHeap<ManifestMergeItem>,
) -> io::Result<()> {
    let mut line = Vec::new();
    let bytes = readers[reader_index].read_until(b'\n', &mut line)?;
    if bytes > 0 {
        heap.push(ManifestMergeItem {
            key: manifest_copy_key(kind, &line),
            line,
            reader_index,
        });
    }
    Ok(())
}

